# ═══════════════════════════════════════════════════════════════
#  STARTUP BOOTSTRAP — makes "double-click to run" work on any PC.
#  • checks the Python version
#  • installs missing packages automatically (PyQt6, PyQt6-WebEngine, requests, psutil)
#  • shows a visible message (never a silently closing window) if something fails
# ═══════════════════════════════════════════════════════════════
import sys as _bs_sys, os as _bs_os, subprocess as _bs_sp, importlib.util as _bs_iu

def _bs_message(title, text):
    try:
        import tkinter as _tk
        from tkinter import messagebox as _mb
        _r = _tk.Tk(); _r.withdraw()
        _mb.showerror(title, text); _r.destroy()
    except Exception:
        try:
            print("\n" + title + "\n" + text)
            if _bs_os.name == "nt":
                input("\nPress Enter to close...")
        except Exception:
            pass

def _bs_ensure_packages():
    if _bs_sys.version_info < (3, 9):
        _bs_message("SPS Browser", "Python 3.9 or newer is required.\nInstall it from https://www.python.org/downloads/\n(tick 'Add Python to PATH').")
        _bs_sys.exit(1)
    needed = [("PyQt6", "PyQt6"), ("PyQt6.QtWebEngineWidgets", "PyQt6-WebEngine"),
              ("requests", "requests"), ("psutil", "psutil")]
    missing = []
    for mod, pipname in needed:
        try:
            ok = _bs_iu.find_spec(mod) is not None
        except Exception:
            ok = False
        if not ok and pipname not in missing:
            missing.append(pipname)
    if not missing:
        return
    print("SPS Browser: installing missing packages: " + ", ".join(missing))
    exe = _bs_sys.executable
    if exe.lower().endswith("pythonw.exe"):
        exe = exe[:-11] + "python.exe"
    try:
        _bs_sp.check_call([exe, "-m", "pip", "install", "--upgrade"] + missing)
    except Exception:
        try:
            _bs_sp.check_call([exe, "-m", "pip", "install", "--user", "--upgrade"] + missing)
        except Exception:
            _bs_message("SPS Browser - missing packages",
                        "Could not install: " + ", ".join(missing) +
                        "\n\nOpen Command Prompt and run:\n    python -m pip install " + " ".join(missing))
            _bs_sys.exit(1)
    # make sure the freshly installed packages are importable in this run
    try:
        import site as _site, importlib as _il
        _il.invalidate_caches()
        for _d in (_site.getusersitepackages(),):
            if _d and _d not in _bs_sys.path:
                _bs_sys.path.append(_d)
    except Exception:
        pass

if __name__ == "__main__":
    _bs_ensure_packages()

