def _sps_pick_data_root():
    """Find a writable data folder on ANY computer.

    Order of preference (first one that really works wins):
      1) C:\\SPS_Browser\\Users\\<windows user>          (Windows system drive)
      2) %LOCALAPPDATA%\\SPS_Browser\\Users\\<user>      (if C:\\ is write-protected)
      3) ~/SPS_Browser/Users/<user>                       (Linux / macOS)
      4) <temp>/SPS_Browser/Users/<user>                  (last resort)
    Every Windows account gets its OWN sub-folder, so several people can share
    one PC without seeing each other's profiles, history or passwords.
    """
    user = os.environ.get("USERNAME") or os.environ.get("USER") or "user"
    user = re.sub(r"[^A-Za-z0-9_.-]+", "_", user).strip("._") or "user"
    cands = []
    if platform.system() == "Windows":
        cands.append(os.environ.get("SystemDrive", "C:") + "\\SPS_Browser")
        _la = os.environ.get("LOCALAPPDATA")
        if _la:
            cands.append(os.path.join(_la, "SPS_Browser"))
    else:
        cands.append(os.path.join(os.path.expanduser("~"), "SPS_Browser"))
    cands.append(os.path.join(tempfile.gettempdir(), "SPS_Browser"))
    for root in cands:
        try:
            data = os.path.join(root, "Users", user)
            os.makedirs(data, exist_ok=True)
            probe = os.path.join(data, ".write_test")
            with open(probe, "w") as _f:
                _f.write("ok")
            os.remove(probe)
            return root, data
        except Exception:
            continue
    data = os.path.join(os.path.expanduser("~"), ".sps_browser")
    os.makedirs(data, exist_ok=True)
    return data, data

APP_ROOT_DIR, BASE_DATA_DIR = _sps_pick_data_root()      # e.g. C:\SPS_Browser  and  C:\SPS_Browser\Users\<you>
PROFILES_DIR     = os.path.join(BASE_DATA_DIR, "profiles")
EXTENSIONS_DIR   = os.path.join(BASE_DATA_DIR, "extensions")
