class LockdownBanner(QFrame):
    """Red alert banner displayed when lockdown_mode is active."""
    unlock_requested = pyqtSignal()
    def __init__(self, reason="Security lockdown active", parent=None):
        super().__init__(parent)
        self.setStyleSheet("QFrame{background:#b71c1c;color:white;}")
        self.setFixedHeight(42)
        lay = QHBoxLayout(self)
        lay.setContentsMargins(12, 4, 12, 4)
        lay.addWidget(QLabel("🔒"))
        msg = QLabel(f"<b>SECURITY LOCKDOWN</b>  {reason[:120]}")
        msg.setStyleSheet("font-size:13px;color:white;")
        lay.addWidget(msg, 1)
        btn = QPushButton("🔓 Unlock")
        btn.setStyleSheet(
            "background:white;color:#b71c1c;border-radius:6px;"
            "padding:3px 12px;font-weight:700;"
        )
        btn.clicked.connect(self.unlock_requested.emit)
        lay.addWidget(btn)

