# Pattern-based detection — covers millions of variants efficiently
# Each pattern is compiled once at startup
_CRYPTO_SCAM_RAW_PATTERNS = [
    '(?:airdrop|giveaway|claim|gift|bonus|reward|drop)\\.(com|net|io|xyz|vip|top|pro|cc|site|online|live|club)',
    '(?:free|earn|win)[-_]?(?:bitcoin|btc|eth|crypto|usdt|bnb|sol|xrp|doge|shib)',
    '(?:bitcoin|btc|eth|ethereum|crypto|usdt|bnb|sol)[-_]?(?:free|gift|earn|claim|airdrop|bonus|giveaway|reward|doubler|multiplier)',
    'double[-_]?(?:bitcoin|btc|eth|crypto|usdt)',
    '(?:bitcoin|btc|eth|crypto)[-_]?(?:mining|miner|mine)[-_]?(?:pro|cloud|pool|easy|fast|quick)',
    '(?:metamask|trustwallet|phantom|ledger|trezor|exodus|coinbase[-_]wallet)[-_.](?:support|recover|help|connect|login|signin|app|io|com|net)',
    '(?:wallet|crypto)[-_.](?:recover|recovery|restore|support|help|connect)',
    '(?:binance|coinbase|kraken|kucoin|bybit|okx|huobi|bitget|mexc|gate[-_]?io)[-_](?:pro|earn|gift|airdrop|vip|bonus|official|real|true|secure|login|signin|support|help|wallet|app|exchange|trade)',
    '(?:binannce|coinbse|krakken|bynance|binanace|b1nance|c0inbase|co1nbase)',
    '(?:uniswap|pancakeswap|sushiswap|aave|compound|curve|1inch|yearn)[-_.](?:airdrop|claim|earn|gift|bonus|pro|vip|official|io|app|defi|finance)',
    '(?:opensea|rarible|foundation|superrare|niftygateway)[-_.](?:mint|claim|airdrop|drop|free|gift|official|io|app|nft)',
    '(?:free|claim|mint|drop)[-_.]?nft',
    '(?:crypto|bitcoin|btc|eth)[-_.](?:invest|profit|robot|trader|bot|auto|ai|signal|tip)',
    '(?:investment|profit|return|yield|interest|passive)[-_.]?(?:crypto|bitcoin|btc|eth)',
    '(?:high|fast|quick|instant|guaranteed)[-_.]?(?:return|profit|gain|yield)[-_.]?(?:crypto|bitcoin|btc)',
    '(?:js|web|browser|coin|btc|eth|xmr|monero)[-_.]?(?:mine|miner|mining|hash|hashrate)',
    '(?:mining|miner)[-_.](?:pool|cloud|farm|pro|fast|easy|simple|online|web)',
    '(?:crypto|bitcoin|blockchain|wallet|defi|nft)[-_.](?:helpdesk|support|help|service|center|desk)',
    '(?:elon|musk|tesla|spacex)[-_.]?(?:crypto|bitcoin|btc|eth|give|giveaway|gift|bonus)',
    '(?:vitalik|buterin|satoshi|nakamoto)[-_.]?(?:crypto|bitcoin|eth|give|giveaway|gift|bonus)',
    '(?:signin|login|account|verify|secure|auth|confirm|validate|update|kyc|2fa)[-_.](?:crypto|bitcoin|blockchain|wallet|defi)',
]

# Pre-compiled for performance
_CRYPTO_SCAM_COMPILED = [_re.compile(p, _re.IGNORECASE) for p in _CRYPTO_SCAM_RAW_PATTERNS]

def is_crypto_scam_domain(host: str) -> bool:
    """Return True if host matches a known crypto scam domain or pattern."""
    host = (host or "").lower().strip(".")
    if not host: return False
    # 1. Exact match (O(1))
    if host in CRYPTO_SCAM_DOMAINS_EXACT: return True
    # 2. Check subdomain (strip www. etc)
    parts = host.split(".")
    # 3. Pattern match on full host
    for pat in _CRYPTO_SCAM_COMPILED:
        if pat.search(host): return True
    return False


