class SitePermissionStore:
    """Remembers per-site Allow/Block decisions (only when the user ticks 'Remember')."""
    def __init__(self, profile_path):
        self.path = os.path.join(profile_path, "site_permissions.json")
        self.data = {}
        try:
            if os.path.exists(self.path):
                with open(self.path, encoding="utf-8") as f:
                    d = json.load(f)
                if isinstance(d, dict):
                    self.data = d
        except Exception:
            self.data = {}

    def _save(self):
        try:
            with open(self.path, "w", encoding="utf-8") as f:
                json.dump(self.data, f, indent=2)
        except Exception:
            pass

    @staticmethod
    def _site(origin):
        try:
            u = QUrl(origin)
            return (u.host() or str(origin)).lower()
        except Exception:
            return str(origin).lower()

    def get(self, origin, key):
        return self.data.get(self._site(origin), {}).get(key)

    def set(self, origin, key, decision):
        self.data.setdefault(self._site(origin), {})[key] = decision
        self._save()

    def remove(self, site, key):
        if site in self.data and key in self.data[site]:
            del self.data[site][key]
            if not self.data[site]:
                del self.data[site]
            self._save()

    def clear(self):
        self.data = {}
        self._save()

    def items(self):
        out = []
        for site, feats in sorted(self.data.items()):
            for key, dec in sorted(feats.items()):
                out.append((site, key, dec))
        return out


