class PermissionPrompt(QDialog):
    """Friendly 'site wants to …' dialog.  result_choice: 'allow' or 'deny'."""
    def __init__(self, theme, site, key, extra="", can_remember=True, parent=None):
        super().__init__(parent)
        t = theme
        icon, text = PERMISSION_LABELS.get(key, ("❓", "do something on your computer"))
        self.result_choice = "deny"
        self.setWindowTitle("Permission request")
        self.setModal(True)
        self.setFixedWidth(430)
        self.setStyleSheet(
            f"QDialog{{background:{t['bg_primary']};}}"
            f"QLabel{{color:{t['text_primary']};background:transparent;}}"
            f"QCheckBox{{color:{t['text_secondary']};font-size:12px;spacing:8px;}}")
        lay = QVBoxLayout(self); lay.setContentsMargins(26, 24, 26, 20); lay.setSpacing(10)
        badge = QLabel(icon); badge.setAlignment(Qt.AlignmentFlag.AlignCenter)
        badge.setFixedSize(64, 64)
        badge.setStyleSheet(f"font-size:30px;background:{t['accent_light']};border-radius:32px;")
        lay.addWidget(badge, alignment=Qt.AlignmentFlag.AlignHCenter)
        title = QLabel(f"<b>{html.escape(site or 'This page')}</b><br>wants to {html.escape(text)}")
        title.setAlignment(Qt.AlignmentFlag.AlignCenter); title.setWordWrap(True)
        title.setStyleSheet("font-size:16px;")
        lay.addWidget(title)
        if extra:
            ex = QLabel(html.escape(extra)); ex.setWordWrap(True)
            ex.setAlignment(Qt.AlignmentFlag.AlignCenter)
            ex.setStyleSheet(f"color:{t['text_secondary']};font-size:12px;")
            lay.addWidget(ex)
        note = QLabel("🔒 SPS Browser never lets a website do this without asking you first.")
        note.setWordWrap(True); note.setAlignment(Qt.AlignmentFlag.AlignCenter)
        note.setStyleSheet(f"color:{t['text_secondary']};font-size:11px;padding:4px 0 2px 0;")
        lay.addWidget(note)
        self.remember = QCheckBox("Remember my choice for this site")
        self.remember.setVisible(can_remember)
        lay.addWidget(self.remember, alignment=Qt.AlignmentFlag.AlignHCenter)
        row = QHBoxLayout(); row.setSpacing(10)
        block = QPushButton("Block")
        allow = QPushButton("Allow")
        block.setCursor(Qt.CursorShape.PointingHandCursor); allow.setCursor(Qt.CursorShape.PointingHandCursor)
        block.setStyleSheet(
            f"QPushButton{{background:{t['bg_secondary']};color:{t['text_primary']};border:1px solid {t['border']};"
            f"border-radius:10px;padding:11px 0;font-weight:700;font-size:13px;}}"
            f"QPushButton:hover{{background:{t['hover']};}}")
        allow.setStyleSheet(
            f"QPushButton{{background:{t['accent']};color:white;border:none;"
            f"border-radius:10px;padding:11px 0;font-weight:700;font-size:13px;}}"
            f"QPushButton:hover{{background:{_darken(t['accent'], 18)};}}")
        block.clicked.connect(self._block); allow.clicked.connect(self._allow)
        row.addWidget(block, 1); row.addWidget(allow, 1)
        lay.addLayout(row)
        block.setDefault(True)

    def _allow(self):
        self.result_choice = "allow"; self.accept()

    def _block(self):
        self.result_choice = "deny"; self.reject()


def ask_site_permission(main_window, site, key, extra="", store_origin=None, remember_ok=True):
    """Return True if the user allows `key` for `site`.  Honors remembered choices and
    Content-Policy auto-blocks.  Never allows anything silently."""
    mw = main_window
    s = getattr(mw, "settings_data", {}) or {}
    for pol in _PERMISSION_POLICY_KEYS.get(key, ()):
        if s.get(pol, False):
            return False
    if key == "download" and s.get("lockdown_block_all_downloads"):
        return False
    store = getattr(mw, "permission_store", None)
    if store is not None and store_origin and remember_ok:
        saved = store.get(store_origin, key)
        if saved == "allow":
            return True
        if saved == "deny":
            return False
    dlg = PermissionPrompt(mw._theme, site, key, extra, can_remember=bool(store is not None and store_origin and remember_ok), parent=mw)
    dlg.exec()
    allowed = dlg.result_choice == "allow"
    if store is not None and store_origin and remember_ok and dlg.remember.isChecked():
        store.set(store_origin, key, "allow" if allowed else "deny")
    return allowed


class SitePermissionsDialog(QDialog):
    """View / revoke remembered site permissions."""
    def __init__(self, store, theme, parent=None):
        super().__init__(parent)
        self.store = store; t = theme
        self.setWindowTitle("🛡️ Site Permissions"); self.resize(560, 460)
        self.setStyleSheet(f"QDialog{{background:{t['bg_primary']};}}QLabel{{color:{t['text_primary']};}}")
        lay = QVBoxLayout(self); lay.setContentsMargins(20, 18, 20, 16)
        h = QLabel("🛡️ Site Permissions"); h.setStyleSheet(f"font-size:20px;font-weight:700;color:{t['accent']};")
        lay.addWidget(h)
        sub = QLabel("Choices you asked SPS Browser to remember. Anything not listed here is always asked first.")
        sub.setWordWrap(True); sub.setStyleSheet(f"color:{t['text_secondary']};font-size:12px;padding-bottom:6px;")
        lay.addWidget(sub)
        self.listw = QListWidget(); lay.addWidget(self.listw, 1)
        row = QHBoxLayout()
        rm = QPushButton("Remove selected"); rm.clicked.connect(self._remove)
        ra = QPushButton("Reset all"); ra.clicked.connect(self._reset)
        for b, c in ((rm, t['bg_secondary']), (ra, t['danger'])):
            fg = t['text_primary'] if c == t['bg_secondary'] else "white"
            b.setStyleSheet(f"QPushButton{{background:{c};color:{fg};border-radius:8px;padding:8px 16px;font-weight:600;}}")
        row.addWidget(rm); row.addWidget(ra); row.addStretch()
        cl = QPushButton("Close"); cl.clicked.connect(self.accept)
        cl.setStyleSheet(f"QPushButton{{background:{t['accent']};color:white;border-radius:8px;padding:8px 20px;font-weight:700;}}")
        row.addWidget(cl); lay.addLayout(row)
        self._fill()

    def _fill(self):
        self.listw.clear()
        for site, key, dec in self.store.items():
            icon, text = PERMISSION_LABELS.get(key, ("❓", key))
            it = QListWidgetItem(f"{icon}  {site}  —  {'✅ allowed' if dec == 'allow' else '🚫 blocked'}: {text}")
            it.setData(Qt.ItemDataRole.UserRole, (site, key))
            self.listw.addItem(it)
        if not self.listw.count():
            self.listw.addItem("No remembered permissions — sites always have to ask.")

    def _remove(self):
        for it in self.listw.selectedItems():
            d = it.data(Qt.ItemDataRole.UserRole)
            if d: self.store.remove(*d)
        self._fill()

    def _reset(self):
        self.store.clear(); self._fill()


