# ═══════════════════════════════════════════════════════════════
# Hosts that are always allowed through the ad/tracker/phishing heuristics.
_TRUSTED_HOST_SUFFIXES = ("duckduckgo.com", "gstatic.com", "spscompany-rikdev.github.io")
_TRUSTED_EXACT_HOSTS   = ("google.com", "www.google.com")

def _is_trusted_host(host):
    return host in _TRUSTED_EXACT_HOSTS or _host_matches(host, _TRUSTED_HOST_SUFFIXES)
_TWO_LEVEL_SLD = {"co", "com", "org", "net", "gov", "edu", "ac"}
_PHISH_PATTERNS = [
    (re.compile(r"paypa[l1][\-\.]", re.I),       "paypal"),
    (re.compile(r"app[l1]e[\-\.]id", re.I),      "apple"),
    (re.compile(r"go+gle[\-\.]", re.I),          "google"),
    (re.compile(r"amaz[o0]n[\-\.]", re.I),       "amazon"),
    (re.compile(r"micr[o0]s[o0]ft[\-\.]", re.I), "microsoft"),
    (re.compile(r"netfl[i1]x[\-\.]", re.I),      "netflix"),
    (re.compile(r"fac[e3]bo[o0]k[\-\.]", re.I),  "facebook"),
]
_KNOWN_GOOD_BRAND_DOMAINS = (
    "google-analytics.com", "amazon-adsystem.com", "paypal-community.com",
    "facebook-hardware.com",
)

def _host_matches(host, suffixes):
    return any(host == d or host.endswith("." + d) for d in suffixes)

def _registrable(host):
    parts = host.split(".")
    if len(parts) < 2:
        return host, host
    if len(parts) >= 3 and parts[-2] in _TWO_LEVEL_SLD and len(parts[-1]) == 2:
        return parts[-3], ".".join(parts[-3:])
    return parts[-2], ".".join(parts[-2:])

def looks_like_phishing(host):
    """True only for look-alike hosts (paypal-login.com, google.evil.ru …).
    The real brand domains (google.com, google.co.in, amazon.in …) are never flagged."""
    host = (host or "").lower().strip(".")
    if not host or _host_matches(host, _KNOWN_GOOD_BRAND_DOMAINS):
        return False
    if host.endswith(".translate.goog"):
        # V36: Google Translate shows "www.google.com" as "www-google-com.translate.goog" - judge the REAL site behind it,
        # otherwise translating google/amazon/paypal pages was blocked as "phishing".
        orig = host[:-len(".translate.goog")].replace("--", "\x00").replace("-", ".").replace("\x00", "-")
        return looks_like_phishing(orig)
    label, _reg = _registrable(host)
    for rx, brand in _PHISH_PATTERNS:
        if rx.search(host + "."):
            if label == brand:
                continue
            return True
    return False


