def sps_translate_url(qurl, target="en"):
    """https://www.example.com/a?b=1  ->  https://www-example-com.translate.goog/a?b=1&_x_tr_sl=auto&_x_tr_tl=en&_x_tr_hl=en"""
    try:
        if not isinstance(qurl, QUrl): qurl = QUrl(str(qurl))
        if qurl.scheme().lower() not in ("http", "https") or not qurl.host():
            return ""
        host = qurl.host()
        if host.endswith(".translate.goog"):
            return ""
        # a literal "-" in a host becomes "--", every "." becomes "-"  (that is how translate.goog names its mirrors)
        thost = host.replace("-", "--").replace(".", "-") + ".translate.goog"
        if qurl.port() not in (-1, 80, 443):
            thost = thost.replace(".translate.goog", "") + f"-{qurl.port()}.translate.goog"
        path = qurl.path() or "/"
        q = qurl.query()
        extra = f"_x_tr_sl=auto&_x_tr_tl={quote_plus(target)}&_x_tr_hl={quote_plus(target)}&_x_tr_pto=wapp"
        frag = ("#" + qurl.fragment()) if qurl.hasFragment() else ""
        return f"https://{thost}{path}?" + (q + "&" if q else "") + extra + frag
    except Exception:
        return ""

def sps_lens_search_pixmap(main_window, pixmap, hint="screenshot"):
    """Upload a picture to Google Lens: write a tiny local page that POSTs it (what the Lens upload button does)."""
    import base64, tempfile
    from PyQt6.QtCore import QBuffer, QIODevice
    pm = pixmap
    if pm.width() > 1600:
        pm = pm.scaledToWidth(1600, Qt.TransformationMode.SmoothTransformation)
    buf = QBuffer(); buf.open(QIODevice.OpenModeFlag.WriteOnly)
    pm.save(buf, "JPEG", 88)
    b64 = base64.b64encode(bytes(buf.data())).decode("ascii")
    page = ("<!doctype html><meta charset='utf-8'><title>Google Lens</title>"
            "<body style='font-family:Segoe UI,sans-serif;background:#fff;color:#202124;text-align:center;padding-top:90px'>"
            "<h2>🔍 Opening Google Lens…</h2><p>Sending the picture to Google Lens.</p>"
            "<form id='f' method='POST' enctype='multipart/form-data' action='https://lens.google.com/v3/upload?hl=en&ep=ccm&s=&st=" + str(int(time.time()*1000)) + "'>"
            "<input type='file' name='encoded_image' id='i' style='display:none'></form>"
            "<script>try{var bin=atob('" + b64 + "'),u=new Uint8Array(bin.length);for(var k=0;k<bin.length;k++)u[k]=bin.charCodeAt(k);"
            "var dt=new DataTransfer();dt.items.add(new File([u],'" + hint + ".jpg',{type:'image/jpeg'}));"
            "document.getElementById('i').files=dt.files;document.getElementById('f').submit();}catch(e){document.body.innerHTML='<h3>Could not send the picture: '+e+'</h3>';}</script>")
    fd, path = tempfile.mkstemp(suffix=".html", prefix="sps_lens_"); os.close(fd)
    with open(path, "w", encoding="utf-8") as f: f.write(page)
    main_window.add_new_tab(QUrl.fromLocalFile(path), "🔍 Google Lens")
    QTimer.singleShot(120000, lambda: os.path.exists(path) and os.remove(path))

