SPS_NATIVE_VIDEO_EXTS = {".mp4", ".m4v", ".mov", ".mkv", ".avi", ".wmv", ".flv", ".ts", ".mts", ".m2ts", ".3gp", ".mpg", ".mpeg"}

try:
    from PyQt6.QtMultimedia import QMediaPlayer, QAudioOutput
    from PyQt6.QtMultimediaWidgets import QVideoWidget
    SPS_HAVE_MULTIMEDIA = True
except Exception:
    SPS_HAVE_MULTIMEDIA = False

def _sps_fmt_ms(ms):
    s = max(0, int(ms // 1000)); h, r = divmod(s, 3600); m, sec = divmod(r, 60)
    return f"{h}:{m:02d}:{sec:02d}" if h else f"{m}:{sec:02d}"

if SPS_HAVE_MULTIMEDIA:
    class SpsVideoWindow(QWidget):
        """Small, self-contained player window: play/pause, seek, volume, speed, full screen."""
        def __init__(self, path, parent=None):
            super().__init__(None)
            self.path = path
            self._main = parent
            self.setWindowTitle("▶ " + os.path.basename(path))
            self.setAttribute(Qt.WidgetAttribute.WA_DeleteOnClose, True)
            self.resize(960, 600)
            self.setStyleSheet("QWidget{background:#000;color:#eee;font-family:'Segoe UI';}"
                               "QPushButton{background:#222;border:1px solid #444;border-radius:6px;padding:5px 12px;font-size:14px;}"
                               "QPushButton:hover{background:#333;}"
                               "QComboBox{background:#222;border:1px solid #444;border-radius:6px;padding:3px 8px;}"
                               "QSlider::groove:horizontal{height:5px;background:#444;border-radius:2px;}"
                               "QSlider::sub-page:horizontal{background:#1a73e8;border-radius:2px;}"
                               "QSlider::handle:horizontal{width:14px;margin:-5px 0;background:#fff;border-radius:7px;}")
            self.video = QVideoWidget(self)
            self.player = QMediaPlayer(self)
            self.audio = QAudioOutput(self)
            self.player.setAudioOutput(self.audio)
            self.player.setVideoOutput(self.video)
            self.audio.setVolume(0.8)

            self.play_btn = QPushButton("⏸"); self.play_btn.setFixedWidth(46)
            self.play_btn.clicked.connect(self.toggle_play)
            self.pos_lbl = QLabel("0:00"); self.dur_lbl = QLabel("0:00")
            self.seek = QSlider(Qt.Orientation.Horizontal); self.seek.setRange(0, 0)
            self.seek.sliderMoved.connect(self.player.setPosition)
            self.seek.sliderPressed.connect(lambda: self.player.setPosition(self.seek.value()))
            self.mute_btn = QPushButton("🔊"); self.mute_btn.setFixedWidth(46)
            self.mute_btn.clicked.connect(self._toggle_mute)
            self.vol = QSlider(Qt.Orientation.Horizontal); self.vol.setRange(0, 100); self.vol.setValue(80); self.vol.setFixedWidth(90)
            self.vol.valueChanged.connect(lambda v: self.audio.setVolume(v / 100.0))
            self.speed = QComboBox()
            for sp in ("0.5x", "0.75x", "1x", "1.25x", "1.5x", "2x"): self.speed.addItem(sp)
            self.speed.setCurrentText("1x")
            self.speed.currentTextChanged.connect(lambda t: self.player.setPlaybackRate(float(t.rstrip("x"))))
            self.fs_btn = QPushButton("⛶"); self.fs_btn.setFixedWidth(46)
            self.fs_btn.clicked.connect(self.toggle_fullscreen)

            self.bar = QWidget(self)
            bl = QHBoxLayout(self.bar); bl.setContentsMargins(10, 6, 10, 8); bl.setSpacing(8)
            for w_ in (self.play_btn, self.pos_lbl, self.seek, self.dur_lbl, self.mute_btn, self.vol, self.speed, self.fs_btn):
                bl.addWidget(w_, 1 if w_ is self.seek else 0)
            lay = QVBoxLayout(self); lay.setContentsMargins(0, 0, 0, 0); lay.setSpacing(0)
            lay.addWidget(self.video, 1); lay.addWidget(self.bar)

            self.player.positionChanged.connect(self._on_pos)
            self.player.durationChanged.connect(lambda d: (self.seek.setRange(0, d), self.dur_lbl.setText(_sps_fmt_ms(d))))
            self.player.playbackStateChanged.connect(lambda st: self.play_btn.setText("⏸" if st == QMediaPlayer.PlaybackState.PlayingState else "▶"))
            self.player.errorOccurred.connect(self._on_error)
            self.video.setFocusPolicy(Qt.FocusPolicy.StrongFocus)
            self.setFocusPolicy(Qt.FocusPolicy.StrongFocus)
            self.player.setSource(QUrl.fromLocalFile(path))
            self.player.play()

        def _on_pos(self, p):
            if not self.seek.isSliderDown(): self.seek.setValue(p)
            self.pos_lbl.setText(_sps_fmt_ms(p))

        def _toggle_mute(self):
            self.audio.setMuted(not self.audio.isMuted()); self.mute_btn.setText("🔇" if self.audio.isMuted() else "🔊")

        def toggle_play(self):
            if self.player.playbackState() == QMediaPlayer.PlaybackState.PlayingState: self.player.pause()
            else: self.player.play()

        def toggle_fullscreen(self):
            if self.isFullScreen():
                self.bar.show(); self.showNormal()
            else:
                self.bar.hide(); self.showFullScreen()

        def _on_error(self, err, msg=""):
            try:
                self.player.pause()
                r = QMessageBox.question(self, "Cannot play this file",
                    f"This file could not be played here:\n{msg or err}\n\nOpen it with your computer's default media player instead?")
                if r == QMessageBox.StandardButton.Yes:
                    QDesktopServices.openUrl(QUrl.fromLocalFile(self.path))
                self.close()
            except RuntimeError:
                pass

        def mouseDoubleClickEvent(self, e): self.toggle_fullscreen()

        def keyPressEvent(self, e):
            k = e.key()
            if k == Qt.Key.Key_Space: self.toggle_play()
            elif k in (Qt.Key.Key_F, Qt.Key.Key_F11): self.toggle_fullscreen()
            elif k == Qt.Key.Key_Escape and self.isFullScreen(): self.toggle_fullscreen()
            elif k == Qt.Key.Key_Left: self.player.setPosition(max(0, self.player.position() - 5000))
            elif k == Qt.Key.Key_Right: self.player.setPosition(self.player.position() + 5000)
            elif k == Qt.Key.Key_Up: self.vol.setValue(min(100, self.vol.value() + 5))
            elif k == Qt.Key.Key_Down: self.vol.setValue(max(0, self.vol.value() - 5))
            else: super().keyPressEvent(e)

        def closeEvent(self, e):
            try: self.player.stop()
            except Exception: pass
            super().closeEvent(e)

def sps_open_local_video(main_window, path):
    """Open a local video in the built-in player. Returns True when handled."""
    if not SPS_HAVE_MULTIMEDIA or not os.path.isfile(path):
        return False
    try:
        win = SpsVideoWindow(path, main_window)
        lst = getattr(main_window, "_v35_players", None)
        if lst is None:
            lst = main_window._v35_players = []
        lst.append(win)
        win.destroyed.connect(lambda *_a, w=win: lst.remove(w) if w in lst else None)
        win.show(); win.raise_(); win.activateWindow(); win.setFocus()
        return True
    except Exception:
        return False

