def _dl_size(b):
    try: b = float(b)
    except Exception: return "?"
    if b < 0: return "?"
    for u in ("B", "KB", "MB", "GB", "TB"):
        if b < 1024 or u == "TB":
            return f"{int(b)} B" if u == "B" else f"{b:.1f} {u}"
        b /= 1024.0

def _dl_dur(sec):
    sec = int(max(sec, 0)); h, r = divmod(sec, 3600); m, s = divmod(r, 60)
    return f"{h}h {m:02d}m" if h else (f"{m}m {s:02d}s" if m else f"{s}s")

