class _DlSpeedGraph(QWidget):
    """Tiny live bar-graph of total download speed (last 60 s)."""
    def __init__(self, theme, parent=None):
        super().__init__(parent)
        self.setFixedHeight(40); self._pts = [0.0] * 60
        self._acc = QColor(theme["accent"]); self._bg = QColor(theme["bg_secondary"])
    def push(self, v):
        self._pts.append(float(max(v, 0))); self._pts = self._pts[-60:]; self.update()
    def paintEvent(self, _e):
        p = QPainter(self)
        try:
            w, h = self.width(), self.height()
            p.fillRect(0, 0, w, h, self._bg)
            mx = max(max(self._pts), 1.0); n = len(self._pts); bw = max(w / n, 1.0)
            c = QColor(self._acc)
            for i, v in enumerate(self._pts):
                bh = int((v / mx) * (h - 4))
                if bh <= 0: continue
                c.setAlpha(90 + int(150 * i / n))
                p.fillRect(QRect(int(i * bw), h - bh, max(int(bw) - 1, 1), bh), c)
        finally:
            p.end()

class DownloadItemWidget(QFrame):
    ACTIVE, PAUSED, DONE, FAILED, CANCELLED = "active", "paused", "done", "failed", "cancelled"

    def __init__(self, download, theme, manager, record=None):
        super().__init__(manager.container if manager else None)
        self.download = download; self.theme = theme; self.manager = manager
        self._conns = []; self.speed = 0.0
        self._last_bytes = 0; self._last_t = time.time(); self._start = time.time()
        self.private = False; self.error = ""
        if download is not None:
            self.kind = self.ACTIVE
            self.name = download.downloadFileName() or "download"
            self.dir = download.downloadDirectory() or ""
            try: self.url = download.url().toString()
            except Exception: self.url = ""
            self.total = max(download.totalBytes(), 0); self.received = max(download.receivedBytes(), 0)
            self.when = time.time()
            try:
                pg = download.page()
                self.private = bool(pg and pg.profile().isOffTheRecord())
            except Exception: pass
        else:
            r = record or {}
            self.kind = r.get("state", self.DONE)
            self.name = r.get("name", "download"); self.dir = r.get("dir", ""); self.url = r.get("url", "")
            self.total = int(r.get("size", 0) or 0); self.received = self.total
            self.when = float(r.get("time", time.time()) or time.time())
        self.setObjectName("dlItem")
        self._build_ui()
        if download is not None:
            download.stateChanged.connect(self._state_changed); self._conns.append((download.stateChanged, self._state_changed))
        self._refresh_final_or_live()

    # ── helpers ──
    @property
    def path(self): return os.path.join(self.dir, self.name) if self.dir else self.name
    def is_live(self): return self.kind in (self.ACTIVE, self.PAUSED)
    def is_finished(self): return not self.is_live()
    def matches(self, flt, text):
        if flt == "active" and not self.is_live(): return False
        if flt == "done" and self.kind != self.DONE: return False
        if flt == "failed" and self.kind not in (self.FAILED, self.CANCELLED): return False
        t = (text or "").strip().lower()
        return not t or t in self.name.lower() or t in self.url.lower()
    def to_record(self):
        return {"name": self.name, "dir": self.dir, "url": self.url, "size": int(self.total or self.received or 0),
                "state": self.kind, "time": self.when}
    def cleanup(self):
        for sig, slot in self._conns:
            try: sig.disconnect(slot)
            except Exception: pass
        self._conns = []

    # ── UI ──
    def _build_ui(self):
        t = self.theme; acc = t["accent"]
        self.setStyleSheet(
            f"#dlItem{{background:{t['bg_primary']};border-bottom:1px solid {t['border']};}}"
            f"#dlItem QLabel{{background:transparent;}}"
            f"#dlItem QPushButton{{background:{t['bg_secondary']};color:{t['text_primary']};border:1px solid {t['border']};"
            f"border-radius:8px;padding:4px 12px;font-size:12px;font-weight:600;}}"
            f"#dlItem QPushButton:hover{{background:{t['hover']};border-color:{acc};}}"
            f"#dlItem QPushButton:disabled{{color:{t['text_secondary']};}}")
        outer = QVBoxLayout(self); outer.setContentsMargins(14, 10, 14, 10); outer.setSpacing(6)
        top = QHBoxLayout(); top.setSpacing(10)
        self.icon_lbl = QLabel("📥"); self.icon_lbl.setFixedSize(36, 36)
        self.icon_lbl.setAlignment(Qt.AlignmentFlag.AlignCenter)
        self.icon_lbl.setStyleSheet(f"font-size:21px;background:{acc}22;border-radius:10px;")
        top.addWidget(self.icon_lbl)
        col = QVBoxLayout(); col.setSpacing(1)
        self.name_lbl = QLabel(self.name)
        self.name_lbl.setStyleSheet(f"font-weight:700;font-size:13px;color:{t['text_primary']};")
        self.url_lbl = QLabel(self.url[:90] + ("…" if len(self.url) > 90 else ""))
        self.url_lbl.setStyleSheet(f"font-size:10px;color:{t['text_secondary']};")
        self.url_lbl.setToolTip(self.url)
        self.status_lbl = QLabel("⏳ Connecting…")
        self.status_lbl.setStyleSheet(f"font-size:11px;color:{t['text_secondary']};")
        for w in (self.name_lbl, self.url_lbl, self.status_lbl): col.addWidget(w)
        top.addLayout(col, 1)
        self.speed_lbl = QLabel(""); self.speed_lbl.setMinimumWidth(90)
        self.speed_lbl.setAlignment(Qt.AlignmentFlag.AlignRight | Qt.AlignmentFlag.AlignVCenter)
        self.speed_lbl.setStyleSheet(f"font-size:12px;font-weight:700;color:{acc};")
        top.addWidget(self.speed_lbl)
        outer.addLayout(top)
        self.bar = QProgressBar(); self.bar.setRange(0, 1000); self.bar.setFixedHeight(7); self.bar.setTextVisible(False)
        self._bar_style(acc)
        outer.addWidget(self.bar)
        row = QHBoxLayout(); row.setSpacing(6)
        self.pause_btn = QPushButton("⏸ Pause");   self.pause_btn.clicked.connect(self._toggle_pause)
        self.cancel_btn = QPushButton("✕ Cancel"); self.cancel_btn.clicked.connect(self._cancel)
        self.cancel_btn.setStyleSheet(f"color:{t['danger']};")
        self.open_btn = QPushButton("📂 Open");    self.open_btn.clicked.connect(self._open_file)
        self.folder_btn = QPushButton("🗂 Show in folder"); self.folder_btn.clicked.connect(self._open_folder)
        self.retry_btn = QPushButton("🔁 Retry");  self.retry_btn.clicked.connect(self._retry)
        self.more_btn = QPushButton("⋯"); self.more_btn.setFixedWidth(34); self.more_btn.clicked.connect(self._more_menu)
        for b in (self.pause_btn, self.cancel_btn, self.open_btn, self.folder_btn, self.retry_btn, self.more_btn):
            b.setCursor(Qt.CursorShape.PointingHandCursor); row.addWidget(b)
        row.addStretch(); outer.addLayout(row)

    def _bar_style(self, color):
        t = self.theme
        self.bar.setStyleSheet(
            f"QProgressBar{{background:{t['bg_tertiary']};border:none;border-radius:3px;}}"
            f"QProgressBar::chunk{{background:{color};border-radius:3px;}}")

    def _set_icon(self):
        ext = os.path.splitext(self.name)[1].lower()
        self.icon_lbl.setText(_DL_ICONS.get(ext, "📥"))

    def _refresh_buttons(self):
        live = self.is_live(); done = self.kind == self.DONE
        exists = done and os.path.isfile(self.path)
        self.pause_btn.setVisible(live and self.download is not None)
        self.cancel_btn.setVisible(live and self.download is not None)
        self.open_btn.setVisible(exists); self.folder_btn.setVisible(done and bool(self.dir))
        self.retry_btn.setVisible(self.kind in (self.FAILED, self.CANCELLED) and bool(self.url))
        self.pause_btn.setText("▶ Resume" if self.kind == self.PAUSED else "⏸ Pause")

    def _refresh_final_or_live(self):
        t = self.theme; self._set_icon(); self.name_lbl.setText(self.name)
        if self.kind == self.DONE:
            ok = os.path.isfile(self.path)
            when = datetime.datetime.fromtimestamp(self.when).strftime("%d %b %Y, %H:%M")
            self.status_lbl.setText(f"✅ {_dl_size(self.total)}  •  {when}" if ok else f"⚠️ File moved or deleted  •  {when}")
            self.status_lbl.setStyleSheet(f"font-size:11px;font-weight:600;color:{t['success'] if ok else t['warning']};")
            self.bar.setValue(1000); self._bar_style(t["success"]); self.speed_lbl.setText("")
        elif self.kind == self.CANCELLED:
            self.status_lbl.setText("❌ Cancelled"); self.status_lbl.setStyleSheet(f"font-size:11px;color:{t['danger']};")
            self.bar.setValue(0); self.speed_lbl.setText("")
        elif self.kind == self.FAILED:
            self.status_lbl.setText("⚠️ " + (self.error or "Failed / interrupted"))
            self.status_lbl.setStyleSheet(f"font-size:11px;color:{t['warning']};"); self.speed_lbl.setText("")
        self._refresh_buttons()

    # ── live updates (called once a second by the manager) ──
    def tick(self):
        d = self.download
        if d is None or not self.is_live(): return
        try:
            pos = d.receivedBytes(); total = d.totalBytes(); paused = d.isPaused(); nm = d.downloadFileName()
        except RuntimeError:
            return
        if nm and nm != self.name: self.name = nm; self._set_icon(); self.name_lbl.setText(nm)
        now = time.time(); dt = max(now - self._last_t, 0.001)
        inst = max(pos - self._last_bytes, 0) / dt
        self.speed = inst if self.speed == 0 else 0.6 * self.speed + 0.4 * inst
        self._last_bytes = pos; self._last_t = now; self.received = pos; self.total = max(total, 0)
        if paused:
            self.kind = self.PAUSED; self.speed = 0.0
            self.status_lbl.setText(f"⏸ Paused  •  {_dl_size(pos)}" + (f" of {_dl_size(total)}" if total > 0 else ""))
            self.speed_lbl.setText("")
        else:
            self.kind = self.ACTIVE
            if total > 0:
                if self.bar.maximum() != 1000: self.bar.setRange(0, 1000)
                self.bar.setValue(int(pos / total * 1000))
                eta = (total - pos) / self.speed if self.speed > 1 else 0
                eta_s = f"  •  {_dl_dur(eta)} left" if eta > 0 else ""
                self.status_lbl.setText(f"{pos / total * 100:.0f}%  •  {_dl_size(pos)} of {_dl_size(total)}{eta_s}")
            else:
                self.bar.setRange(0, 0) if pos == 0 else None
                self.status_lbl.setText(f"Downloading…  {_dl_size(pos)}")
            self.speed_lbl.setText(f"{_dl_size(self.speed)}/s" if self.speed > 100 else "")
        self.status_lbl.setStyleSheet(f"font-size:11px;color:{self.theme['text_secondary']};")
        self._refresh_buttons()

    def _state_changed(self, state):
        S = QWebEngineDownloadRequest.DownloadState
        try:
            if state == S.DownloadCompleted:
                self.kind = self.DONE; self.received = self.total = max(self.download.totalBytes(), self.download.receivedBytes())
                self.name = self.download.downloadFileName() or self.name; self.dir = self.download.downloadDirectory() or self.dir
                self.when = time.time()
                if self.bar.maximum() == 0: self.bar.setRange(0, 1000)
            elif state == S.DownloadCancelled:
                self.kind = self.CANCELLED
            elif state == S.DownloadInterrupted:
                self.kind = self.FAILED
                try: self.error = self.download.interruptReasonString() or "Interrupted"
                except Exception: self.error = "Interrupted"
            else:
                return
            self.speed = 0.0
            self._refresh_final_or_live()
            if self.manager: self.manager._item_finished(self)
        except RuntimeError:
            pass

    # ── actions ──
    def _toggle_pause(self):
        try:
            if self.download.isPaused(): self.download.resume()
            else: self.download.pause()
        except Exception: pass
        self.tick()

    def _cancel(self):
        try: self.download.cancel()
        except Exception: pass

    def _open_file(self):
        if os.path.isfile(self.path): QDesktopServices.openUrl(QUrl.fromLocalFile(self.path))
        else: self._refresh_final_or_live()

    def _open_folder(self):
        if self.dir and os.path.isdir(self.dir): QDesktopServices.openUrl(QUrl.fromLocalFile(self.dir))

    def _retry(self):
        if self.manager: self.manager.retry(self)

    def _copy_link(self):
        QApplication.clipboard().setText(self.url)
        if self.manager: self.manager.flash("🔗 Link copied")

    def _delete_file(self):
        if not os.path.isfile(self.path): return
        if QMessageBox.question(self, "Delete file", f"Permanently delete this file from disk?\n\n{self.path}") \
                == QMessageBox.StandardButton.Yes:
            try: os.remove(self.path)
            except Exception as exc:
                QMessageBox.warning(self, "Delete failed", str(exc)); return
            self._refresh_final_or_live()

    def _more_menu(self):
        m = QMenu(self)
        m.addAction("🔗 Copy download link", self._copy_link)
        if self.manager and self.url.startswith(("http://", "https://")):
            m.addAction("🌐 Open source link in new tab", lambda: self.manager.open_in_tab(self.url))
        if self.kind == self.DONE and os.path.isfile(self.path):
            m.addAction("📋 Copy file path", lambda: QApplication.clipboard().setText(self.path))
            m.addAction("🗑 Delete file from disk", self._delete_file)
        m.addSeparator()
        m.addAction("✖ Remove from list", lambda: self.manager.remove_item(self) if self.manager else None)
        m.setAttribute(Qt.WidgetAttribute.WA_DeleteOnClose, True)
        m.exec(self.more_btn.mapToGlobal(QPoint(0, self.more_btn.height())))

class DownloadManagerDialog(QDialog):
    def __init__(self, theme, parent=None):
        super().__init__(parent)
        self.theme = theme; t = theme; acc = t["accent"]
        self._items = []; self._filter = "all"; self._loading = True
        self.setWindowTitle("SPS Download Manager"); self.resize(760, 640)
        self.setStyleSheet(
            f"QDialog{{background:{t['bg_primary']};}}QLabel{{color:{t['text_primary']};}}"
            f"QScrollArea{{background:transparent;border:none;}}"
            f"QScrollBar:vertical{{background:{t['bg_secondary']};width:8px;border-radius:4px;}}"
            f"QScrollBar::handle:vertical{{background:{t['border']};border-radius:4px;}}")
        lay = QVBoxLayout(self); lay.setContentsMargins(0, 0, 0, 0); lay.setSpacing(0)
        # header
        hdr = QWidget(); hdr.setStyleSheet(f"background:qlineargradient(x1:0,y1:0,x2:1,y2:1,stop:0 {acc},stop:1 {acc}aa);")
        hv = QVBoxLayout(hdr); hv.setContentsMargins(20, 12, 16, 10); hv.setSpacing(4)
        h1 = QHBoxLayout()
        ttl = QLabel("📥 Download Manager"); ttl.setStyleSheet("color:white;font-size:18px;font-weight:800;background:transparent;")
        self.count_lbl = QLabel(""); self.count_lbl.setStyleSheet("color:rgba(255,255,255,.8);font-size:12px;background:transparent;")
        h1.addWidget(ttl, 1); h1.addWidget(self.count_lbl); hv.addLayout(h1)
        self.stats_lbl = QLabel("Idle"); self.stats_lbl.setStyleSheet("color:rgba(255,255,255,.92);font-size:12px;font-weight:600;background:transparent;")
        hv.addWidget(self.stats_lbl)
        lay.addWidget(hdr)
        self.graph = _DlSpeedGraph(t); lay.addWidget(self.graph)
        # toolbar: search + bulk actions
        bar = QWidget(); bar.setStyleSheet(f"background:{t['bg_secondary']};")
        bl = QHBoxLayout(bar); bl.setContentsMargins(12, 8, 12, 8); bl.setSpacing(6)
        self.search = QLineEdit(); self.search.setPlaceholderText("🔍 Search downloads…"); self.search.setClearButtonEnabled(True)
        self.search.setStyleSheet(f"background:{t['bg_primary']};color:{t['text_primary']};border:1px solid {t['border']};"
                                  f"border-radius:10px;padding:6px 12px;")
        self.search.textChanged.connect(self._apply_filter); bl.addWidget(self.search, 1)
        btn_css = (f"QPushButton{{background:{t['bg_primary']};color:{t['text_primary']};border:1px solid {t['border']};"
                   f"border-radius:10px;padding:6px 12px;font-size:12px;font-weight:600;}}"
                   f"QPushButton:hover{{background:{t['hover']};border-color:{acc};}}")
        for text, fn in (("⏸ Pause all", self.pause_all), ("▶ Resume all", self.resume_all),
                         ("📁 Folder", self.open_download_folder), ("🧹 Clear finished", self._clear_completed)):
            b = QPushButton(text); b.setStyleSheet(btn_css); b.setCursor(Qt.CursorShape.PointingHandCursor)
            b.clicked.connect(lambda _=False, f=fn: f()); bl.addWidget(b)
        lay.addWidget(bar)
        # filter tabs
        tabs = QWidget(); tabs.setStyleSheet(f"background:{t['bg_secondary']};")
        tl = QHBoxLayout(tabs); tl.setContentsMargins(12, 0, 12, 8); tl.setSpacing(6)
        self._tab_btns = {}
        for key, label in (("all", "All"), ("active", "⬇ Active"), ("done", "✅ Completed"), ("failed", "⚠ Failed / Cancelled")):
            b = QPushButton(label); b.setCheckable(True); b.setCursor(Qt.CursorShape.PointingHandCursor)
            b.setStyleSheet(f"QPushButton{{background:transparent;color:{t['text_secondary']};border:none;border-radius:12px;padding:5px 14px;font-weight:700;font-size:12px;}}"
                            f"QPushButton:checked{{background:{acc};color:white;}}QPushButton:hover:!checked{{background:{t['hover']};}}")
            b.clicked.connect(lambda _=False, k=key: self._set_filter(k)); tl.addWidget(b); self._tab_btns[key] = b
        tl.addStretch(); self._tab_btns["all"].setChecked(True)
        lay.addWidget(tabs)
        # list
        self.scroll = QScrollArea(); self.scroll.setWidgetResizable(True)
        self.container = QWidget(); self.container.setStyleSheet(f"background:{t['bg_primary']};")
        self.c_lay = QVBoxLayout(self.container); self.c_lay.setContentsMargins(0, 0, 0, 0); self.c_lay.setSpacing(0)
        self.c_lay.setAlignment(Qt.AlignmentFlag.AlignTop)
        self.empty_lbl = QLabel("✨ No downloads yet"); self.empty_lbl.setAlignment(Qt.AlignmentFlag.AlignCenter)
        self.empty_lbl.setStyleSheet(f"color:{t['text_secondary']};font-size:14px;padding:60px;")
        self.c_lay.addWidget(self.empty_lbl)
        self.scroll.setWidget(self.container); lay.addWidget(self.scroll, 1)
        self.toast = QLabel(""); self.toast.setAlignment(Qt.AlignmentFlag.AlignCenter); self.toast.hide()
        self.toast.setStyleSheet(f"background:{acc};color:white;padding:5px;font-weight:600;font-size:12px;"); lay.addWidget(self.toast)
        self._load_history(); self._loading = False; self._apply_filter()
        self._timer = QTimer(self); self._timer.setInterval(1000); self._timer.timeout.connect(self._tick); self._timer.start()

    # ── persistence ──
    def _history_path(self):
        try:
            base = getattr(self.parent(), "profile_path", None) or get_profile_path(CURRENT_PROFILE_NAME)
            os.makedirs(base, exist_ok=True)
            return os.path.join(base, "downloads_history.json")
        except Exception:
            return None

    def _load_history(self):
        p = self._history_path()
        if not p or not os.path.isfile(p): return
        try:
            with open(p, encoding="utf-8") as f: recs = json.load(f)
        except Exception:
            return
        for r in reversed(recs[:300]):                      # file is newest-first → insert oldest first
            if isinstance(r, dict) and r.get("name"):
                self._insert(DownloadItemWidget(None, self.theme, self, r))

    def _save_history(self):
        if self._loading: return
        p = self._history_path()
        if not p: return
        try:
            recs = [i.to_record() for i in self._items if i.is_finished() and not i.private][:300]
            with open(p, "w", encoding="utf-8") as f: json.dump(recs, f, indent=1)
        except Exception:
            pass

    # ── list management ──
    def _insert(self, w):
        self._items.insert(0, w); self.c_lay.insertWidget(0, w)

    def add_download(self, download):
        for i in self._items:                               # never add the same download twice
            if i.download is download: self.show(); self.raise_(); return
        w = DownloadItemWidget(download, self.theme, self)
        self._insert(w); self._apply_filter(); self._update_stats()
        self.show(); self.raise_()

    def _item_finished(self, item):
        self._save_history(); self._apply_filter(); self._update_stats()

    def remove_item(self, item):
        if item in self._items: self._items.remove(item)
        item.cleanup(); self.c_lay.removeWidget(item); item.deleteLater()
        self._save_history(); self._apply_filter(); self._update_stats()

    def _clear_completed(self):
        for i in [x for x in self._items if x.is_finished()]:
            self.remove_item(i)

    def _set_filter(self, key):
        self._filter = key
        for k, b in self._tab_btns.items(): b.setChecked(k == key)
        self._apply_filter()

    def _apply_filter(self, *_):
        txt = self.search.text() if hasattr(self, "search") else ""
        shown = 0
        for i in self._items:
            ok = i.matches(self._filter, txt); i.setVisible(ok); shown += ok
        self.empty_lbl.setText("✨ No downloads yet" if not self._items else "🔎 No downloads match")
        self.empty_lbl.setVisible(shown == 0)
        n = len(self._items); self.count_lbl.setText(f"{n} item{'s' if n != 1 else ''}" if n else "")

    # ── bulk + helpers ──
    def pause_all(self):
        for i in self._items:
            if i.is_live() and i.download is not None:
                try:
                    if not i.download.isPaused(): i.download.pause()
                except Exception: pass
            i.tick()
        self.flash("⏸ Paused all active downloads")

    def resume_all(self):
        for i in self._items:
            if i.is_live() and i.download is not None:
                try:
                    if i.download.isPaused(): i.download.resume()
                except Exception: pass
            i.tick()
        self.flash("▶ Resumed downloads")

    def open_download_folder(self):
        d = ""
        try: d = self.parent().settings_data.get("download_path", "")
        except Exception: pass
        d = d or os.path.expanduser("~/Downloads")
        try: os.makedirs(d, exist_ok=True)
        except Exception: pass
        QDesktopServices.openUrl(QUrl.fromLocalFile(d))

    def open_in_tab(self, url):
        try: self.parent().add_new_tab(QUrl(url))
        except Exception: pass

    def retry(self, item):
        """Re-download a failed/cancelled item through the current tab's page (goes through the normal download handler)."""
        try:
            mw = self.parent(); page = mw.tabs.currentWidget().page()
            page.download(QUrl(item.url), item.name)
            self.remove_item(item); self.flash("🔁 Retrying…")
        except Exception:
            self.open_in_tab(item.url); self.flash("🔁 Opened link in a tab — the download will restart")

    def flash(self, msg, ms=2500):
        self.toast.setText(msg); self.toast.show(); QTimer.singleShot(ms, self.toast.hide)

    def _tick(self):
        live = [i for i in self._items if i.is_live()]
        for i in live: i.tick()
        self._update_stats(live)

    def _update_stats(self, live=None):
        if live is None: live = [i for i in self._items if i.is_live()]
        spd = sum(i.speed for i in live)
        if live or any(v > 0 for v in self.graph._pts[-3:]): self.graph.push(spd)
        done = sum(1 for i in self._items if i.kind == i.DONE)
        got = sum(i.received for i in self._items if i.received)
        if live:
            left = sum(max(i.total - i.received, 0) for i in live if i.total > 0)
            eta = f"  •  ~{_dl_dur(left / spd)} left" if spd > 1 and left > 0 else ""
            self.stats_lbl.setText(f"⬇ {_dl_size(spd)}/s  •  {len(live)} active  •  {done} completed{eta}")
        else:
            self.stats_lbl.setText(f"Idle  •  {done} completed  •  {_dl_size(got)} total" if self._items else "Idle")

    def closeEvent(self, e):
        self._save_history(); super().closeEvent(e)


# ═══════════════════════════════════════════════════════════════
#  PASSWORD MANAGER
# ═══════════════════════════════════════════════════════════════
class _SecretBox:
    """Encrypts saved passwords on disk.

    * A random 256-bit master key is created per profile (vault.key).
    * On Windows the key file is wrapped with DPAPI, so it can only be opened by the
      same Windows user on the same PC (copying the files elsewhere gives nothing).
    * Data is encrypted with HMAC-SHA256 in counter mode + an HMAC-SHA256 tag
      (encrypt-then-MAC), so tampering is detected.
    """
    PREFIX = "sps1:"

    def __init__(self, folder):
        self.path = os.path.join(folder, "vault.key")
        self._key = self._load_or_create()
        self._ek = hmac.new(self._key, b"sps-enc", hashlib.sha256).digest()
        self._mk = hmac.new(self._key, b"sps-mac", hashlib.sha256).digest()

    # ---- master key protection -------------------------------------------
    @staticmethod
    def _dpapi(data, protect):
        import ctypes
        from ctypes import wintypes

        class BLOB(ctypes.Structure):
            _fields_ = [("cbData", wintypes.DWORD), ("pbData", ctypes.POINTER(ctypes.c_char))]

        buf = ctypes.create_string_buffer(data, len(data))
        bin_ = BLOB(len(data), ctypes.cast(buf, ctypes.POINTER(ctypes.c_char)))
        out = BLOB()
        fn = ctypes.windll.crypt32.CryptProtectData if protect else ctypes.windll.crypt32.CryptUnprotectData
        ok = fn(ctypes.byref(bin_), None, None, None, None, 0, ctypes.byref(out))
        if not ok:
            raise OSError("DPAPI failed")
        try:
            return ctypes.string_at(out.pbData, out.cbData)
        finally:
            ctypes.windll.kernel32.LocalFree(out.pbData)

    def _load_or_create(self):
        if os.path.exists(self.path):
            try:
                raw = open(self.path, "rb").read()
                if raw.startswith(b"DPAPI1:"):
                    return self._dpapi(raw[7:], False)
                if raw.startswith(b"RAW1:"):
                    return raw[5:]
            except Exception:
                pass
        key = secrets.token_bytes(32)
        blob = b"RAW1:" + key
        if platform.system() == "Windows":
            try:
                blob = b"DPAPI1:" + self._dpapi(key, True)
            except Exception:
                blob = b"RAW1:" + key
        try:
            tmp = self.path + ".tmp"
            with open(tmp, "wb") as f:
                f.write(blob)
            os.replace(tmp, self.path)
            try:
                os.chmod(self.path, 0o600)
            except Exception:
                pass
        except Exception:
            pass
        return key

    # ---- encrypt / decrypt -------------------------------------------------
    def _stream(self, nonce, n):
        out = bytearray(); i = 0
        while len(out) < n:
            out += hmac.new(self._ek, nonce + i.to_bytes(8, "big"), hashlib.sha256).digest(); i += 1
        return bytes(out[:n])

    def encrypt(self, text):
        data = text.encode("utf-8"); nonce = secrets.token_bytes(16)
        ct = bytes(a ^ b for a, b in zip(data, self._stream(nonce, len(data))))
        tag = hmac.new(self._mk, nonce + ct, hashlib.sha256).digest()
        return self.PREFIX + base64.b64encode(nonce + tag + ct).decode("ascii")

    def decrypt(self, token):
        if not isinstance(token, str) or not token.startswith(self.PREFIX):
            return None
        try:
            raw = base64.b64decode(token[len(self.PREFIX):])
            nonce, tag, ct = raw[:16], raw[16:48], raw[48:]
            if not hmac.compare_digest(tag, hmac.new(self._mk, nonce + ct, hashlib.sha256).digest()):
                return None
            return bytes(a ^ b for a, b in zip(ct, self._stream(nonce, len(ct)))).decode("utf-8")
        except Exception:
            return None


def _pw_host(site):
    """Normalise a site / URL to a bare host name (lower-case, no www.)."""
    s = (site or "").strip().lower()
    if not s:
        return ""
    if "://" not in s:
        s = "https://" + s
    try:
        h = urlparse(s).hostname or ""
    except Exception:
        h = ""
    return h[4:] if h.startswith("www.") else h


class PasswordManager:
    """Saved logins — encrypted on disk, matched by website, used for auto-fill."""
    def __init__(self, profile_name):
        folder = get_profile_path(profile_name)
        self.path = os.path.join(folder, "passwords.json")
        self.never_path = os.path.join(folder, "passwords_never.json")
        self.box = _SecretBox(folder)
        self._never = self._load_never()
        self._data = self._load()

    # ---- storage ---------------------------------------------------------
    def _load(self):
        items = []
        migrated = False
        if os.path.exists(self.path):
            try:
                with open(self.path, encoding="utf-8") as f:
                    raw = json.load(f)
            except Exception:
                raw = []
                try:    # keep a copy of an unreadable file instead of losing it
                    shutil.copy2(self.path, self.path + ".broken")
                except Exception:
                    pass
            for e in raw if isinstance(raw, list) else []:
                if not isinstance(e, dict):
                    continue
                e = dict(e)
                if "pw_enc" in e:
                    pw = self.box.decrypt(e.pop("pw_enc"))
                    if pw is None:
                        continue              # cannot be decrypted on this account/PC -> ignore
                    e["password"] = pw
                else:
                    migrated = True           # old plain-text entry -> will be encrypted on next save
                e.setdefault("id", secrets.token_hex(8))
                items.append(e)
        self._data = items
        if migrated:
            self._save()
        return items

    def _save(self):
        out = []
        for e in self._data:
            c = dict(e)
            c["pw_enc"] = self.box.encrypt(c.pop("password", ""))
            out.append(c)
        try:
            tmp = self.path + ".tmp"
            with open(tmp, "w", encoding="utf-8") as f:
                json.dump(out, f, indent=2)
            os.replace(tmp, self.path)
            try:
                os.chmod(self.path, 0o600)
            except Exception:
                pass
        except Exception as ex:
            _sps_log_exception(type(ex), ex, ex.__traceback__)

    def _load_never(self):
        try:
            with open(self.never_path, encoding="utf-8") as f:
                return set(json.load(f))
        except Exception:
            return set()

    def _save_never(self):
        try:
            with open(self.never_path, "w", encoding="utf-8") as f:
                json.dump(sorted(self._never), f)
        except Exception:
            pass

    # ---- API used by the dialog ----------------------------------------------
    def add(self, site, username, password):
        host = _pw_host(site)
        for e in self._data:                       # same site + user -> update instead of duplicating
            if _pw_host(e.get("site", "")) == host and e.get("username") == username:
                e["password"] = password; e["modified"] = str(datetime.datetime.now())
                self._save(); return e
        entry = {"id": secrets.token_hex(8), "site": site, "username": username,
                 "password": password, "added": str(datetime.datetime.now())}
        self._data.append(entry); self._save(); return entry

    def get_all(self): return [dict(e) for e in self._data]

    def delete(self, eid):
        self._data = [e for e in self._data if e.get("id") != eid]; self._save()

    def search(self, query):
        q = query.lower()
        return [dict(e) for e in self._data if q in e.get("site", "").lower() or q in e.get("username", "").lower()]

    def update(self, eid, **kw):
        for e in self._data:
            if e.get("id") == eid:
                e.update(kw)
        self._save()

    # ---- auto-fill helpers -------------------------------------------------
    def find_for_host(self, host):
        """Saved logins for this website (same host, or a sub-domain / parent domain of it), newest-used first."""
        h = _pw_host(host)
        if not h:
            return []
        res = []
        for e in self._data:
            eh = _pw_host(e.get("site", ""))
            if eh and (eh == h or h.endswith("." + eh) or eh.endswith("." + h)):
                res.append(e)
        res.sort(key=lambda e: e.get("last_used", e.get("added", "")), reverse=True)
        return res

    def get_by_id(self, eid):
        for e in self._data:
            if e.get("id") == eid:
                return dict(e)
        return None

    def mark_used(self, eid):
        for e in self._data:
            if e.get("id") == eid:
                e["last_used"] = str(datetime.datetime.now())
        self._save()

    def never_save(self, host):
        return _pw_host(host) in self._never

    def add_never(self, host):
        self._never.add(_pw_host(host)); self._save_never()

    def check_strength(self, pw):
        score = 0
        if len(pw) >= 8:  score += 1
        if len(pw) >= 16: score += 1
        if re.search(r'[A-Z]', pw): score += 1
        if re.search(r'[a-z]', pw): score += 1
        if re.search(r'\d', pw):    score += 1
        if re.search(r'[^A-Za-z0-9]', pw): score += 1
        if score <= 2: return "Weak", "#d93025"
        if score <= 4: return "Medium", "#f9ab00"
        return "Strong", "#188038"


class PasswordManagerDialog(QDialog):
    def __init__(self, pm, theme, parent=None):
        super().__init__(parent)
        self.pm=pm; self.theme=theme
        self.setWindowTitle("🔐 SPS Password Manager"); self.resize(850,620)
        t=theme
        self.setStyleSheet(f"""
            QDialog{{background:{t['bg_primary']};}}
            QLabel{{color:{t['text_primary']};}}
            QLineEdit{{background:{t['bg_secondary']};color:{t['text_primary']};
                       border:1px solid {t['border']};border-radius:8px;padding:8px 12px;}}
            QPushButton{{background:{t['accent']};color:white;border:none;
                         border-radius:8px;padding:8px 18px;font-weight:600;}}
            QPushButton:hover{{background:{t['accent']}dd;}}
            QTableWidget{{background:{t['bg_secondary']};color:{t['text_primary']};
                          gridline-color:{t['border']};border:1px solid {t['border']};border-radius:8px;}}
            QHeaderView::section{{background:{t['bg_tertiary']};color:{t['text_primary']};
                                  padding:8px;border:none;font-weight:600;}}
        """)
        self._build_ui(); self._refresh()

    def _build_ui(self):
        t=self.theme; lay=QVBoxLayout(self); lay.setSpacing(12)
        hdr=QLabel("🔐 Password Manager")
        hdr.setStyleSheet(f"font-size:22px;font-weight:700;color:{t['text_primary']};padding:10px 0;")
        lay.addWidget(hdr)
        sr=QHBoxLayout()
        self.search_bar=QLineEdit(); self.search_bar.setPlaceholderText("🔍 Search passwords…")
        self.search_bar.textChanged.connect(self._refresh); sr.addWidget(self.search_bar,1)
        gen_btn=QPushButton("⚡ Generate")
        gen_btn.setStyleSheet(f"background:{t['bg_tertiary']};color:{t['text_primary']};border:1px solid {t['border']};")
        gen_btn.clicked.connect(self._generate_pw); sr.addWidget(gen_btn)
        exp_btn=QPushButton("📤 Export")
        exp_btn.setStyleSheet(f"background:{t['bg_tertiary']};color:{t['text_primary']};border:1px solid {t['border']};")
        exp_btn.clicked.connect(self._export); sr.addWidget(exp_btn)
        lay.addLayout(sr)
        self.table=QTableWidget(0,5)
        self.table.setHorizontalHeaderLabels(["Site","Username","Password","Strength","Actions"])
        for i,m in enumerate([QHeaderView.ResizeMode.Stretch,QHeaderView.ResizeMode.Stretch,
                               QHeaderView.ResizeMode.ResizeToContents,
                               QHeaderView.ResizeMode.ResizeToContents,
                               QHeaderView.ResizeMode.ResizeToContents]):
            self.table.horizontalHeader().setSectionResizeMode(i,m)
        self.table.setSelectionBehavior(QTableWidget.SelectionBehavior.SelectRows)
        self.table.setEditTriggers(QTableWidget.EditTrigger.NoEditTriggers)
        self.table.setAlternatingRowColors(True)
        lay.addWidget(self.table,1)
        fb=QGroupBox("Add New Entry")
        fb.setStyleSheet(f"QGroupBox{{color:{t['text_primary']};border:1px solid {t['border']};"
                         f"border-radius:10px;margin-top:12px;padding:12px;}}"
                         f"QGroupBox::title{{subcontrol-origin:margin;padding:0 6px;}}")
        form=QHBoxLayout(fb)
        self.f_site=QLineEdit(); self.f_site.setPlaceholderText("Site / URL")
        self.f_user=QLineEdit(); self.f_user.setPlaceholderText("Username")
        self.f_pass=QLineEdit(); self.f_pass.setPlaceholderText("Password")
        self.f_pass.setEchoMode(QLineEdit.EchoMode.Password)
        self.f_pass.textChanged.connect(self._show_strength)
        self.strength_lbl=QLabel(""); self.strength_lbl.setFixedWidth(60)
        add_btn=QPushButton("➕ Add"); add_btn.clicked.connect(self._add_entry)
        for w in [self.f_site,self.f_user,self.f_pass,self.strength_lbl]: form.addWidget(w,1 if w!=self.strength_lbl else 0)
        form.addWidget(add_btn); lay.addWidget(fb)

    def _show_strength(self, pw):
        label,color=self.pm.check_strength(pw)
        self.strength_lbl.setText(label)
        self.strength_lbl.setStyleSheet(f"color:{color};font-weight:600;font-size:11px;")

    def _refresh(self):
        query=self.search_bar.text()
        entries=self.pm.search(query) if query else self.pm.get_all()
        t=self.theme; self.table.setRowCount(0)
        for e in entries:
            row=self.table.rowCount(); self.table.insertRow(row)
            self.table.setItem(row,0,QTableWidgetItem(e.get("site","")))
            self.table.setItem(row,1,QTableWidgetItem(e.get("username","")))
            pw_item=QTableWidgetItem("••••••••")
            pw_item.setData(Qt.ItemDataRole.UserRole,e.get("password",""))
            self.table.setItem(row,2,pw_item)
            strength,color=self.pm.check_strength(e.get("password",""))
            s_item=QTableWidgetItem(strength); s_item.setForeground(QColor(color))
            self.table.setItem(row,3,s_item)
            cell_w=QWidget(); cell_l=QHBoxLayout(cell_w)
            cell_l.setContentsMargins(4,2,4,2); cell_l.setSpacing(4)
            for icon,tip,fn in [
                ("👁","Show/hide",partial(self._toggle_reveal,row,pw_item,e)),
                ("📋","Copy",partial(self._copy_password,e.get("password",""))),
                ("🗑","Delete",partial(self._delete_entry,e.get("id"))),
            ]:
                b=QPushButton(icon); b.setFixedSize(30,26)
                b.setStyleSheet(f"background:{t['bg_tertiary']};color:{t['text_primary']};border-radius:4px;padding:0;")
                b.setToolTip(tip); b.clicked.connect(fn); cell_l.addWidget(b)
            self.table.setCellWidget(row,4,cell_w)

    def _toggle_reveal(self,row,pw_item,entry,*_):
        pw_item.setText(entry.get("password","") if pw_item.text()=="••••••••" else "••••••••")

    def _copy_password(self,pw,*_):
        QApplication.clipboard().setText(pw)

    def _delete_entry(self,eid,*_):
        if QMessageBox.question(self,"Delete","Delete this password entry?")==QMessageBox.StandardButton.Yes:
            self.pm.delete(eid); self._refresh()

    def _add_entry(self):
        site=self.f_site.text().strip(); user=self.f_user.text().strip(); pw=self.f_pass.text()
        if not site or not user or not pw:
            QMessageBox.warning(self,"Missing Fields","Please fill in all fields."); return
        self.pm.add(site,user,pw)
        self.f_site.clear(); self.f_user.clear(); self.f_pass.clear(); self._refresh()

    def _generate_pw(self):
        t=self.theme; dlg=QDialog(self); dlg.setWindowTitle("Generate Password")
        dlg.setStyleSheet(f"background:{t['bg_primary']};color:{t['text_primary']};")
        lay=QVBoxLayout(dlg)
        lr=QHBoxLayout(); lr.addWidget(QLabel("Length:"))
        spin=QSpinBox(); spin.setRange(8,64); spin.setValue(16); lr.addWidget(spin)
        lay.addLayout(lr)
        sym_cb=QCheckBox("Include symbols"); sym_cb.setChecked(True); lay.addWidget(sym_cb)
        num_cb=QCheckBox("Include numbers"); num_cb.setChecked(True); lay.addWidget(num_cb)
        result=QLineEdit(); result.setReadOnly(True); lay.addWidget(result)
        self._pw_strength_lbl=QLabel(""); lay.addWidget(self._pw_strength_lbl)
        def regen():
            pw=generate_password(spin.value(),sym_cb.isChecked())
            result.setText(pw)
            lbl,col=self.pm.check_strength(pw)
            self._pw_strength_lbl.setText(f"Strength: {lbl}")
            self._pw_strength_lbl.setStyleSheet(f"color:{col};font-weight:700;")
        br=QHBoxLayout()
        for txt,fn in [("🔄 Generate",regen),
                       ("📋 Copy",lambda: QApplication.clipboard().setText(result.text())),
                       ("✓ Use",lambda: (self.f_pass.setText(result.text()),dlg.accept()))]:
            b=QPushButton(txt); b.clicked.connect(fn); br.addWidget(b)
        lay.addLayout(br); regen(); dlg.exec()

    def _export(self):
        if QMessageBox.warning(self,"Export passwords?",
                "The exported file is NOT encrypted — anyone who opens it can read your passwords.\n\n"
                "Export only to a safe place and delete the file when you are done.\n\nContinue?",
                QMessageBox.StandardButton.Yes|QMessageBox.StandardButton.No,
                QMessageBox.StandardButton.No)!=QMessageBox.StandardButton.Yes: return
        path,_=QFileDialog.getSaveFileName(self,"Export Passwords","passwords.csv","CSV (*.csv)")
        if path:
            import csv as _csv
            with open(path,"w",newline="",encoding="utf-8") as f:
                w=_csv.writer(f); w.writerow(["site","username","password"])
                for e in self.pm.get_all():
                    w.writerow([e.get("site",""),e.get("username",""),e.get("password","")])
            QMessageBox.information(self,"Exported",f"Passwords exported to {path}")

