def _sps_is_internal_newtab(url_str):
    """True for the browser's own new-tab page (a temp file that is deleted on exit) — never worth saving/restoring."""
    u = (url_str or "").strip().lower().replace("\\", "/")
    return (not u) or u in ("about:blank", "about:newtab") or "sps_newtab_" in u or u.startswith("data:text/html")

def _sps_stale_file_url(url_str):
    """True for file:// URLs that point to a file which no longer exists."""
    try:
        u = (url_str or "").strip()
        if u.lower().startswith("file:"):
            p = QUrl(u).toLocalFile()
            return (not p) or (not os.path.exists(p))
    except Exception:
        pass
    return False

def _sps_restorable_url(url_str):
    return not (_sps_is_internal_newtab(url_str) or _sps_stale_file_url(url_str))

class SessionManager:
    def __init__(self, profile_name):
        self.path=os.path.join(get_profile_path(profile_name),"session.json")
    def save(self, tabs_info):
        with open(self.path,"w") as f: json.dump({"tabs":tabs_info,"saved":str(datetime.datetime.now())},f)
    def load(self):
        if os.path.exists(self.path):
            try:
                with open(self.path) as f: data=json.load(f)
                return data.get("tabs",[])
            except: pass
        return []

