# ═══════════════════════════════════════════════════════════════
#  FIRST-RUN GUIDED TOUR  (spotlight overlay + step card)
# ═══════════════════════════════════════════════════════════════
class TourOverlay(QWidget):
    """Dims the window, spotlights one part of the UI and explains it. Esc = skip, ←/→ = navigate."""
    def __init__(self, win, steps, theme, on_done):
        super().__init__(win)
        self.win = win; self.steps = steps; self.t = theme; self.on_done = on_done
        self.i = 0; self._rect = None; self._done = False
        self.setFocusPolicy(Qt.FocusPolicy.StrongFocus)
        self.setMouseTracking(True)
        t = theme; acc = t["accent"]
        self.card = QFrame(self); self.card.setFixedWidth(360)
        self.card.setStyleSheet(
            f"QFrame#tourCard{{background:{t['bg_primary']};border:2px solid {acc};border-radius:16px;}}"
            f"QLabel{{background:transparent;color:{t['text_primary']};}}")
        self.card.setObjectName("tourCard")
        cl = QVBoxLayout(self.card); cl.setContentsMargins(20, 16, 20, 16); cl.setSpacing(8)
        self.step_lbl = QLabel(""); self.step_lbl.setStyleSheet(f"color:{acc};font-size:11px;font-weight:800;")
        self.title_lbl = QLabel(""); self.title_lbl.setWordWrap(True)
        self.title_lbl.setStyleSheet(f"font-size:18px;font-weight:800;color:{t['text_primary']};")
        self.text_lbl = QLabel(""); self.text_lbl.setWordWrap(True); self.text_lbl.setTextFormat(Qt.TextFormat.RichText)
        self.text_lbl.setStyleSheet(f"font-size:13px;color:{t['text_secondary']};")
        self.bar = QProgressBar(); self.bar.setFixedHeight(5); self.bar.setTextVisible(False)
        self.bar.setRange(0, max(len(steps), 1))
        self.bar.setStyleSheet(f"QProgressBar{{background:{t['bg_tertiary']};border:none;border-radius:2px;}}"
                               f"QProgressBar::chunk{{background:{acc};border-radius:2px;}}")
        for w in (self.step_lbl, self.title_lbl, self.text_lbl, self.bar): cl.addWidget(w)
        row = QHBoxLayout(); row.setSpacing(8)
        self.skip_btn = QPushButton("Skip tour")
        self.back_btn = QPushButton("‹ Back")
        self.next_btn = QPushButton("Next ›")
        self.skip_btn.setStyleSheet(f"QPushButton{{color:{t['text_secondary']};background:transparent;border:none;font-weight:600;padding:6px 4px;}}"
                                    f"QPushButton:hover{{color:{t['text_primary']};}}")
        self.back_btn.setStyleSheet(f"QPushButton{{background:{t['bg_secondary']};color:{t['text_primary']};border:1px solid {t['border']};border-radius:10px;padding:7px 14px;font-weight:700;}}"
                                    f"QPushButton:hover{{border-color:{acc};}}")
        self.next_btn.setStyleSheet(f"QPushButton{{background:{acc};color:white;border:none;border-radius:10px;padding:7px 18px;font-weight:800;}}"
                                    f"QPushButton:hover{{background:{acc}dd;}}")
        for b in (self.skip_btn, self.back_btn, self.next_btn): b.setCursor(Qt.CursorShape.PointingHandCursor)
        self.skip_btn.clicked.connect(lambda *_: self.finish())
        self.back_btn.clicked.connect(lambda *_: self.go(self.i - 1))
        self.next_btn.clicked.connect(lambda *_: self.go(self.i + 1))
        row.addWidget(self.skip_btn); row.addStretch(1); row.addWidget(self.back_btn); row.addWidget(self.next_btn)
        cl.addLayout(row)
        self._timer = QTimer(self); self._timer.setInterval(300); self._timer.timeout.connect(self._relayout)
        self._timer.start()
        self.go(0)

    # ── geometry ──
    def _target_rect(self, targets):
        r = None
        for w in (targets or []):
            try:
                if w is None or not w.isVisible(): continue
                tl = w.mapTo(self.win, QPoint(0, 0)); wr = QRect(tl, w.size())
                r = wr if r is None else r.united(wr)
            except Exception:
                continue
        return r.adjusted(-6, -6, 6, 6) if r is not None else None

    def _relayout(self):
        if self._done: return
        if self.geometry() != self.win.rect(): self.setGeometry(self.win.rect())
        try: targets = self.steps[self.i][2]() if self.steps[self.i][2] else None
        except Exception: targets = None
        r = self._target_rect(targets)
        if r != self._rect:
            self._rect = r; self._place_card(); self.update()

    def _place_card(self):
        self.card.adjustSize()
        cw, ch = self.card.width(), self.card.height(); W, H = self.width(), self.height(); r = self._rect
        if r is None:
            x, y = (W - cw) // 2, (H - ch) // 2
        else:
            cx = min(max(r.center().x() - cw // 2, 14), max(W - cw - 14, 14))
            cy = min(max(r.center().y() - ch // 2, 14), max(H - ch - 14, 14))
            if r.bottom() + 16 + ch <= H - 10:   x, y = cx, r.bottom() + 16
            elif r.top() - 16 - ch >= 10:        x, y = cx, r.top() - 16 - ch
            elif r.right() + 16 + cw <= W - 10:  x, y = r.right() + 16, cy
            elif r.left() - 16 - cw >= 10:       x, y = r.left() - 16 - cw, cy
            else:                                x, y = (W - cw) // 2, (H - ch) // 2
        self.card.move(int(x), int(y)); self.card.raise_()

    # ── steps ──
    def go(self, n):
        if n >= len(self.steps): self.finish(); return
        self.i = max(n, 0)
        title, text, tgt = self.steps[self.i]
        self.step_lbl.setText(f"STEP {self.i + 1} OF {len(self.steps)}")
        self.title_lbl.setText(title); self.text_lbl.setText(text)
        self.bar.setValue(self.i + 1)
        self.back_btn.setVisible(self.i > 0)
        last = self.i == len(self.steps) - 1
        self.next_btn.setText("Finish ✓" if last else ("Start tour ›" if self.i == 0 else "Next ›"))
        self.skip_btn.setVisible(not last)
        self.setGeometry(self.win.rect()); self._rect = None; self._relayout()
        self._place_card(); self.update(); self.setFocus()

    def finish(self):
        if self._done: return
        self._done = True
        try: self._timer.stop()
        except Exception: pass
        self.hide(); self.deleteLater()
        try: self.on_done()
        except Exception: pass

    # ── painting / input ──
    def paintEvent(self, _e):
        from PyQt6.QtGui import QPainterPath
        from PyQt6.QtCore import QRectF
        p = QPainter(self)
        try:
            p.setRenderHint(QPainter.RenderHint.Antialiasing)
            full = QPainterPath(); full.addRect(QRectF(self.rect()))
            if self._rect is not None:
                hole = QPainterPath(); hole.addRoundedRect(QRectF(self._rect), 12, 12)
                full = full.subtracted(hole)
            p.fillPath(full, QColor(0, 0, 0, 175))
            if self._rect is not None:
                p.setPen(QPen(QColor(self.t["accent"]), 3)); p.setBrush(Qt.BrushStyle.NoBrush)
                p.drawRoundedRect(QRectF(self._rect), 12, 12)
        finally:
            p.end()

    def mousePressEvent(self, e): e.accept()
    def mouseReleaseEvent(self, e): e.accept()
    def wheelEvent(self, e): e.accept()
    def keyPressEvent(self, e):
        k = e.key()
        if k == Qt.Key.Key_Escape: self.finish()
        elif k in (Qt.Key.Key_Right, Qt.Key.Key_Return, Qt.Key.Key_Enter, Qt.Key.Key_Space): self.go(self.i + 1)
        elif k == Qt.Key.Key_Left: self.go(self.i - 1)
        else: e.accept()

# ═══════════════════════════════════════════════════════════════
#  V36: PROFILES  -  Chrome-style picker (cards, photo, colour, 3-dot menu, several profiles open at once)
# ═══════════════════════════════════════════════════════════════
from PyQt6.QtGui import QPainterPath

SPS_PROFILE_COLORS = [("#1a73e8", "Blue"), ("#d93025", "Red"), ("#188038", "Green"), ("#f9ab00", "Yellow"),
                      ("#9334e6", "Purple"), ("#e8710a", "Orange"), ("#12b5cb", "Cyan"), ("#e52592", "Pink"),
                      ("#00796b", "Teal"), ("#3949ab", "Indigo"), ("#795548", "Brown"), ("#5f6368", "Grey")]

def sps_profile_ids():
    try:
        ids = [d for d in os.listdir(PROFILES_DIR) if os.path.isdir(os.path.join(PROFILES_DIR, d))]
    except Exception:
        ids = []
    if "Default" not in ids:
        try: os.makedirs(os.path.join(PROFILES_DIR, "Default"), exist_ok=True)
        except Exception: pass
        ids.append("Default")
    ids.sort(key=lambda x: (x != "Default", x.lower()))
    return ids

def sps_profile_meta(pid):
    """{'name','color','avatar'}  - name/colour from profile_meta.json, avatar = avatar.png if it exists."""
    d = {"name": pid, "color": SPS_PROFILE_COLORS[sum(map(ord, pid)) % len(SPS_PROFILE_COLORS)][0]}
    try:
        with open(os.path.join(PROFILES_DIR, pid, "profile_meta.json"), encoding="utf-8") as f:
            raw = json.load(f)
        if isinstance(raw.get("name"), str) and raw["name"].strip():
            d["name"] = raw["name"].strip()[:40]
        if isinstance(raw.get("color"), str) and re.fullmatch(r"#[0-9a-fA-F]{6}", raw["color"]):
            d["color"] = raw["color"]
    except Exception:
        pass
    av = os.path.join(PROFILES_DIR, pid, "avatar.png")
    d["avatar"] = av if os.path.isfile(av) else ""
    return d

def sps_profile_save_meta(pid, name=None, color=None):
    m = sps_profile_meta(pid)
    if name is not None:
        m["name"] = name.strip()[:40] or pid
    if color:
        m["color"] = color
    os.makedirs(os.path.join(PROFILES_DIR, pid), exist_ok=True)
    with open(os.path.join(PROFILES_DIR, pid, "profile_meta.json"), "w", encoding="utf-8") as f:
        json.dump({"name": m["name"], "color": m["color"]}, f, indent=1, ensure_ascii=False)
    try:                                           # the profile colour is also its accent colour inside the browser
        s = json.loads(json.dumps(load_settings(pid)))     # deep copy: never touch the shared defaults
        s["accent_color"] = m["color"]
        if isinstance(s.get("theme"), dict):
            s["theme"]["accent"] = m["color"]
        save_settings_to_disk(pid, s)
    except Exception:
        pass

def sps_profile_make_id(name):
    base = re.sub(r"[^\w \-]", "", (name or "").strip(), flags=re.U).strip()[:30] or "Profile"
    existing = {x.lower() for x in sps_profile_ids()} | {"con", "prn", "aux", "nul"}
    pid, n = base, 2
    while pid.lower() in existing:
        pid = "%s %d" % (base, n); n += 1
    return pid

def _sps_proc_stamp(pid):
    try:
        import psutil
        return round(psutil.Process(pid).create_time(), 1)
    except Exception:
        return 0

def sps_profile_lock(pid):
    """Marks the profile as 'open in THIS process'. Stale locks (crash) are ignored because pid + start time are checked."""
    try:
        with open(os.path.join(PROFILES_DIR, pid, ".sps_running"), "w") as f:
            json.dump({"pid": os.getpid(), "t": _sps_proc_stamp(os.getpid())}, f)
    except Exception:
        pass

def sps_profile_unlock(pid):
    p = os.path.join(PROFILES_DIR, pid, ".sps_running")
    try:
        with open(p) as f:
            if int(json.load(f).get("pid", 0)) == os.getpid():
                os.remove(p)
    except Exception:
        pass

def sps_profile_running_pid(pid):
    """PID of the browser process that has this profile open (0 = not open)."""
    try:
        with open(os.path.join(PROFILES_DIR, pid, ".sps_running")) as f:
            d = json.load(f)
        p = int(d.get("pid", 0))
        import psutil
        pr = psutil.Process(p)
        if pr.is_running() and abs(pr.create_time() - float(d.get("t", 0))) < 2.0:
            return p
    except Exception:
        pass
    return 0

def sps_profile_delete(pid):
    """Returns '' on success or the reason it could not be deleted."""
    if pid == "Default":
        return "The Default profile cannot be deleted."
    if sps_profile_running_pid(pid):
        return "This profile is open right now. Close its browser window first."
    try:
        shutil.rmtree(os.path.join(PROFILES_DIR, pid))
        return ""
    except Exception as ex:
        return "Could not delete the profile folder: %s" % ex

def sps_picker_prefs():
    try:
        with open(os.path.join(BASE_DATA_DIR, "picker_prefs.json"), encoding="utf-8") as f:
            d = json.load(f)
        return d if isinstance(d, dict) else {}
    except Exception:
        return {}

def sps_picker_prefs_save(**kw):
    try:
        d = sps_picker_prefs(); d.update(kw)
        with open(os.path.join(BASE_DATA_DIR, "picker_prefs.json"), "w", encoding="utf-8") as f:
            json.dump(d, f)
    except Exception:
        pass

def _sps_focus_pid(pid):
    """Windows: bring the main window of process `pid` to the front."""
    if platform.system() != "Windows":
        return False
    try:
        import ctypes
        from ctypes import wintypes
        u = ctypes.windll.user32
        found = []
        Enum = ctypes.WINFUNCTYPE(wintypes.BOOL, wintypes.HWND, wintypes.LPARAM)
        def cb(hwnd, _l):
            p = wintypes.DWORD(); u.GetWindowThreadProcessId(hwnd, ctypes.byref(p))
            if p.value == pid and u.IsWindowVisible(hwnd) and u.GetWindowTextLengthW(hwnd) > 0:
                found.append(hwnd)
            return True
        u.EnumWindows(Enum(cb), 0)
        if found:
            u.ShowWindow(found[0], 9); u.SetForegroundWindow(found[0])
            return True
    except Exception:
        pass
    return False

def sps_open_profile_new_process(pid):
    """Open `pid` in ANOTHER browser window/process (like Chrome). Goes through the sandbox exe when installed.
    If the profile is already open somewhere, that window is brought to the front instead."""
    run = sps_profile_running_pid(pid)
    if run and run != os.getpid():
        _sps_focus_pid(run)
        return True
    if getattr(sys, "frozen", False):
        cmd = [_sps_find_sandbox_exe() or sys.executable, "--profile", pid]
    else:
        cmd = [_sps_gui_python(), os.path.abspath(sys.argv[0]), "--profile", pid]
    env = os.environ.copy()
    env.pop("SPS_SANDBOX_RESTART_FILE", None)
    kw = {}
    if platform.system() == "Windows":
        kw["creationflags"] = 0x00000008 | 0x00000200          # DETACHED_PROCESS | CREATE_NEW_PROCESS_GROUP
    subprocess.Popen(cmd, env=env, close_fds=True, stdin=subprocess.DEVNULL, stdout=subprocess.DEVNULL,
                     stderr=subprocess.DEVNULL, **kw)
    return True


def sps_avatar_pixmap(meta, size=96, photo=None):
    """Round avatar: the photo if there is one, otherwise a coloured circle with the first letter."""
    pm = QPixmap(size, size); pm.fill(Qt.GlobalColor.transparent)
    p = QPainter(pm)
    p.setRenderHint(QPainter.RenderHint.Antialiasing); p.setRenderHint(QPainter.RenderHint.SmoothPixmapTransform)
    clip = QPainterPath(); clip.addEllipse(0, 0, size, size); p.setClipPath(clip)
    ph = photo if photo is not None else (QPixmap(meta["avatar"]) if meta.get("avatar") else QPixmap())
    if ph is not None and not ph.isNull():
        ph = ph.scaled(size, size, Qt.AspectRatioMode.KeepAspectRatioByExpanding, Qt.TransformationMode.SmoothTransformation)
        p.drawPixmap((size - ph.width()) // 2, (size - ph.height()) // 2, ph)
    else:
        p.fillRect(0, 0, size, size, QColor(meta.get("color", "#1a73e8")))
        p.setPen(QColor("white"))
        f = QFont("Segoe UI"); f.setPixelSize(int(size * 0.46)); f.setBold(True); p.setFont(f)
        p.drawText(QRect(0, 0, size, size), Qt.AlignmentFlag.AlignCenter, ((meta.get("name") or "?").strip()[:1] or "?").upper())
    p.end()
    return pm

def _sps_save_avatar(pm, path):
    s = min(pm.width(), pm.height())
    sq = pm.copy((pm.width() - s) // 2, (pm.height() - s) // 2, s, s)
    sq.scaled(256, 256, Qt.AspectRatioMode.KeepAspectRatio, Qt.TransformationMode.SmoothTransformation).save(path, "PNG")


class _SpsProfileCard(QFrame):
    clicked = pyqtSignal()
    def mouseReleaseEvent(self, ev):
        if ev.button() == Qt.MouseButton.LeftButton:
            ev.accept()
            self.clicked.emit()      # the picker may close and delete this card right here -> never touch self afterwards
            return
        try:
            super().mouseReleaseEvent(ev)
        except RuntimeError:
            pass


class ProfileEditDialog(QDialog):
    """Add / edit a profile in 2 steps:  1) name + photo   2) colour.   pid=None means 'new profile'."""
    def __init__(self, parent=None, pid=None):
        super().__init__(parent)
        self.pid = pid
        meta = sps_profile_meta(pid) if pid else {"name": "", "color": SPS_PROFILE_COLORS[0][0], "avatar": ""}
        self.color = meta["color"]; self._photo = None; self._remove_photo = False; self._has_old_photo = bool(meta["avatar"])
        self.result_id = pid
        self.setWindowTitle("Edit profile" if pid else "Add a profile")
        self.setMinimumWidth(460)
        self.setStyleSheet("QDialog{background:#ffffff;}QLabel{color:#202124;}"
                           "QLineEdit{border:1px solid #dadce0;border-radius:8px;padding:10px;font-size:15px;color:#202124;background:#fff;}"
                           "QLineEdit:focus{border:2px solid #1a73e8;}"
                           "QPushButton{border-radius:8px;padding:9px 18px;font-weight:600;border:none;}")
        lay = QVBoxLayout(self); lay.setSpacing(14); lay.setContentsMargins(28, 24, 28, 22)
        self.stack = QStackedWidget(); lay.addWidget(self.stack)

        # ---- step 1: name + photo ----
        p1 = QWidget(); l1 = QVBoxLayout(p1); l1.setSpacing(12)
        t1 = QLabel("Name your profile" if not pid else "Edit your profile"); t1.setStyleSheet("font-size:22px;font-weight:700;")
        t1.setAlignment(Qt.AlignmentFlag.AlignCenter); l1.addWidget(t1)
        self.preview = QLabel(); self.preview.setAlignment(Qt.AlignmentFlag.AlignCenter); l1.addWidget(self.preview)
        rowp = QHBoxLayout()
        b_up = QPushButton("📷  Upload a photo"); b_up.setStyleSheet("background:#e8f0fe;color:#1a73e8;"); b_up.clicked.connect(self._pick_photo)
        self.b_rm = QPushButton("Remove photo"); self.b_rm.setStyleSheet("background:#f1f3f4;color:#5f6368;"); self.b_rm.clicked.connect(self._clear_photo)
        rowp.addStretch(1); rowp.addWidget(b_up); rowp.addWidget(self.b_rm); rowp.addStretch(1); l1.addLayout(rowp)
        self.name_edit = QLineEdit(meta["name"]); self.name_edit.setPlaceholderText("Profile name, e.g. Work, Personal, Kids")
        self.name_edit.setMaxLength(40); self.name_edit.textChanged.connect(lambda _t: self._refresh_preview())
        l1.addWidget(self.name_edit)
        self.err = QLabel(""); self.err.setStyleSheet("color:#d93025;font-size:12px;"); l1.addWidget(self.err)
        self.stack.addWidget(p1)

        # ---- step 2: colour ----
        p2 = QWidget(); l2 = QVBoxLayout(p2); l2.setSpacing(12)
        t2 = QLabel("Pick a colour"); t2.setStyleSheet("font-size:22px;font-weight:700;"); t2.setAlignment(Qt.AlignmentFlag.AlignCenter); l2.addWidget(t2)
        self.preview2 = QLabel(); self.preview2.setAlignment(Qt.AlignmentFlag.AlignCenter); l2.addWidget(self.preview2)
        sub = QLabel("This colour is used for your profile picture and the browser's accent colour.")
        sub.setWordWrap(True); sub.setStyleSheet("color:#5f6368;"); sub.setAlignment(Qt.AlignmentFlag.AlignCenter); l2.addWidget(sub)
        grid = QGridLayout(); grid.setSpacing(10); self._swatches = {}
        for i, (hexc, nm) in enumerate(SPS_PROFILE_COLORS):
            b = QPushButton(); b.setFixedSize(46, 46); b.setToolTip(nm); b.setCursor(Qt.CursorShape.PointingHandCursor)
            b.clicked.connect(lambda _=False, c=hexc: self._set_color(c))
            grid.addWidget(b, i // 6, i % 6); self._swatches[hexc] = b
        l2.addLayout(grid)
        self.stack.addWidget(p2)

        # ---- buttons ----
        nav = QHBoxLayout()
        self.b_cancel = QPushButton("Cancel"); self.b_cancel.setStyleSheet("background:#f1f3f4;color:#5f6368;"); self.b_cancel.clicked.connect(self.reject)
        self.b_back = QPushButton("Back"); self.b_back.setStyleSheet("background:#f1f3f4;color:#1a73e8;"); self.b_back.clicked.connect(lambda: self._go(0))
        self.b_next = QPushButton("Next"); self.b_next.setStyleSheet("background:#1a73e8;color:white;"); self.b_next.clicked.connect(self._next)
        nav.addWidget(self.b_cancel); nav.addStretch(1); nav.addWidget(self.b_back); nav.addWidget(self.b_next); lay.addLayout(nav)
        self._go(0); self._set_color(self.color)

    def _meta_now(self):
        return {"name": self.name_edit.text().strip() or "?", "color": self.color}

    def _refresh_preview(self):
        ph = self._photo
        if ph is None and not self._remove_photo and self._has_old_photo and self.pid:
            m = dict(self._meta_now(), avatar=sps_profile_meta(self.pid)["avatar"])
        else:
            m = dict(self._meta_now(), avatar="")
        pm = sps_avatar_pixmap(m, 120, ph)
        self.preview.setPixmap(pm); self.preview2.setPixmap(pm)
        self.b_rm.setVisible(ph is not None or (self._has_old_photo and not self._remove_photo))

    def _pick_photo(self):
        path, _f = QFileDialog.getOpenFileName(self, "Choose a profile photo", "", "Images (*.png *.jpg *.jpeg *.bmp *.gif *.webp)")
        if not path:
            return
        pm = QPixmap(path)
        if pm.isNull():
            QMessageBox.warning(self, "Photo", "That file could not be opened as a picture."); return
        self._photo = pm; self._remove_photo = False; self._refresh_preview()

    def _clear_photo(self):
        self._photo = None; self._remove_photo = True; self._refresh_preview()

    def _set_color(self, hexc):
        self.color = hexc
        for c, b in self._swatches.items():
            ring = "3px solid #202124" if c == hexc else "3px solid transparent"
            b.setStyleSheet("QPushButton{background:%s;border:%s;border-radius:23px;}" % (c, ring))
        self._refresh_preview()

    def _go(self, step):
        self.stack.setCurrentIndex(step)
        self.b_back.setVisible(step == 1)
        self.b_next.setText("Next" if step == 0 else ("Save" if self.pid else "Create profile"))
        self._refresh_preview()

    def _next(self):
        if self.stack.currentIndex() == 0:
            if not self.name_edit.text().strip():
                self.err.setText("Please type a name for the profile."); return
            self.err.setText(""); self._go(1); return
        self._save(); self.accept()

    def _save(self):
        name = self.name_edit.text().strip()
        pid = self.pid or sps_profile_make_id(name)
        os.makedirs(os.path.join(PROFILES_DIR, pid), exist_ok=True)
        sps_profile_save_meta(pid, name=name, color=self.color)
        av = os.path.join(PROFILES_DIR, pid, "avatar.png")
        if self._photo is not None:
            _sps_save_avatar(self._photo, av)
        elif self._remove_photo:
            try: os.remove(av)
            except Exception: pass
        self.result_id = pid


class ProfileSelector(QDialog):
    """Chrome-style 'Who's using SPS Browser?' - one card per profile (photo, name, ⋮ menu) + an 'Add profile' card."""
    COLS = 4
    def __init__(self, parent=None):
        super().__init__(parent)
        self.selected_profile = "Default"; self.fresh_restart = False
        self.setWindowTitle("SPS Browser - Who's using SPS Browser?")
        self.resize(960, 660); self.setMinimumSize(720, 520)
        self.setStyleSheet(
            "QDialog{background:#f6f8fc;}QLabel{color:#202124;}"
            "QFrame#pcard{background:#ffffff;border:1px solid #dadce0;border-radius:18px;}"
            "QFrame#pcard:hover{border:2px solid #1a73e8;}"
            "QFrame#padd{background:#ffffff;border:2px dashed #bdc1c6;border-radius:18px;}"
            "QFrame#padd:hover{border:2px dashed #1a73e8;background:#f1f6ff;}"
            "QToolButton{border:none;border-radius:14px;font-size:18px;color:#5f6368;padding:2px 8px;}"
            "QToolButton:hover{background:#e8eaed;}QToolButton::menu-indicator{image:none;}"
            "QPushButton{border-radius:8px;padding:9px 18px;font-weight:600;border:none;}")
        lay = QVBoxLayout(self); lay.setContentsMargins(40, 28, 40, 22); lay.setSpacing(10)
        logo = QLabel(); logo.setAlignment(Qt.AlignmentFlag.AlignCenter)
        ic = _sps_load_app_icon()
        if not ic.isNull():
            logo.setPixmap(ic.pixmap(56, 56))
        lay.addWidget(logo)
        title = QLabel("Who's using SPS Browser?"); title.setAlignment(Qt.AlignmentFlag.AlignCenter)
        title.setStyleSheet("font-size:30px;font-weight:700;"); lay.addWidget(title)
        sub = QLabel("Pick a profile. Each profile has its own history, passwords, bookmarks and settings, and you can have several open at the same time.")
        sub.setWordWrap(True); sub.setAlignment(Qt.AlignmentFlag.AlignCenter); sub.setStyleSheet("color:#5f6368;font-size:13px;"); lay.addWidget(sub)
        self.scroll = QScrollArea(); self.scroll.setWidgetResizable(True); self.scroll.setFrameShape(QFrame.Shape.NoFrame)
        self.scroll.setStyleSheet("background:transparent;")
        lay.addWidget(self.scroll, 1)
        foot = QHBoxLayout()
        self.chk = QCheckBox("Show this window when SPS Browser starts")
        self.chk.setChecked(sps_picker_prefs().get("show_on_startup", True))
        self.chk.stateChanged.connect(lambda _s: sps_picker_prefs_save(show_on_startup=self.chk.isChecked()))
        foot.addWidget(self.chk); foot.addStretch(1); lay.addLayout(foot)
        self._rebuild()

    # ---------- cards ----------
    def _rebuild(self):
        host = QWidget(); host.setStyleSheet("background:transparent;")
        grid = QGridLayout(host); grid.setSpacing(18); grid.setContentsMargins(4, 10, 4, 10)
        ids = sps_profile_ids()
        for i, pid in enumerate(ids):
            grid.addWidget(self._make_card(pid), i // self.COLS, i % self.COLS)
        n = len(ids)
        grid.addWidget(self._make_add_card(), n // self.COLS, n % self.COLS)
        grid.setRowStretch((n // self.COLS) + 1, 1)
        self.scroll.setWidget(host)

    def _make_card(self, pid):
        meta = sps_profile_meta(pid)
        card = _SpsProfileCard(); card.setObjectName("pcard"); card.setFixedSize(200, 250)
        card.setCursor(Qt.CursorShape.PointingHandCursor)
        v = QVBoxLayout(card); v.setContentsMargins(10, 8, 10, 16); v.setSpacing(6)
        top = QHBoxLayout(); top.addStretch(1)
        kebab = QToolButton(); kebab.setText("⋮"); kebab.setToolTip("Edit or delete this profile")
        kebab.setPopupMode(QToolButton.ToolButtonPopupMode.InstantPopup); kebab.setCursor(Qt.CursorShape.ArrowCursor)
        menu = QMenu(kebab)
        menu.addAction("✏️  Edit", lambda p=pid: self._edit(p))
        menu.addAction("🗑  Delete", lambda p=pid: self._delete(p))
        kebab.setMenu(menu)
        top.addWidget(kebab); v.addLayout(top)
        av = QLabel(); av.setAlignment(Qt.AlignmentFlag.AlignCenter); av.setPixmap(sps_avatar_pixmap(meta, 104)); v.addWidget(av)
        nm = QLabel(meta["name"]); nm.setAlignment(Qt.AlignmentFlag.AlignCenter); nm.setWordWrap(True)
        nm.setStyleSheet("font-size:16px;font-weight:600;"); v.addWidget(nm)
        run = sps_profile_running_pid(pid)
        st = QLabel("● Open now" if run else ""); st.setAlignment(Qt.AlignmentFlag.AlignCenter)
        st.setStyleSheet("color:#188038;font-size:12px;font-weight:600;"); v.addWidget(st)
        v.addStretch(1)
        card.clicked.connect(lambda p=pid: self._open(p))
        return card

    def _make_add_card(self):
        card = _SpsProfileCard(); card.setObjectName("padd"); card.setFixedSize(200, 250)
        card.setCursor(Qt.CursorShape.PointingHandCursor)
        v = QVBoxLayout(card); v.setAlignment(Qt.AlignmentFlag.AlignCenter); v.setSpacing(10)
        plus = QLabel("+"); plus.setAlignment(Qt.AlignmentFlag.AlignCenter); plus.setFixedSize(84, 84)
        plus.setStyleSheet("background:#e8f0fe;color:#1a73e8;border-radius:42px;font-size:46px;font-weight:300;")
        v.addWidget(plus, 0, Qt.AlignmentFlag.AlignCenter)
        t = QLabel("Add profile"); t.setAlignment(Qt.AlignmentFlag.AlignCenter); t.setStyleSheet("font-size:16px;font-weight:600;color:#1a73e8;")
        v.addWidget(t)
        card.clicked.connect(self._add)
        return card

    # ---------- actions ----------
    def _open(self, pid):
        run = sps_profile_running_pid(pid)
        if run and run != os.getpid():
            _sps_focus_pid(run)                      # already open in another window -> just show that one
            QMessageBox.information(self, "Already open", "That profile is already open - switched to its window.")
            self.reject(); return
        self.selected_profile = pid; self.fresh_restart = False
        sps_picker_prefs_save(last_profile=pid)
        self.accept()

    def _add(self):
        dlg = ProfileEditDialog(self)
        if dlg.exec() != QDialog.DialogCode.Accepted:
            return
        pid = dlg.result_id
        self._rebuild()
        box = QMessageBox(self); box.setWindowTitle("Profile created")
        box.setIcon(QMessageBox.Icon.Information)
        box.setText("<b>Your profile is ready.</b>")
        box.setInformativeText("SPS Browser needs a quick restart before you can use this profile. "
                               "Restart now to open it, or choose Later and open it from this screen when you like.")
        now = box.addButton("Restart now", QMessageBox.ButtonRole.AcceptRole)
        box.addButton("Later", QMessageBox.ButtonRole.RejectRole)
        box.exec()
        if box.clickedButton() is now:
            self.selected_profile = pid; self.fresh_restart = True
            sps_picker_prefs_save(last_profile=pid)
            self.accept()

    def _edit(self, pid):
        dlg = ProfileEditDialog(self, pid)
        if dlg.exec() == QDialog.DialogCode.Accepted:
            self._rebuild()

    def _delete(self, pid):
        meta = sps_profile_meta(pid)
        if QMessageBox.question(self, "Delete profile",
                                "Delete the profile '%s' and ALL of its data (history, passwords, bookmarks, settings)?\n\nThis cannot be undone." % meta["name"]
                                ) != QMessageBox.StandardButton.Yes:
            return
        err = sps_profile_delete(pid)
        if err:
            QMessageBox.warning(self, "Delete profile", err)
        self._rebuild()



