    def _build_ui(self):
        t = self.t
        lay = QVBoxLayout(self)
        title = QLabel("⚑ SPS Browser Flags — Experimental Features")
        title.setStyleSheet(f"font-size:18px;font-weight:700;color:{t['accent']};padding:8px 0;")
        lay.addWidget(title)

        warn = QLabel("⚠️  These features are experimental. Changes take effect after restart.")
        warn.setStyleSheet(f"background:#fff3cd;color:#856404;border-radius:6px;padding:8px;font-size:12px;")
        lay.addWidget(warn)

        # Search
        self.search_edit = QLineEdit(); self.search_edit.setPlaceholderText("Search flags…")
        self.search_edit.setStyleSheet(f"background:{t['bg_secondary']};color:{t['text_primary']};border:1px solid {t['border']};border-radius:6px;padding:6px;")
        self.search_edit.textChanged.connect(self._filter_flags)
        lay.addWidget(self.search_edit)

        scroll = QScrollArea(); scroll.setWidgetResizable(True)
        scroll.setStyleSheet(f"border:none;background:{t['bg_primary']};")
        container = QWidget()
        self.flags_layout = QVBoxLayout(container)
        self.flag_rows = []
        categories = {}
        for flag in self.FLAGS:
            cat = flag[3]
            if cat not in categories:
                categories[cat] = []
            categories[cat].append(flag)
        for cat, flags in categories.items():
            cat_lbl = QLabel(f"  {cat}")
            cat_lbl.setStyleSheet(f"font-size:13px;font-weight:700;color:{t['text_secondary']};background:{t['bg_tertiary']};padding:6px 8px;border-radius:6px;margin-top:4px;")
            self.flags_layout.addWidget(cat_lbl)
            for key, label, desc, _ in flags:
                row = QWidget()
                row.setStyleSheet(f"background:{t['bg_secondary']};border-radius:8px;margin:2px 0;")
                rl = QHBoxLayout(row); rl.setContentsMargins(12,8,12,8)
                info_col = QVBoxLayout()
                lbl_w = QLabel(label); lbl_w.setStyleSheet(f"font-size:13px;font-weight:600;color:{t['text_primary']};")
                desc_w = QLabel(desc); desc_w.setStyleSheet(f"font-size:11px;color:{t['text_secondary']};")
                info_col.addWidget(lbl_w); info_col.addWidget(desc_w)
                cb = QCheckBox()
                cb.setChecked(bool(self.settings.get(key, False)))
                cb.stateChanged.connect(lambda state, k=key: self.settings.update({k: bool(state)}))
                rl.addLayout(info_col, 1); rl.addWidget(cb)
                self.flags_layout.addWidget(row)
                self.flag_rows.append((row, label+" "+desc, cat))
        scroll.setWidget(container)
        lay.addWidget(scroll, 1)

        btn_row = QHBoxLayout()
        save_btn = QPushButton("💾 Save Flags")
        reset_btn = QPushButton("↺ Reset All to Default")
        save_btn.setStyleSheet(f"background:{t['accent']};color:white;border-radius:8px;padding:8px 16px;font-weight:700;")
        reset_btn.setStyleSheet(f"background:{t['bg_secondary']};color:{t['text_primary']};border-radius:8px;padding:8px 16px;border:1px solid {t['border']};")
        save_btn.clicked.connect(self.accept)
        reset_btn.clicked.connect(self._reset_all)
        btn_row.addWidget(save_btn); btn_row.addWidget(reset_btn)
        lay.addLayout(btn_row)

    def _filter_flags(self, text):
        text = text.lower()
        for row, searchable, cat in self.flag_rows:
            row.setVisible(text in searchable.lower() or text in cat.lower() or not text)

    def _reset_all(self):
        for key, *_ in self.FLAGS:
            if key in DEFAULT_SETTINGS:
                self.settings[key] = DEFAULT_SETTINGS[key]
        self.accept()
        QMessageBox.information(self, "Reset", "Flags reset to defaults. Restart the browser to apply.")


