#  V28 ── EXTENSION OVERFLOW TOOLBAR (Chrome-style puzzle menu)
# ═══════════════════════════════════════════════════════════════
class ExtensionOverflowMenu(QMenu):
    """
    When 2+ extensions are toolbar-visible, a single 🧩 button is shown.
    Clicking it opens this popup menu listing all extensions with their icons.
    Clicking an extension item runs it.
    """
    def __init__(self, extensions, run_callback, theme, parent=None):
        super().__init__(parent)
        t = theme
        self.setStyleSheet(
            f"QMenu{{background:{t['bg_primary']};border:1px solid {t['border']};"
            f"border-radius:10px;padding:6px;min-width:220px;}}"
            f"QMenu::item{{padding:10px 16px;border-radius:6px;color:{t['text_primary']};font-size:13px;}}"
            f"QMenu::item:selected{{background:{t['accent_light']};color:{t['accent']};}}"
        )
        header = QAction("Extensions", self)
        header.setEnabled(False)
        self.addAction(header)
        self.addSeparator()
        for ext in extensions:
            icon_text = ext.get("icon", "🧩")
            name = ext.get("name", "Extension")
            act = QAction(f"{icon_text}  {name}", self)
            act.setToolTip(ext.get("description", ""))
            ext_ref = ext
            act.triggered.connect(lambda checked=False, e=ext_ref: run_callback(e))
            self.addAction(act)
        self.addSeparator()
        manage_act = QAction("⚙️  Manage Extensions…", self)
        self.addAction(manage_act)


