class ToolbarCustomizerDialog(QDialog):
    """V28 — Drag-and-reorder toolbar buttons, add/remove items. Like Chrome's toolbar customization."""
    def __init__(self, settings, theme, parent=None):
        super().__init__(parent)
        self.settings = settings
        t = theme; self.t = t
        self.setWindowTitle("🔧 Customize Toolbar")
        self.resize(520, 480)
        self.setStyleSheet(f"background:{t['bg_primary']};color:{t['text_primary']};")
        self._build_ui()

    ALL_BUTTONS = [
        ("sidebar_toggle", "☰ Sidebar Toggle"),
        ("back", "← Back"),
        ("forward", "→ Forward"),
        ("reload", "↻ Reload"),
        ("home", "🏠 Home"),
        ("search_engine", "🔍 Search Engine Picker"),
        ("url_bar", "🔗 URL Bar"),
        ("lock", "🔒 Security Lock"),
        ("bookmark", "⭐ Bookmark"),
        ("zoom_out", "− Zoom Out"),
        ("zoom_label", "🔍 Zoom Level"),
        ("zoom_in", "+ Zoom In"),
        ("ai_hub", "🤖 AI Hub"),
        ("screenshot", "📸 Screenshot"),
        ("reader_mode", "📖 Reader Mode"),
        ("find_in_page", "🔍 Find in Page"),
        ("extensions", "🧩 Extensions"),
        ("downloads", "⬇ Downloads"),
        ("menu", "⋮ Main Menu"),
    ]

    def _build_ui(self):
        t = self.t
        lay = QVBoxLayout(self)
        title = QLabel("🔧 Customize Toolbar")
        title.setStyleSheet(f"font-size:18px;font-weight:700;color:{t['accent']};padding:8px 0;")
        lay.addWidget(title)
        info = QLabel("Toggle toolbar items on/off. Changes apply after restarting the browser or clicking Apply.")
        info.setStyleSheet(f"color:{t['text_secondary']};font-size:12px;padding:4px;"); info.setWordWrap(True)
        lay.addWidget(info)
        scroll = QScrollArea(); scroll.setWidgetResizable(True); scroll.setStyleSheet(f"border:none;")
        container = QWidget()
        vl = QVBoxLayout(container)
        hidden = self.settings.get("toolbar_hidden_buttons", [])
        self.checks = {}
        for key, label in self.ALL_BUTTONS:
            row = QFrame(); row.setStyleSheet(f"background:{t['bg_secondary']};border-radius:8px;margin:2px;")
            rl = QHBoxLayout(row); rl.setContentsMargins(12,8,12,8)
            lbl = QLabel(label); lbl.setStyleSheet(f"font-size:13px;color:{t['text_primary']};")
            cb = QCheckBox(); cb.setChecked(key not in hidden)
            self.checks[key] = cb
            rl.addWidget(lbl, 1); rl.addWidget(cb)
            vl.addWidget(row)
        scroll.setWidget(container)
        lay.addWidget(scroll, 1)
        btn_row = QHBoxLayout()
        apply_btn = QPushButton("✅ Apply")
        reset_btn = QPushButton("↺ Reset")
        apply_btn.setStyleSheet(f"background:{t['accent']};color:white;border-radius:8px;padding:8px 16px;font-weight:700;")
        reset_btn.setStyleSheet(f"background:{t['bg_secondary']};color:{t['text_primary']};border-radius:8px;padding:8px 16px;border:1px solid {t['border']};")
        apply_btn.clicked.connect(self._apply); reset_btn.clicked.connect(self._reset)
        btn_row.addWidget(apply_btn); btn_row.addWidget(reset_btn)
        lay.addLayout(btn_row)

    def _apply(self):
        hidden = [key for key, cb in self.checks.items() if not cb.isChecked()]
        self.settings["toolbar_hidden_buttons"] = hidden
        self.accept()

    def _reset(self):
        for cb in self.checks.values(): cb.setChecked(True)


