import gc
import socket
import ipaddress

def _app_dir():
    """Folder that contains the browser (works from source AND from a PyInstaller setup.exe)."""
    if getattr(sys, "frozen", False):
        return os.path.dirname(os.path.abspath(sys.executable))
    return os.path.dirname(os.path.abspath(__file__))

APP_DIR = _app_dir()
LOCAL_AI_MODELS_DIR = os.path.join(APP_DIR, "local_ai", "models")          # ← put the .gguf files here
LOCAL_AI_LEGACY_DIR = os.path.join(BASE_DATA_DIR, "local_ai_models")        # old per-user folder (fallback only)
LOCAL_AI_SANDBOX_DIR = os.path.join(BASE_DATA_DIR, "local_ai_sandbox")
for _d in (LOCAL_AI_MODELS_DIR, LOCAL_AI_SANDBOX_DIR, SHARED_MODELS_DIR):
    try:
        os.makedirs(_d, exist_ok=True)
    except Exception:
        pass   # e.g. read-only install folder — the models folder is created by the installer instead
try:   # put the how-to next to the shared models folder
    _rd = os.path.join(LOCAL_AI_MODELS_DIR, "README_AI_MODELS.txt")
    _rt = os.path.join(SHARED_MODELS_DIR, "README_AI_MODELS.txt")
    if os.path.isfile(_rd) and not os.path.exists(_rt):
        shutil.copy2(_rd, _rt)
except Exception:
    pass

