def _local_ai_find_model(filename):
    """Return the full path of a model file (project folder first), or ''."""
    for d in (LOCAL_AI_MODELS_DIR, SHARED_MODELS_DIR, LOCAL_AI_LEGACY_DIR):
        p = os.path.join(d, filename)
        if os.path.isfile(p) and os.path.getsize(p) > 50 * 1024 * 1024:
            return p
    return ""

def _local_ai_all_models():
    """Known models + any other .gguf the user dropped into the models folder."""
    models = list(LOCAL_AI_MODELS)
    known = {m[2].lower() for m in models}
    for d in (LOCAL_AI_MODELS_DIR, SHARED_MODELS_DIR, LOCAL_AI_LEGACY_DIR):
        try:
            for fn in sorted(os.listdir(d)):
                if fn.lower().endswith(".gguf") and fn.lower() not in known:
                    known.add(fn.lower())
                    models.append((os.path.splitext(fn)[0] + " 📦", "", fn, 2500, "Custom model from your models folder"))
        except Exception:
            pass
    return models



