def sps_legal_file(name):
    """Full text of LICENSE.txt / SPS_BROWSER_NOTICE.txt / THIRD_PARTY_NOTICES.txt (next to the exe, in the bundle, or next to the sources)."""
    roots = [APP_DIR, os.path.join(APP_DIR, "legal"), getattr(sys, "_MEIPASS", ""), os.path.dirname(os.path.abspath(__file__)),
             os.path.dirname(os.path.dirname(os.path.abspath(__file__)))]
    for r in roots:
        p = os.path.join(r, name) if r else ""
        if p and os.path.isfile(p):
            try:
                with open(p, "rb") as f:
                    return f.read().decode("utf-8", "replace").replace("\r\n", "\n")
            except Exception:
                pass
    return "(The file %s was not found next to the program. Reinstall SPS Browser to restore it.)" % name


