def _sps_load_app_icon():
    """The SPS Browser logo (assets/sps_browser.ico / .png next to the exe). Falls back to an empty icon."""
    roots = [APP_DIR, os.path.join(APP_DIR, "assets"), getattr(sys, "_MEIPASS", ""),
             os.path.join(getattr(sys, "_MEIPASS", ""), "assets"), os.path.dirname(os.path.abspath(__file__))]
    for r in roots:
        for n in ("sps_browser.ico", "sps_browser.png"):
            p = os.path.join(r, n) if r else ""
            if p and os.path.isfile(p):
                ic = QIcon(p)
                if not ic.isNull():
                    return ic
    return QIcon()

