class HFDownloadError(Exception):
    """code: restricted | not_found | disk | network | hash | bad_file | cancelled"""
    def __init__(self, code, message):
        super().__init__(message)
        self.code = code
        self.message = message

# ── the downloader ──
def _hf_get_following(url, headers, have, timeout=(15, 60)):
    """GET with manual redirects (no cookies, no credentials are ever sent)."""
    import requests
    first_meta = {}
    cur = url
    for _hop in range(8):
        h = dict(headers)
        if have:
            h["Range"] = "bytes=%d-" % have
        r = requests.get(cur, headers=h, stream=True, allow_redirects=False, timeout=timeout)
        for k in ("X-Linked-Etag", "X-Linked-Size"):
            if k not in first_meta and r.headers.get(k):
                first_meta[k] = r.headers.get(k)
        if r.status_code in (301, 302, 303, 307, 308) and r.headers.get("Location"):
            cur = _hf_up.urljoin(cur, r.headers["Location"])
            r.close()
            continue
        return r, first_meta
    raise HFDownloadError("network", "Too many redirects.")

def _hf_download_once(repo, filename, dest_dir, progress, cancel, base_url):
    import requests
    final = os.path.join(dest_dir, filename)
    part = final + ".part"
    url = "%s/%s/resolve/main/%s" % (base_url, repo, _hf_up.quote(filename))
    have = os.path.getsize(part) if os.path.isfile(part) else 0
    hdr = {"User-Agent": "SPS-Browser/35 model-downloader"}

    try:
        r, meta = _hf_get_following(url, hdr, have)
    except requests.RequestException as e:
        raise HFDownloadError("network", "Connection problem: %s" % e)

    sc = r.status_code
    if sc in (401, 403):
        r.close()
        raise HFDownloadError("restricted",
            "The publisher of this model requires a Hugging Face account to download it, so it cannot be downloaded here. "
            "Open the model page (the i button), download the file in your browser, and put it in the models folder.")
    if sc == 404:
        r.close()
        raise HFDownloadError("not_found", "File not found on Hugging Face (it may have been renamed).")

    total = 0
    if sc == 416 and have:                         # the .part file already has everything
        cr = r.headers.get("Content-Range", "")
        m = re.search(r"/(\d+)$", cr)
        total = int(m.group(1)) if m else have
        r.close()
        if total != have:
            os.remove(part); have = 0
            raise HFDownloadError("network", "Partial file was damaged - please press Download again.")
    elif sc in (200, 206):
        if sc == 206:
            m = re.search(r"/(\d+)$", r.headers.get("Content-Range", ""))
            total = int(m.group(1)) if m else have + int(r.headers.get("Content-Length", 0) or 0)
        else:
            have = 0                                   # server ignored Range -> start from the beginning
            total = int(r.headers.get("Content-Length", 0) or meta.get("X-Linked-Size", 0) or 0)
    else:
        r.close()
        raise HFDownloadError("network", "Unexpected answer from the server (HTTP %d)." % sc)

    if total:
        try:
            free = shutil.disk_usage(dest_dir).free
            if free < (total - have) + 300 * 1024 * 1024:
                r.close()
                raise HFDownloadError("disk", "Not enough free disk space: need about %.1f GB, only %.1f GB free."
                                      % ((total - have) / 1024**3, free / 1024**3))
        except OSError:
            pass

    sha = _hf_hashlib.sha256()
    if sc != 416:
        mode = "ab" if (have and sc == 206) else "wb"
        if mode == "ab":
            with open(part, "rb") as pf:               # re-hash what we already have
                for chunk in iter(lambda: pf.read(8 * 1024 * 1024), b""):
                    sha.update(chunk)
        done = have if mode == "ab" else 0
        try:
            with open(part, mode) as out:
                for chunk in r.iter_content(chunk_size=1024 * 1024):
                    if cancel is not None and cancel.is_set():
                        raise HFDownloadError("cancelled", "Paused.")
                    if not chunk:
                        continue
                    out.write(chunk); sha.update(chunk); done += len(chunk)
                    if progress: progress(done, total)
        except requests.RequestException as e:
            raise HFDownloadError("network", "Connection lost: %s" % e)
        finally:
            r.close()
        if total and done != total:
            raise HFDownloadError("network", "Connection lost before the download finished.")
    else:
        with open(part, "rb") as pf:
            for chunk in iter(lambda: pf.read(8 * 1024 * 1024), b""):
                sha.update(chunk)

    expected = (meta.get("X-Linked-Etag") or "").strip('"').lower()
    if re.fullmatch(r"[0-9a-f]{64}", expected) and sha.hexdigest() != expected:
        try: os.remove(part)
        except OSError: pass
        raise HFDownloadError("hash", "The downloaded file is damaged (checksum does not match). It was deleted - please download again.")
    with open(part, "rb") as pf:
        if pf.read(4) != b"GGUF":
            try: os.remove(part)
            except OSError: pass
            raise HFDownloadError("bad_file", "The downloaded file is not a valid .gguf model.")
    os.replace(part, final)
    return final

def hf_download(repo, filename, dest_dir, progress=None, cancel=None, base_url=HF_BASE_URL, retries=3):
    """Download one model file. Returns its final path. Raises HFDownloadError."""
    os.makedirs(dest_dir, exist_ok=True)
    attempt = 0
    while True:
        try:
            return _hf_download_once(repo, filename, dest_dir, progress, cancel, base_url)
        except HFDownloadError as e:
            if e.code == "network" and attempt < retries and not (cancel is not None and cancel.is_set()):
                attempt += 1
                time.sleep(min(2 * attempt, 6))          # connection dropped -> resume automatically
                continue
            raise

def hf_models_dir():
    """First writable models folder (shared C:\\SPS_Browser\\local_ai\\models, else the one next to the exe)."""
    for d in (SHARED_MODELS_DIR, LOCAL_AI_MODELS_DIR):
        try:
            os.makedirs(d, exist_ok=True)
            t = os.path.join(d, ".write_test")
            with open(t, "w") as f: f.write("x")
            os.remove(t)
            return d
        except Exception:
            continue
    return SHARED_MODELS_DIR


# ── brain of the "Download AI models" window (no Qt in here, so it can be tested without a screen) ──
class ModelDownloadController:
    MIN_MODEL_BYTES = 50 * 1024 * 1024          # smaller files are treated as damaged / not installed

    def __init__(self, base_dir, models=None, base_url=HF_BASE_URL, dest_dir=None):
        self.base_dir = base_dir
        self.models = list(models if models is not None else LOCAL_AI_MODELS)
        self.base_url = base_url
        self._dest = dest_dir
        self._lock = threading.Lock()
        self._jobs = {}                       # filename -> dict
        self._lic_path = os.path.join(base_dir, "model_licenses_accepted.json")

    # ----- catalog -----
    def dest_dir(self):
        return self._dest or hf_models_dir()

    def entries(self):
        out = []
        for m in self.models:
            label, repo, fn, ram, desc = m[0], m[1], m[2], m[3], m[4]
            if not repo:
                continue                       # custom files the user dropped in are not downloadable
            info = MODEL_DL_INFO.get(fn, {})
            out.append(dict(label=label, repo=repo, repos=[repo] + list(info.get("alt_repos", [])), filename=fn, ram_mb=ram, desc=desc, info=info,
                            size_mb=info.get("size_mb", ram), manual=bool(info.get("manual"))))
        return out

    def _entry(self, filename):
        for e in self.entries():
            if e["filename"] == filename:
                return e
        return None

    def installed_path(self, filename):
        p = os.path.join(self.dest_dir(), filename)
        if os.path.isfile(p) and os.path.getsize(p) >= self.MIN_MODEL_BYTES:
            return p
        try:
            return _local_ai_find_model(filename) or ""
        except Exception:
            return ""

    # ----- licence acceptance (just a click - no account) -----
    def license_accepted(self, filename):
        try:
            with open(self._lic_path, encoding="utf-8") as f:
                return filename in json.load(f)
        except Exception:
            return False

    def accept_license(self, filename):
        try:
            data = {}
            if os.path.isfile(self._lic_path):
                with open(self._lic_path, encoding="utf-8") as f:
                    data = json.load(f)
            data[filename] = time.strftime("%Y-%m-%d %H:%M:%S")
            os.makedirs(self.base_dir, exist_ok=True)
            with open(self._lic_path, "w", encoding="utf-8") as f:
                json.dump(data, f, indent=1)
        except Exception:
            pass

    # ----- state for the window -----
    def snapshot(self, filename):
        e = self._entry(filename) or {}
        with self._lock:
            job = dict(self._jobs.get(filename) or {})
        running = bool(job) and job.get("state") == "downloading"
        inst = self.installed_path(filename)
        part = os.path.join(self.dest_dir(), filename + ".part")
        part_bytes = os.path.getsize(part) if os.path.isfile(part) else 0
        if running:
            state = "downloading"
        elif inst:
            state = "installed"
        elif e.get("manual"):
            state = "manual"
        elif job.get("state") == "error":
            state = "error"
        elif part_bytes:
            state = "paused"
        else:
            state = "idle"
        done = job.get("done", part_bytes) if running else part_bytes
        total = job.get("total", 0) or (e.get("size_mb", 0) * 1024 * 1024)
        speed = job.get("speed", 0.0) if running else 0.0
        eta = int((total - done) / speed) if (running and speed > 1 and total > done) else 0
        return dict(state=state, done=done, total=total, speed=speed, eta=eta,
                    error=job.get("error", "") if state == "error" else "",
                    code=job.get("code", "") if state == "error" else "", path=inst)

    def any_running(self):
        with self._lock:
            return any(j.get("state") == "downloading" for j in self._jobs.values())

    # ----- actions -----
    def start(self, filename):
        e = self._entry(filename)
        if not e or e["manual"]:
            return False
        with self._lock:
            j = self._jobs.get(filename)
            if j and j.get("state") == "downloading":
                return False
            cancel = threading.Event()
            job = dict(state="downloading", done=0, total=0, speed=0.0, cancel=cancel, samples=[], error="", code="")
            self._jobs[filename] = job
        t = threading.Thread(target=self._run, args=(e, job), daemon=True, name="sps-model-dl")
        job["thread"] = t
        t.start()
        return True

    def _run(self, e, job):
        def progress(done, total):
            now = time.time()
            s = job["samples"]
            s.append((now, done))
            while len(s) > 2 and now - s[0][0] > 4:
                s.pop(0)
            sp = (done - s[0][1]) / max(0.001, now - s[0][0]) if len(s) > 1 else 0.0
            with self._lock:
                job.update(done=done, total=total, speed=sp)
        try:
            repos = e.get("repos") or [e["repo"]]
            for _i, _repo in enumerate(repos):
                try:
                    hf_download(_repo, e["filename"], self.dest_dir(), progress=progress,
                                cancel=job["cancel"], base_url=self.base_url)
                    break
                except HFDownloadError as _ex:
                    if _ex.code in ("restricted", "not_found") and _i < len(repos) - 1:
                        continue                  # try the next mirror repo of the same file
                    raise
            with self._lock:
                job.update(state="done", speed=0.0)
        except HFDownloadError as ex:
            with self._lock:
                if ex.code == "cancelled":
                    job.update(state="paused", speed=0.0)
                else:
                    job.update(state="error", error=ex.message, code=ex.code, speed=0.0)
        except Exception as ex:
            with self._lock:
                job.update(state="error", error="Unexpected problem: %s" % ex, code="unexpected", speed=0.0)

    def pause(self, filename):
        with self._lock:
            j = self._jobs.get(filename)
        if j and j.get("cancel"):
            j["cancel"].set()

    def delete(self, filename):
        """Remove the model file (and any half-downloaded part). Returns '' or an error text."""
        self.pause(filename)
        err = ""
        for p in {self.installed_path(filename), os.path.join(self.dest_dir(), filename),
                  os.path.join(self.dest_dir(), filename + ".part")}:
            if p and os.path.isfile(p):
                try:
                    os.remove(p)
                except Exception as ex:
                    err = "Could not delete %s: %s" % (os.path.basename(p), ex)
        with self._lock:
            self._jobs.pop(filename, None)
        return err

    def cancel_all(self, wait=3.0):
        with self._lock:
            jobs = list(self._jobs.values())
        for j in jobs:
            if j.get("cancel"):
                j["cancel"].set()
        end = time.time() + wait
        for j in jobs:
            t = j.get("thread")
            if t and t.is_alive():
                t.join(max(0.0, end - time.time()))


def _mdl_fmt_size(n):
    return "%.1f GB" % (n / 1024**3) if n >= 1024**3 else "%d MB" % (n / 1024**2)

def _mdl_fmt_eta(sec):
    if sec <= 0:
        return ""
    return "%d min %02d s" % (sec // 60, sec % 60) if sec >= 60 else "%d s" % sec


class ModelDownloadDialog(QDialog):
    """⬇ Download AI models - free, no account, no token. Pause / resume, checksum-verified."""
    def __init__(self, theme, open_url, controller, on_change=None, parent=None):
        super().__init__(parent)
        self.t = theme; self.ctl = controller; self._open_url = open_url; self._on_change = on_change
        self._rows = {}; self._last_state = {}
        t = theme
        self.setWindowTitle("⬇ Download AI models")
        self.resize(720, 560)
        self.setStyleSheet(
            f"QDialog{{background:{t['bg_primary']};color:{t['text_primary']};}}"
            f"QLabel{{color:{t['text_primary']};}}"
            f"QFrame#mrow{{background:{t['bg_secondary']};border:1px solid {t['border']};border-radius:10px;}}"
            f"QPushButton{{background:{t['accent']};color:white;border:none;border-radius:8px;padding:7px 14px;font-weight:600;}}"
            f"QPushButton:hover{{background:{t['accent']}cc;}}"
            f"QPushButton:disabled{{background:{t['bg_tertiary']};color:{t['text_secondary']};}}"
            f"QPushButton#ghost{{background:transparent;color:{t['text_primary']};border:1px solid {t['border']};}}"
            f"QProgressBar{{border:none;background:{t['bg_tertiary']};border-radius:5px;height:10px;text-align:center;}}"
            f"QProgressBar::chunk{{background:{t['accent']};border-radius:5px;}}")
        lay = QVBoxLayout(self); lay.setSpacing(10)
        head = QLabel("<b style='font-size:17px'>Download AI models</b><br>"
                      "<span style='color:%s'>Free · no account · no token. Files are saved on this PC and the AI runs fully offline. "
                      "Downloads can be paused and resumed, and every file is verified.</span>" % t["text_secondary"])
        head.setWordWrap(True); lay.addWidget(head)
        self.where = QLabel(); self.where.setWordWrap(True)
        self.where.setStyleSheet(f"color:{t['text_secondary']};font-size:11px;"); lay.addWidget(self.where)
        scroll = QScrollArea(); scroll.setWidgetResizable(True); scroll.setFrameShape(QFrame.Shape.NoFrame)
        host = QWidget(); self.rows_lay = QVBoxLayout(host); self.rows_lay.setSpacing(8); self.rows_lay.setContentsMargins(0, 0, 4, 0)
        for e in self.ctl.entries():
            self._add_row(e)
        self.rows_lay.addStretch(1)
        scroll.setWidget(host); lay.addWidget(scroll, 1)
        foot = QHBoxLayout()
        b_folder = QPushButton("📂 Open models folder"); b_folder.setObjectName("ghost"); b_folder.clicked.connect(self._open_folder)
        b_close = QPushButton("Close"); b_close.clicked.connect(self.close)
        foot.addWidget(b_folder); foot.addStretch(1); foot.addWidget(b_close); lay.addLayout(foot)
        self._timer = QTimer(self); self._timer.timeout.connect(self._refresh); self._timer.start(400)
        self._refresh()

    def _add_row(self, e):
        t = self.t; fn = e["filename"]; info = e["info"]
        fr = QFrame(); fr.setObjectName("mrow")
        g = QGridLayout(fr); g.setContentsMargins(12, 10, 12, 10); g.setHorizontalSpacing(10)
        title = QLabel("<b>%s</b>" % e["label"]); sub = QLabel("%s · %s · needs about %s RAM" % (
            e["desc"].split(" — ")[0], _mdl_fmt_size(e["size_mb"] * 1024 * 1024), _mdl_fmt_size(e["ram_mb"] * 1024 * 1024)))
        sub.setStyleSheet(f"color:{t['text_secondary']};font-size:11px;")
        lic = QLabel("License: %s" % info.get("license", "see model page")); lic.setStyleSheet(f"color:{t['text_secondary']};font-size:11px;")
        status = QLabel(""); status.setWordWrap(True); status.setStyleSheet(f"color:{t['text_secondary']};font-size:11px;")
        bar = QProgressBar(); bar.setRange(0, 1000); bar.setTextVisible(False); bar.setFixedHeight(10)
        main = QPushButton("⬇ Download"); main.setMinimumWidth(130)
        main.clicked.connect(lambda _=False, f=fn: self._on_main(f))
        dele = QPushButton("🗑"); dele.setObjectName("ghost"); dele.setToolTip("Delete this model from the PC"); dele.setFixedWidth(40)
        dele.clicked.connect(lambda _=False, f=fn: self._on_delete(f))
        page = QPushButton("ⓘ"); page.setObjectName("ghost"); page.setToolTip("Open the model page"); page.setFixedWidth(40)
        page.clicked.connect(lambda _=False, u=info.get("page", ""): u and self._open_url(u))
        g.addWidget(title, 0, 0); g.addWidget(page, 0, 1); g.addWidget(main, 0, 2); g.addWidget(dele, 0, 3)
        g.addWidget(sub, 1, 0, 1, 2); g.addWidget(lic, 2, 0, 1, 2)
        g.addWidget(bar, 3, 0, 1, 4); g.addWidget(status, 4, 0, 1, 4)
        g.setColumnStretch(0, 1)
        self.rows_lay.addWidget(fr)
        self._rows[fn] = dict(main=main, dele=dele, bar=bar, status=status)

    # ----- button handlers -----
    def _on_main(self, fn):
        s = self.ctl.snapshot(fn)["state"]
        if s == "downloading":
            self.ctl.pause(fn)
        elif s in ("idle", "paused", "error"):
            if not self.ctl.license_accepted(fn) and not self._ask_license(fn):
                return
            self.ctl.start(fn)
        elif s == "manual":
            info = MODEL_DL_INFO.get(fn, {})
            QMessageBox.information(self, "Add this model manually", info.get("note", "") +
                                    "\n\nModels folder:\n" + self.ctl.dest_dir())
        self._refresh()

    def _ask_license(self, fn):
        info = MODEL_DL_INFO.get(fn, {}); e = self.ctl._entry(fn) or {}
        box = QMessageBox(self); box.setWindowTitle("Before you download")
        box.setIcon(QMessageBox.Icon.Information)
        box.setText("<b>%s</b> is published under the <b>%s</b> license." % (e.get("label", fn), info.get("license", "model")))
        box.setInformativeText(info.get("note", "") + "\n\nBy downloading you agree to follow that license.")
        ok = box.addButton("I agree — download", QMessageBox.ButtonRole.AcceptRole)
        rd = box.addButton("Read the license", QMessageBox.ButtonRole.ActionRole)
        box.addButton("Cancel", QMessageBox.ButtonRole.RejectRole)
        box.exec()
        clicked = box.clickedButton()
        if clicked is rd:
            self._open_url(info.get("license_url") or info.get("page", ""))
            return False
        if clicked is ok:
            self.ctl.accept_license(fn)
            return True
        return False

    def _on_delete(self, fn):
        s = self.ctl.snapshot(fn)
        if s["state"] not in ("installed", "paused", "downloading", "error") and not s["done"]:
            return
        if QMessageBox.question(self, "Delete model", "Delete this model from the PC?\n(You can download it again later.)") \
                == QMessageBox.StandardButton.Yes:
            err = self.ctl.delete(fn)
            if err:
                QMessageBox.warning(self, "Delete", err)
            if self._on_change:
                self._on_change()
            self._refresh()

    def _open_folder(self):
        d = self.ctl.dest_dir()
        try: os.makedirs(d, exist_ok=True)
        except Exception: pass
        QDesktopServices.openUrl(QUrl.fromLocalFile(d))

    # ----- live refresh -----
    def _refresh(self):
        self.where.setText("Saved in: %s" % self.ctl.dest_dir())
        for fn, w in self._rows.items():
            s = self.ctl.snapshot(fn)
            st = s["state"]
            prev = self._last_state.get(fn)
            if prev != st:
                self._last_state[fn] = st
                if st == "installed" and prev == "downloading" and self._on_change:
                    self._on_change()                      # new model finished -> AI panel re-scans
            frac = int(1000 * s["done"] / s["total"]) if s["total"] else 0
            w["bar"].setValue(min(1000, max(0, frac)))
            w["bar"].setVisible(st in ("downloading", "paused", "error") and s["done"] > 0 or st == "downloading")
            w["dele"].setVisible(st in ("installed", "paused", "error") and (st == "installed" or s["done"] > 0))
            if st == "downloading":
                eta = _mdl_fmt_eta(s["eta"])
                w["main"].setText("⏸ Pause"); w["main"].setEnabled(True)
                w["status"].setText("%s of %s · %.1f MB/s%s" % (_mdl_fmt_size(s["done"]), _mdl_fmt_size(s["total"]),
                                    s["speed"] / 1048576, (" · " + eta + " left") if eta else ""))
            elif st == "installed":
                w["main"].setText("✅ Installed"); w["main"].setEnabled(False)
                w["status"].setText("Ready to use — pick it in the AI model menu.")
            elif st == "paused":
                w["main"].setText("▶ Resume"); w["main"].setEnabled(True)
                w["status"].setText("Paused at %s of %s" % (_mdl_fmt_size(s["done"]), _mdl_fmt_size(s["total"])))
            elif st == "error":
                w["main"].setText("↻ Try again"); w["main"].setEnabled(True)
                w["status"].setText("⚠ " + s["error"])
            elif st == "manual":
                w["main"].setText("How to add"); w["main"].setEnabled(True)
                w["status"].setText("Publisher requires a login, so this one is added manually.")
            else:
                w["main"].setText("⬇ Download"); w["main"].setEnabled(True)
                w["status"].setText("")

    def shutdown(self):
        self._timer.stop(); self.ctl.cancel_all()


def _local_ai_detect_best_model():
    """Best INSTALLED model that fits in free RAM (falls back to any installed one)."""
    try:
        import psutil
        free_mb = psutil.virtual_memory().available // (1024 * 1024)
    except Exception:
        free_mb = 2500
    models = _local_ai_all_models()
    installed = [m for m in models if _local_ai_find_model(m[2])]
    if not installed:
        return models[0]
    best = installed[0]
    for m in installed:
        if free_mb >= m[3] + 400:
            best = m
    return best

def _local_ai_default_ctx(filename):
    f = filename.lower()
    if "tinyllama" in f:
        return 2048
    if "coder" in f:                      # code/agent work needs room for tools + files
        return 8192
    if "deepseek" in f or "r1-distill" in f:      # reasoning models write long "thoughts"
        return 6144
    return 4096

# ── internet tools (only used after the user says yes) ───────────
def _local_ai_url_is_public(url):
    """Refuse non-http(s) URLs and anything pointing at this PC / the home network."""
    try:
        pu = urlparse(url)
        if pu.scheme not in ("http", "https") or not pu.hostname:
            return False
        for info in socket.getaddrinfo(pu.hostname, None):
            ip = ipaddress.ip_address(info[4][0])
            if ip.is_private or ip.is_loopback or ip.is_link_local or ip.is_reserved or ip.is_multicast:
                return False
        return True
    except Exception:
        return False

_WS_UA = "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/124.0.0.0 Safari/537.36"
_WS_HEADERS = {"User-Agent": _WS_UA, "Accept": "text/html,application/xhtml+xml,application/json;q=0.9,*/*;q=0.8",
               "Accept-Language": "en-US,en;q=0.9"}

def _ws_clean_query(q):
    """'web for: who is the pm of india' -> 'who is the pm of india' (small models often add labels to the query)."""
    q = " ".join(str(q or "").split())
    for _ in range(2):
        q = re.sub(r"^(?:please\s+)?(?:web(?:\s*search)?(?:\s+for)?|search(?:\s+(?:the\s+)?(?:web|internet|online))?(?:\s+for)?|google|look\s*up|query)\s*[:\-–]\s*", "", q, flags=re.I)
        q = re.sub(r"^(?:web\s+for|search\s+(?:the\s+)?(?:web|internet|online)\s+for|search\s+for|look\s+up)\s+", "", q, flags=re.I)
    return q.strip(" \"'“”")[:200]

def _ws_text(s):
    s = re.sub(r"<[^>]+>", "", s or "")
    return re.sub(r"\s+", " ", html.unescape(s)).strip()

def _ws_unwrap(href):
    """Turn search-engine redirect links into the real page address."""
    href = html.unescape(href or "").strip()
    if href.startswith("//"):
        href = "https:" + href
    try:
        if "duckduckgo.com/l/" in href:
            mm = re.search(r"[?&]uddg=([^&]+)", href)
            if mm:
                return unquote_plus(mm.group(1))
        if "bing.com/ck/a" in href:
            mm = re.search(r"[?&]u=a1([^&]+)", href)
            if mm:
                import base64 as _b64
                b = mm.group(1)
                b += "=" * (-len(b) % 4)
                return _b64.urlsafe_b64decode(b.encode()).decode("utf-8", "replace")
    except Exception:
        pass
    return href

def _ws_add(results, seen, url, title, snippet, num):
    if len(results) >= num or not url.startswith(("http://", "https://")) or not title:
        return
    low = url.lower()
    if "duckduckgo.com/y.js" in low or "bing.com/aclick" in low or "doubleclick.net" in low:
        return                                           # adverts
    key = re.sub(r"^https?://(?:www\.)?", "", low).rstrip("/")
    if key in seen:
        return
    seen.add(key)
    results.append({"url": url, "title": title[:160], "snippet": (snippet or "")[:300]})

def _ws_parse_ddg(page, num):
    res, seen = [], set()
    anchors = list(re.finditer(r"<a\b([^>]*\bresult__a\b[^>]*)>(.*?)</a>", page or "", re.S | re.I))
    for i, m in enumerate(anchors):
        hm = re.search(r"""href\s*=\s*["']([^"']+)["']""", m.group(1))
        if not hm:
            continue
        end = anchors[i + 1].start() if i + 1 < len(anchors) else len(page)
        sm = re.search(r"""result__snippet[^>]*>(.*?)</(?:a|td|div)>""", page[m.end():end], re.S | re.I)
        _ws_add(res, seen, _ws_unwrap(hm.group(1)), _ws_text(m.group(2)), _ws_text(sm.group(1)) if sm else "", num)
    return res

def _ws_parse_ddg_lite(page, num):
    res, seen = [], set()
    anchors = list(re.finditer(r"<a\b([^>]*\bresult-link\b[^>]*)>(.*?)</a>", page or "", re.S | re.I))
    for i, m in enumerate(anchors):
        hm = re.search(r"""href\s*=\s*["']([^"']+)["']""", m.group(1))
        if not hm:
            continue
        end = anchors[i + 1].start() if i + 1 < len(anchors) else len(page)
        sm = re.search(r"""result-snippet[^>]*>(.*?)</td>""", page[m.end():end], re.S | re.I)
        _ws_add(res, seen, _ws_unwrap(hm.group(1)), _ws_text(m.group(2)), _ws_text(sm.group(1)) if sm else "", num)
    return res

def _ws_parse_bing(page, num):
    res, seen = [], set()
    for blk in re.split(r"""<li[^>]*class=["'][^"']*\bb_algo\b""", page or "")[1:]:
        hm = re.search(r"""<h2[^>]*>\s*<a\b[^>]*href\s*=\s*["']([^"']+)["'][^>]*>(.*?)</a>""", blk, re.S | re.I)
        if not hm:
            continue
        sm = re.search(r"<p\b[^>]*>(.*?)</p>", blk, re.S | re.I)
        _ws_add(res, seen, _ws_unwrap(hm.group(1)), _ws_text(hm.group(2)), _ws_text(sm.group(1)) if sm else "", num)
    return res

def _ws_wikipedia(query, num):
    res, seen = [], set()
    try:
        r = requests.get("https://en.wikipedia.org/w/api.php", timeout=8, headers=_WS_HEADERS,
                         params={"action": "query", "list": "search", "srsearch": query, "format": "json", "srlimit": num, "utf8": 1})
        for it in (r.json().get("query", {}).get("search", []) or []):
            t = it.get("title", "")
            _ws_add(res, seen, "https://en.wikipedia.org/wiki/" + quote_plus(t.replace(" ", "_"), safe="_()"), t + " - Wikipedia", _ws_text(it.get("snippet", "")), num)
    except Exception:
        pass
    return res

def _local_ai_web_search(query, num=5):
    """Web search without any API key. Tries several search pages in turn (one of them is almost always reachable)
    and returns [{url, title, snippet}]."""
    if not requests:
        return []
    query = _ws_clean_query(query)
    if not query:
        return []
    results = []
    merged = set()

    def take(found):
        for x in found:
            k = re.sub(r"^https?://(?:www\.)?", "", x["url"].lower()).rstrip("/")
            if k not in merged and len(results) < num:
                merged.add(k); results.append(x)

    tries = (
        lambda: _ws_parse_ddg(requests.post("https://html.duckduckgo.com/html/", data={"q": query}, headers=_WS_HEADERS, timeout=9).text, num),
        lambda: _ws_parse_bing(requests.get("https://www.bing.com/search", params={"q": query, "setlang": "en", "count": num + 3}, headers=_WS_HEADERS, timeout=9).text, num),
        lambda: _ws_parse_ddg(requests.get("https://html.duckduckgo.com/html/", params={"q": query}, headers=_WS_HEADERS, timeout=9).text, num),
        lambda: _ws_parse_ddg_lite(requests.post("https://lite.duckduckgo.com/lite/", data={"q": query}, headers=_WS_HEADERS, timeout=9).text, num),
    )
    for fn in tries:
        if len(results) >= num:
            break
        try:
            take(fn())
        except Exception:
            continue
        if len(results) >= 3:
            break
    if not results:
        take(_ws_wikipedia(query, num))
    return results

def _local_ai_fetch_url(url, max_chars=4000):
    """Fetch and clean a web page (public http/https only)."""
    if not requests:
        return "requests not installed."
    if not _local_ai_url_is_public(url):
        return "Blocked: only public http/https pages can be read (not this PC or your local network)."
    try:
        r = requests.get(url, timeout=12, headers={"User-Agent": "Mozilla/5.0"})
        text = re.sub(r'<script[^>]*>.*?</script>', '', r.text, flags=re.DOTALL)
        text = re.sub(r'<style[^>]*>.*?</style>', '', text, flags=re.DOTALL)
        text = re.sub(r'<[^>]+>', ' ', text)
        text = re.sub(r'\s+', ' ', html.unescape(text)).strip()
        return text[:max_chars]
    except Exception as e:
        return f"Fetch error: {e}"

def _local_ai_run_python(code, timeout=20):
    raise PermissionError("Running code is permanently disabled for the AI.")
    """Run Python in a throw-away folder with a scrubbed environment (the user confirmed the code first)."""
    sandbox = tempfile.mkdtemp(dir=LOCAL_AI_SANDBOX_DIR)
    fpath = os.path.join(sandbox, "run.py")
    try:
        with open(fpath, "w", encoding="utf-8") as f:
            f.write(code)
        env = {k: v for k, v in os.environ.items()
               if k.upper() in ("PATH", "SYSTEMROOT", "WINDIR", "TEMP", "TMP", "COMSPEC", "PATHEXT")}
        kw = {}
        if platform.system() == "Windows":
            kw["creationflags"] = 0x08000000   # CREATE_NO_WINDOW
        py = sys.executable if not getattr(sys, "frozen", False) else (shutil.which("python") or sys.executable)
        result = subprocess.run([py, "-I", fpath], capture_output=True, text=True,
                                timeout=timeout, cwd=sandbox, env=env, **kw)
        out = (result.stdout or "") + (result.stderr or "")
        return out[:3000] or "(no output)"
    except subprocess.TimeoutExpired:
        return "⏱️ Timed out (20s limit)"
    except Exception as e:
        return f"Error: {e}"
    finally:
        shutil.rmtree(sandbox, ignore_errors=True)

def _local_ai_image_gen(prompt):
    """Image via Pollinations (free, no key). Returns a URL — only used after the user allows internet."""
    safe = quote_plus(prompt[:200])
    return f"https://image.pollinations.ai/prompt/{safe}?width=512&height=512&nologo=true"

def _local_ai_save_artifact(filename, content):
    """Save an AI-written file in the sandbox folder (file name is sanitised — no path tricks)."""
    name = re.sub(r"[^A-Za-z0-9._ -]", "_", os.path.basename(str(filename).replace("\\", "/"))).strip(" .") or "output.txt"
    path = os.path.join(LOCAL_AI_SANDBOX_DIR, name)
    with open(path, "w", encoding="utf-8") as f:
        f.write(content)
    return path

# ── model loading / chat-template safety ─────────────────────────
_LLM_CACHE = {"key": None, "llm": None}
_LLM_LOCK = threading.Lock()

# ggml tensor type -> (elements per block, bytes per block)   (used only to check the file is complete)
_GGUF_BLOCKS = {0: (1, 4), 1: (1, 2), 2: (32, 18), 3: (32, 20), 6: (32, 22), 7: (32, 24), 8: (32, 34),
                10: (256, 84), 11: (256, 110), 12: (256, 144), 13: (256, 176), 14: (256, 210),
                15: (256, 292), 30: (1, 2), 24: (1, 1), 25: (1, 2), 26: (1, 4), 27: (1, 8), 28: (1, 8)}

def _gguf_inspect(path):
    """Read a .gguf header WITHOUT loading it.  Returns a dict:
       ok (bool), problem (str), arch, pre (tokenizer pre-type), size, expected.
       Lets us tell 'file is incomplete' apart from 'AI engine too old for this model'."""
    import struct
    info = {"ok": False, "problem": "", "arch": "", "pre": "", "size": 0, "expected": 0}
    try:
        info["size"] = os.path.getsize(path)
    except Exception as e:
        info["problem"] = f"cannot read the file ({e})"; return info
    fixed = {0: 1, 1: 1, 2: 2, 3: 2, 4: 4, 5: 4, 6: 4, 7: 1, 10: 8, 11: 8, 12: 8}
    try:
        with open(path, "rb", buffering=1024 * 1024) as f:
            if f.read(4) != b"GGUF":
                info["problem"] = "this is not a valid .gguf file (wrong header) — it was probably damaged while copying or downloading"
                return info
            ver, n_tensors, n_kv = struct.unpack("<IQQ", f.read(20))
            def rd_str():
                n = struct.unpack("<Q", f.read(8))[0]
                if n > 1 << 24: raise ValueError("bad string length")
                return f.read(n)
            def rd_val(t):
                if t in fixed:
                    raw = f.read(fixed[t])
                    if len(raw) != fixed[t]: raise EOFError
                    return struct.unpack("<" + {0: "B", 1: "b", 2: "H", 3: "h", 4: "I", 5: "i", 6: "f", 7: "?", 10: "Q", 11: "q", 12: "d"}[t], raw)[0]
                if t == 8:
                    return rd_str().decode("utf-8", "replace")
                if t == 9:
                    et, n = struct.unpack("<IQ", f.read(12))
                    if et in fixed:
                        f.seek(fixed[et] * n, 1)
                    else:
                        for _ in range(n): rd_val(et)
                    return None
                raise ValueError(f"unknown value type {t}")
            align = 32
            for _ in range(n_kv):
                key = rd_str().decode("utf-8", "replace")
                t = struct.unpack("<I", f.read(4))[0]
                v = rd_val(t)
                if key == "general.architecture": info["arch"] = str(v)
                elif key == "tokenizer.ggml.pre": info["pre"] = str(v)
                elif key == "general.alignment": align = int(v) or 32
            last_off, last_bytes = 0, 0
            for _ in range(n_tensors):
                rd_str()
                nd = struct.unpack("<I", f.read(4))[0]
                dims = struct.unpack("<" + "Q" * nd, f.read(8 * nd))
                tt, off = struct.unpack("<IQ", f.read(12))
                if off >= last_off:
                    last_off = off
                    blk = _GGUF_BLOCKS.get(tt)
                    nel = 1
                    for d in dims: nel *= d
                    last_bytes = (nel // blk[0]) * blk[1] if blk else 0
            pos = f.tell()
            data_start = (pos + align - 1) // align * align
            info["expected"] = data_start + last_off + last_bytes
    except (EOFError, struct.error):
        info["problem"] = "the file ends in the middle of its header — it is incomplete (the copy was cut short)"
        return info
    except Exception as e:
        info["problem"] = f"the header could not be read ({e}) — the file may be damaged"
        return info
    if info["size"] < info["expected"]:
        gb = 1024 ** 3
        info["problem"] = (f"the file is INCOMPLETE: it is {info['size'] / gb:.2f} GB but should be at least "
                           f"{info['expected'] / gb:.2f} GB — copy / download it again")
        return info
    info["ok"] = True
    return info

def _llama_version():
    try:
        import llama_cpp
        return str(getattr(llama_cpp, "__version__", "unknown"))
    except Exception:
        return "not installed"

def _capture_llama_log(model_path, ctx=2048):
    """Load the model once more with llama.cpp's own logging switched on and capture what it says.
    This is the REAL reason a load fails (llama-cpp-python itself only says 'Failed to load model')."""
    import io, contextlib
    from llama_cpp import Llama
    buf = io.StringIO()
    try:
        with contextlib.redirect_stderr(buf), contextlib.redirect_stdout(buf):
            Llama(model_path=model_path, n_ctx=min(int(ctx or 2048), 2048), n_threads=2,
                  use_mmap=False, verbose=True)
    except BaseException as e:
        buf.write(f"\n[python] {type(e).__name__}: {e}\n")
    text = buf.getvalue()
    try:
        os.makedirs(BASE_DATA_DIR, exist_ok=True)
        with open(os.path.join(BASE_DATA_DIR, "ai_load_log.txt"), "w", encoding="utf-8", errors="replace") as f:
            f.write(f"model: {model_path}\nllama-cpp-python: {_llama_version()}\n\n{text}")
    except Exception:
        pass
    return text

def _explain_load_failure(model_path, err, log=""):
    """Turn llama-cpp's vague 'Failed to load model' into the REAL reason + the fix."""
    lines = []
    info = _gguf_inspect(model_path)
    ver = _llama_version()
    if info["problem"]:
        return "Problem: " + info["problem"] + "."
    if ver == "not installed":
        return ("Reason: the AI engine (llama-cpp-python) is not installed.\n"
                "Fix: python -m pip install llama-cpp-python   then restart the browser.")
    low = (log or "").lower()
    pre = info.get("pre", "")
    vt = tuple(int(x) for x in re.findall(r"\d+", ver)[:3]) if re.search(r"\d", ver) else (0,)
    gb = info["size"] / 1024 ** 3
    free = None
    try:
        import psutil
        free = psutil.virtual_memory().available / 1024 ** 3
    except Exception:
        pass
    if "pre-tokenizer" in low or "unknown model architecture" in low or (pre == "deepseek-r1-qwen" and vt < (0, 3, 7)):
        lines.append(f"Reason: your AI engine (llama-cpp-python {ver}) is too OLD for this model. The model file is fine.")
        lines.append("Fix: close the browser and run:\npython -m pip install --upgrade llama-cpp-python==0.3.19 --only-binary=:all: "
                     "--extra-index-url https://abetlen.github.io/llama-cpp-python/whl/cpu")
    elif any(k in low for k in ("failed to allocate", "out of memory", "bad_alloc", "unable to allocate", "cudamalloc")):
        lines.append(f"Reason: NOT ENOUGH FREE MEMORY to load this model ({gb:.2f} GB file).")
        lines.append("Fix: close other programs / browser tabs, or use a smaller model (Q4 instead of Q8).")
    elif any(k in low for k in ("failed to open", "cannot open", "no such file", "permission denied", "access is denied")):
        lines.append("Reason: Windows could not open the model file (permission, antivirus or a cloud-synced folder).")
        lines.append("Fix: move the .gguf into  C:\\SPS_Browser\\local_ai\\models  and try again.")
    elif any(k in low for k in ("out of bounds", "end of file", "unexpected end", "tensor data", "invalid magic")):
        lines.append("Reason: the model file is damaged or cut short. Copy / download it again.")
    else:
        lines.append(f"The model file looks complete ({gb:.2f} GB, architecture '{info['arch']}', tokenizer '{pre}'), "
                     f"but the AI engine (llama-cpp-python {ver}) still could not open it.")
    if free is not None:
        lines.append(f"Free RAM right now: {free:.1f} GB (this model needs about {gb + 0.8:.1f} GB).")
    keys = ("error", "fail", "unknown", "invalid", "unsupported", "cannot", "unable", "assert", "not found", "mismatch", "wrong")
    hits = [l.strip() for l in (log or "").splitlines() if any(k in l.lower() for k in keys)]
    tail = hits[-6:] if hits else [l.strip() for l in (log or "").splitlines() if l.strip()][-6:]
    if tail:
        lines.append("llama.cpp says:\n  " + "\n  ".join(t[:220] for t in tail))
        lines.append(f"(full log saved to {os.path.join(BASE_DATA_DIR, 'ai_load_log.txt')})")
    return "\n".join(lines)

def _get_llm(model_path, ctx):
    """Load the model once and keep it in memory (the old code reloaded it for every message).
    If the first attempt fails, retry with safer settings (no memory-mapping, smaller window)."""
    from llama_cpp import Llama
    key = (model_path, ctx)
    with _LLM_LOCK:
        if _LLM_CACHE["key"] != key:
            _LLM_CACHE["llm"] = None
            _LLM_CACHE["key"] = None
            gc.collect()
            threads = max(1, (os.cpu_count() or 2) - 1)
            safe_ctx = min(ctx, 2048) if ctx else 2048        # ctx 0 would mean "model maximum" = huge
            attempts = [dict(n_ctx=ctx),
                        dict(n_ctx=ctx, use_mmap=False),
                        dict(n_ctx=safe_ctx, use_mmap=False),
                        dict(n_ctx=1024, use_mmap=False, n_batch=128)]
            last = None
            for kw in attempts:
                try:
                    _LLM_CACHE["llm"] = Llama(model_path=model_path, n_threads=threads, verbose=False, **kw)
                    last = None
                    break
                except Exception as e:      # try the next, safer setting
                    last = e
                    gc.collect()
            if last is not None:
                log = ""
                try:
                    log = _capture_llama_log(model_path, ctx)
                except Exception:
                    pass
                raise RuntimeError(_explain_load_failure(model_path, last, log))
            _LLM_CACHE["key"] = key
        return _LLM_CACHE["llm"]

def _split_messages(messages):
    """-> (system_text, conversation) with strictly alternating user/assistant turns starting with 'user'."""
    system, convo = [], []
    for m in messages:
        c = (m.get("content") or "").strip()
        if not c:
            continue
        role = m.get("role")
        if role == "system":
            system.append(c); continue
        role = role if role in ("user", "assistant") else "user"
        if convo and convo[-1]["role"] == role:
            convo[-1]["content"] += "\n\n" + c
        else:
            convo.append({"role": role, "content": c})
    while convo and convo[0]["role"] != "user":
        convo.pop(0)
    if not convo:
        convo = [{"role": "user", "content": "Hello"}]
    return "\n\n".join(system), convo

def _assemble_messages(model_path, system, convo, fold_system=False):
    """Gemma's chat template has NO system role ('System role not supported') — fold the
    system prompt into the first user message for it (and as a retry for any other model)."""
    convo = [dict(m) for m in convo]
    if system and (fold_system or any(k in os.path.basename(model_path).lower() for k in ("gemma", "deepseek", "r1-distill"))):
        convo[0]["content"] = f"{system}\n\n---\n\n{convo[0]['content']}"
        return convo
    return ([{"role": "system", "content": system}] if system else []) + convo

def _trim_to_context(llm, system, convo, ctx, reserve):
    """Drop the oldest turns until the prompt fits the context window."""
    budget = max(256, ctx - reserve - 64)
    def tok(text):
        try:
            return len(llm.tokenize(text.encode("utf-8"), add_bos=False)) + 4
        except Exception:
            return len(text) // 3 + 4
    def total():
        return tok(system) + sum(tok(m["content"]) for m in convo)
    while len(convo) > 1 and total() > budget:
        convo.pop(0)
        while convo and convo[0]["role"] != "user":
            convo.pop(0)
        if not convo:
            break
    if convo and total() > budget:            # one huge message (e.g. attached file): cut it
        keep = max(400, (budget - tok(system)) * 3)
        convo[-1]["content"] = convo[-1]["content"][-keep:]
    return convo or [{"role": "user", "content": "Hello"}]

