import shlex as _shlex
import fnmatch as _fnmatch

AI_WORKSPACE_DIR = os.path.join(LOCAL_AI_SANDBOX_DIR, "workspace")     # where the AI's own files live
AI_TRASH_DIR     = os.path.join(LOCAL_AI_SANDBOX_DIR, "trash")         # "deleted" files go here (recoverable)
AI_BACKUP_DIR    = os.path.join(LOCAL_AI_SANDBOX_DIR, "backups")       # copy of anything the AI overwrites
for _d in (AI_WORKSPACE_DIR, AI_TRASH_DIR, AI_BACKUP_DIR):
    try:
        os.makedirs(_d, exist_ok=True)
    except Exception:
        pass

_AI_CUR = [AI_WORKSPACE_DIR]          # the sandbox folder of the chat that is open right now

def ai_set_chat_dir(chat_id):
    """Every chat gets its own private sandbox folder (like a fresh computer per conversation)."""
    d = os.path.join(AI_WORKSPACE_DIR, re.sub(r"[^A-Za-z0-9_-]", "", str(chat_id)) or "default")
    try:
        os.makedirs(d, exist_ok=True)
    except Exception:
        pass
    _AI_CUR[0] = d
    return d

def ai_chat_dir():
    return _AI_CUR[0]

AI_MAX_WRITE_BYTES = 2 * 1024 * 1024
AI_MAX_READ_BYTES  = 2 * 1024 * 1024


# ── paths ────────────────────────────────────────────────────────
def _ai_real(p):
    """Absolute, symlink-resolved path. Relative names live in the AI workspace."""
    p = os.path.expandvars(os.path.expanduser(str(p).strip().strip('"').strip("'")))
    if not os.path.isabs(p):
        p = os.path.join(_AI_CUR[0], p)
    return os.path.realpath(os.path.abspath(p))

def _ai_under(p, root):
    try:
        a = os.path.normcase(os.path.realpath(p))
        b = os.path.normcase(os.path.realpath(root)).rstrip("\\/")
        return a == b or a.startswith(b + os.sep)
    except Exception:
        return False

def _ai_n(p):
    return p.replace("\\", "/").lower()

_AI_HOME = os.path.realpath(os.path.expanduser("~"))

# places the AI may never read or write (system, secrets, other programs' private data)
_AI_DENY_DIRS = re.compile(
    r"(^|/)(windows|winnt|program files(?: \(x86\))?|programdata|\$recycle\.bin|system volume information|recovery|"
    r"appdata|\.ssh|\.gnupg|\.aws|\.azure|\.kube|\.docker|keychains|\.mozilla|\.thunderbird|\.password-store|"
    r"\.config/(?:google-chrome|chromium|brave|microsoft-edge|mozilla|gcloud|opera)|"
    r"library/(?:keychains|application support|cookies|safari|preferences|launchagents|launchdaemons)|"
    r"start menu/programs/startup|\.config/autostart)(/|$)")
_AI_UNIX_SYS = re.compile(
    r"^/(etc|usr|bin|sbin|boot|sys|proc|dev|lib|lib32|lib64|libx32|root|opt|run|snap|srv|var|system|library|applications|private|volumes)(/|$)")
_AI_SECRET_FILE = re.compile(
    r"(^|/)(id_rsa|id_dsa|id_ecdsa|id_ed25519)[^/]*$|\.(pem|key|pfx|p12|ppk|kdbx|keystore|jks|asc|gpg)$|"
    r"(^|/)(login data|cookies|web data|local state|key[34]\.db|logins\.json|wallet\.dat|\.netrc|\.npmrc|\.pypirc|"
    r"\.git-credentials|ntuser\.dat|sam|security|system|credentials|\.env)$")
_AI_NO_WRITE_EXT = {".exe", ".dll", ".sys", ".msi", ".scr", ".com", ".pif", ".cpl", ".hta", ".lnk", ".reg", ".drv",
                    ".ocx", ".vbe", ".jse", ".msc", ".appx", ".msix", ".app", ".dmg", ".pkg", ".deb", ".rpm", ".so", ".dylib", ".bin"}
_AI_SCRIPT_EXT = {".bat", ".cmd", ".ps1", ".psm1", ".vbs", ".wsf", ".sh", ".bash", ".js", ".py", ".pyw", ".jar", ".command"}
_AI_NO_WRITE_NAMES = re.compile(r"(^|/)\.(bashrc|bash_profile|bash_login|bash_logout|profile|zshrc|zprofile|zshenv|zlogin|inputrc|gitconfig|xinitrc|xprofile)$")

def ai_check_path(path, write=False):
    """Hard policy. Returns dict(ok, path, why, overwrite, script, sandbox)."""
    out = {"ok": False, "path": "", "why": "", "overwrite": False, "script": False, "sandbox": False}
    try:
        if not str(path or "").strip():
            out["why"] = "No path was given."; return out
        real = _ai_real(path)
        out["path"] = real
        n = _ai_n(real)
        if len(real) > 400:
            out["why"] = "That path is too long."; return out
        if n.startswith("//"):
            out["why"] = "Network (UNC) paths are not allowed."; return out
        if _ai_under(real, LOCAL_AI_SANDBOX_DIR) and not (_ai_under(real, _AI_CUR[0]) or _ai_under(real, AI_TRASH_DIR) or _ai_under(real, AI_BACKUP_DIR)):
            out["why"] = "That belongs to another chat's sandbox or to the AI's system folders — each chat only sees its own sandbox."; return out
        if _ai_under(real, _AI_CUR[0]) or _ai_under(real, AI_TRASH_DIR) or _ai_under(real, AI_BACKUP_DIR):
            out["sandbox"] = True
            if write and os.path.splitext(n)[1] in _AI_NO_WRITE_EXT:
                out["why"] = "Program files (.exe, .dll, .msi …) can never be created by the AI."; return out
            out["script"] = os.path.splitext(n)[1] in _AI_SCRIPT_EXT
            out["overwrite"] = bool(write and os.path.exists(real))
            out["ok"] = True
            return out
        if _ai_under(real, APP_DIR):
            if write:
                out["why"] = "The browser's own program folder is protected — the AI cannot change the browser."; return out
        elif _ai_under(real, BASE_DATA_DIR) or _ai_under(real, APP_ROOT_DIR):
            out["why"] = "That is SPS Browser's private data (passwords, cookies, settings) — the AI may not touch it."; return out
        if re.fullmatch(r"[a-z]:/?", n) or n == "/":
            out["why"] = "Whole drives / the root folder are off-limits. Pick a specific folder."; return out
        if _AI_DENY_DIRS.search(n):
            out["why"] = "That is a system or private-data location — the AI may not use it."; return out
        in_home = _ai_under(real, _AI_HOME)
        if not in_home and _AI_UNIX_SYS.search(n):
            out["why"] = "That is a system folder — the AI may not use it."; return out
        if _AI_SECRET_FILE.search(n):
            out["why"] = "That looks like a password / key / secret file — the AI may not open it."; return out
        if write:
            if not in_home:
                out["why"] = "The AI may only create or change files inside your home folder (or its own AI folder)."; return out
            ext = os.path.splitext(n)[1]
            if ext in _AI_NO_WRITE_EXT:
                out["why"] = "Program files (.exe, .dll, .msi …) can never be created by the AI."; return out
            if _AI_NO_WRITE_NAMES.search(n):
                out["why"] = "Shell start-up files cannot be changed by the AI."; return out
            out["script"] = ext in _AI_SCRIPT_EXT
            out["overwrite"] = os.path.exists(real)
        out["ok"] = True
        return out
    except Exception as ex:
        out["why"] = f"Could not check the path ({ex})."
        return out


