def _ai_looks_like_path(tok):
    return bool(tok) and not tok.startswith("-") and (("/" in tok) or ("\\" in tok) or tok.startswith("~") or re.match(r"^[A-Za-z]:", tok))

def ai_command_check(cmd, extra_allowed=()):
    """-> (ok, reason). Only read-only programs on the allow-list, paths checked, no redirection/substitution."""
    cmd = (cmd or "").strip()
    if not cmd:
        return False, "Empty command."
    if len(cmd) > 600:
        return False, "Command is too long."
    c = cmd.replace("2>&1", " ").replace("1>&2", " ")
    for rx, why in _AI_CMD_PATTERNS:
        if rx.search(c):
            return False, why
    allow = set(_AI_CMD_ALLOW) | {a.strip().lower() for a in extra_allowed if a and a.strip()}
    for seg in re.split(r"&&|\|\||[;|&\n\r]", c):
        seg = seg.strip()
        if not seg:
            continue
        try:
            toks = _shlex.split(seg, posix=(platform.system() != "Windows"))
        except Exception:
            toks = seg.split()
        if not toks:
            continue
        first = os.path.basename(toks[0].replace("\\", "/")).lower()
        first = re.sub(r"\.(exe|com|bat|cmd)$", "", first)
        if first in _AI_CMD_NEVER_WHY:
            return False, f"`{first}` is blocked. " + _AI_CMD_NEVER_WHY[first]
        if first not in allow:
            return False, (f"`{first}` is not on the safe-command list. The AI may only run read-only commands "
                           f"(like dir, ls, type, cat, findstr, grep, tree, whoami). "
                           f"Use the file tools to change files and run_python to run code.")
        for t in toks[1:]:
            if _ai_looks_like_path(t):
                chk = ai_check_path(t, write=False)
                if not chk["ok"]:
                    return False, chk["why"]
    return True, ""

def _ai_scrubbed_env(cwd=None):
    env = {k: v for k, v in os.environ.items()
           if k.upper() in ("PATH", "SYSTEMROOT", "WINDIR", "COMSPEC", "PATHEXT", "LANG", "LC_ALL", "HOME", "USERPROFILE", "OS")
           and not re.search(r"KEY|TOKEN|SECRET|PASSW", k, re.I)}
    if cwd:
        env["TEMP"] = env["TMP"] = env["TMPDIR"] = cwd
    env["PYTHONIOENCODING"] = "utf-8"
    env["PYTHONUTF8"] = "1"
    return env

def _ai_kill_tree(proc):
    try:
        if platform.system() == "Windows":
            subprocess.run(["taskkill", "/T", "/F", "/PID", str(proc.pid)], capture_output=True, timeout=5,
                           creationflags=0x08000000)
        else:
            import signal
            try:
                os.killpg(os.getpgid(proc.pid), signal.SIGKILL)
            except Exception:
                proc.kill()
    except Exception:
        try: proc.kill()
        except Exception: pass

def _ai_run_process(argv, cwd, timeout, cancel, env=None, shell=False, cap=60000):
    raise PermissionError("Running programs is permanently disabled for the AI.")
    """Run a process with: no stdin · scrubbed env · time limit · output cap · cancel button · POSIX resource limits.
    Returns (exit_code, output_text, status) where status is 'ok' | 'timeout' | 'cancelled' | 'error'."""
    kw = {}
    if platform.system() == "Windows":
        kw["creationflags"] = 0x08000000
    else:
        def _limits():
            try:
                import resource
                os.setsid()
                resource.setrlimit(resource.RLIMIT_CPU, (int(timeout) + 5, int(timeout) + 5))
                resource.setrlimit(resource.RLIMIT_FSIZE, (64 * 1024 * 1024, 64 * 1024 * 1024))
                resource.setrlimit(resource.RLIMIT_AS, (2 * 1024 ** 3, 2 * 1024 ** 3))
            except Exception:
                pass
        kw["preexec_fn"] = _limits
    try:
        proc = subprocess.Popen(argv, cwd=cwd, env=env or _ai_scrubbed_env(cwd), shell=shell,
                                stdin=subprocess.DEVNULL, stdout=subprocess.PIPE, stderr=subprocess.STDOUT, **kw)
    except Exception as ex:
        return -1, f"Could not start: {ex}", "error"
    buf = []; size = [0]
    def _reader():
        try:
            while True:
                chunk = proc.stdout.read(4096)
                if not chunk:
                    break
                if size[0] < cap:
                    buf.append(chunk); size[0] += len(chunk)
        except Exception:
            pass
    th = threading.Thread(target=_reader, daemon=True); th.start()
    t0 = time.time(); status = "ok"
    while proc.poll() is None:
        if cancel is not None and cancel.is_set():
            _ai_kill_tree(proc); status = "cancelled"; break
        if time.time() - t0 > timeout:
            _ai_kill_tree(proc); status = "timeout"; break
        time.sleep(0.05)
    try: proc.wait(timeout=3)
    except Exception: pass
    th.join(timeout=2)
    out = b"".join(buf).decode("utf-8", "replace")
    if size[0] >= cap:
        out += "\n…(output cut)"
    return (proc.returncode if proc.returncode is not None else -1), out, status


# ── Python sandbox: an audit hook that stops file/OS/network damage even if the code tries ──
_AI_PY_BOOT = r'''
import sys, os, runpy
sys.dont_write_bytecode = True
_DATA = os.path.normcase(os.path.realpath(__DATA__)).rstrip("\\/") + os.sep
_SBROOT = os.path.normcase(os.path.realpath(__SBROOT__)).rstrip("\\/") + os.sep
_SB = os.path.normcase(os.path.realpath(os.getcwd()))
def _under(p):
    try:
        if isinstance(p, bytes): p = os.fsdecode(p)
        a = os.path.normcase(os.path.realpath(p))
        return a == _SB or a.startswith(_SB.rstrip("\\/") + os.sep)
    except Exception:
        return False
def _sysroots():
    r = []
    try:
        import sysconfig
        for k in ("stdlib", "platstdlib", "purelib", "platlib", "data"):
            v = sysconfig.get_paths().get(k)
            if v: r.append(v)
    except Exception:
        pass
    for v in (sys.prefix, sys.base_prefix, sys.exec_prefix, sys.base_exec_prefix, os.path.dirname(os.__file__)):
        if v: r.append(v)
    for v in sys.path:
        if v and os.path.isabs(v): r.append(v)
    if os.name == "nt":
        r.append(os.environ.get("SYSTEMROOT", "C:\\Windows"))
    else:
        r += ["/usr", "/lib", "/lib64", "/etc/localtime", "/etc/timezone", "/etc/ssl", "/proc/self", "/proc/cpuinfo", "/proc/meminfo", "/dev/urandom", "/dev/null", "/dev/random", "/dev/tty", "/sys/devices/system/cpu"]
    return [os.path.normcase(os.path.realpath(x)).rstrip("\\/") for x in r if x]
_READ_OK = _sysroots() + [os.path.normcase(os.path.realpath(x)).rstrip("\\/") for x in __EXTRA__]
def _may_read(p):
    try:
        if isinstance(p, bytes): p = os.fsdecode(p)
        a = os.path.normcase(os.path.realpath(p))
        if a == _SB or a.startswith(_SB.rstrip("\\/") + os.sep):
            return True
        return any(a == r or a.startswith(r + os.sep) for r in _READ_OK)
    except Exception:
        return False
_BLOCK = ("subprocess.", "os.system", "os.exec", "os.posix_spawn", "os.spawn", "os.fork", "os.forkpty", "socket.",
          "ctypes.", "winreg.", "os.kill", "os.killpg", "os.chmod", "os.chown", "os.lchown", "os.symlink", "os.link",
          "os.mkfifo", "os.mknod", "os.setuid", "os.setgid", "os.startfile", "webbrowser.", "pty.", "msvcrt.",
          "os.add_dll_directory", "ftplib.", "smtplib.", "urllib.Request", "http.client.", "shutil.chown", "os.putenv", "os.unsetenv",
          "multiprocessing.", "signal.", "mmap.", "resource.setrlimit")
_PATHS = ("os.remove", "os.rmdir", "os.rename", "os.replace", "os.truncate", "os.mkdir", "os.utime", "os.removexattr",
          "shutil.rmtree", "shutil.move", "shutil.copyfile", "shutil.copytree", "shutil.copymode", "shutil.copystat",
          "os.makedirs", "tempfile.mkstemp", "tempfile.mkdtemp")
def _hook(ev, args):
    if ev.startswith(_BLOCK):
        raise PermissionError("SPS AI sandbox blocked: " + ev + " (the AI may not use programs, the network or system calls)")
    if ev == "open":
        path, mode, flags = args
        if isinstance(path, int):
            return
        w = False
        try:
            if flags is not None and flags & (os.O_WRONLY | os.O_RDWR | os.O_APPEND | os.O_CREAT | os.O_TRUNC):
                w = True
        except Exception:
            pass
        if mode and any(c in str(mode) for c in "wax+"):
            w = True
        if w and not _under(path):
            raise PermissionError("SPS AI sandbox: files can only be written inside the AI folder, not: " + str(path))
        if not w:
            if not _may_read(path):
                raise PermissionError("SPS AI sandbox: code can only read files inside the sandbox folder, not: " + str(path) +
                                      " . To use one of the user's own files, call the read_file or copy_file tool (it asks the user first).")
            n = os.fsdecode(path).replace("\\", "/").lower() if not isinstance(path, str) else path.replace("\\", "/").lower()
            if any(s in n for s in ("/.ssh/", "/.gnupg/", "/.aws/", "id_rsa", "id_ed25519", "/etc/shadow", ".kdbx", "/login data",
                                    "/google/chrome/user data", "/microsoft/edge/user data", "/mozilla/firefox/profiles")):
                raise PermissionError("SPS AI sandbox: that file is private and cannot be read: " + str(path))
    elif ev in ("os.listdir", "os.scandir", "glob.glob"):
        a = args[0] if args else None
        if isinstance(a, (str, bytes, os.PathLike)) and not _may_read(a):
            raise PermissionError("SPS AI sandbox: code can only list folders inside the sandbox, not: " + str(a))
    elif ev.startswith(_PATHS):
        for a in args:
            if isinstance(a, (str, bytes, os.PathLike)) and not _under(a):
                raise PermissionError("SPS AI sandbox: " + ev + " is only allowed inside the AI folder, not: " + str(a))
sys.addaudithook(_hook)
_target = sys.argv[1]
sys.argv = [_target] + sys.argv[2:]
sys.path.insert(0, os.path.dirname(_target))
runpy.run_path(_target, run_name="__main__")
'''

def _ai_python_exe():
    if not getattr(sys, "frozen", False):
        return sys.executable
    return shutil.which("python") or shutil.which("python3") or shutil.which("py")

def ai_run_python_guarded(code=None, file=None, timeout=25, cancel=None, read_roots=()):
    raise PermissionError("Running code is permanently disabled for the AI.")
    """Run Python inside the chat's sandbox folder (audit-hook sandbox: no network/programs, reads and writes confined)."""
    py = _ai_python_exe()
    if not py:
        return False, "Python was not found on this PC, so code can't be run. (Install Python from python.org.)"
    chat_dir = ai_chat_dir()
    os.makedirs(chat_dir, exist_ok=True)
    tmp = os.path.join(chat_dir, ".sps_run_" + _uuid.uuid4().hex[:8])
    os.makedirs(tmp, exist_ok=True)
    boot = os.path.join(tmp, "_boot.py")
    try:
        extra = [os.path.realpath(r) for r in read_roots]
        with open(boot, "w", encoding="utf-8") as f:
            f.write(_AI_PY_BOOT.replace("__DATA__", repr(BASE_DATA_DIR)).replace("__SBROOT__", repr(LOCAL_AI_SANDBOX_DIR))
                    .replace("__EXTRA__", repr(extra)))
        if file:
            target = file
            cwd = os.path.dirname(file)
        else:
            target = os.path.join(tmp, "main.py")
            with open(target, "w", encoding="utf-8") as f:
                f.write(code or "")
            cwd = chat_dir
        code_, out, status = _ai_run_process([py, "-I", boot, target], cwd, timeout, cancel, env=_ai_scrubbed_env(cwd))
        out = out.strip() or "(no output — if you expected output, use print())"
        out = out.replace(tmp + os.sep, "").replace(chat_dir + os.sep, "")
        if status == "timeout":
            return False, f"Timed out after {timeout}s (probably an endless loop).\n{out[-1500:]}"
        if status == "cancelled":
            return False, "Stopped by the user."
        if code_ != 0:
            return False, f"Exited with error code {code_}.\n{out[-2500:]}"
        return True, out[-2500:]
    finally:
        shutil.rmtree(tmp, ignore_errors=True)


# ── internet: public hosts only, and every redirect hop is re-checked ──
def ai_http_get_text(url, timeout=12, max_bytes=1500000):
    if not requests:
        return False, "The 'requests' package is not installed.", ""
    cur = url
    for _hop in range(6):
        if not _local_ai_url_is_public(cur):
            return False, "Blocked: only public http/https pages can be read (not this PC or your local network).", ""
        r = requests.get(cur, timeout=timeout, headers={"User-Agent": "Mozilla/5.0"}, allow_redirects=False, stream=True)
        if r.is_redirect or r.status_code in (301, 302, 303, 307, 308):
            cur = urljoin(cur, r.headers.get("Location", ""))
            continue
        raw = b""
        for chunk in r.iter_content(65536):
            raw += chunk
            if len(raw) > max_bytes:
                break
        ctype = r.headers.get("Content-Type", "")
        if not re.search(r"text|json|xml|html", ctype, re.I) and ctype:
            return False, f"Not a text page ({ctype}).", cur
        txt = raw.decode(r.encoding or "utf-8", "replace")
        return True, txt, cur
    return False, "Too many redirects.", cur

def ai_html_to_text(raw, max_chars=6000):
    t = re.sub(r"(?is)<(script|style|noscript|svg|head)[^>]*>.*?</\1>", " ", raw)
    t = re.sub(r"(?i)<br\s*/?>|</p>|</div>|</li>|</h\d>|</tr>", "\n", t)
    t = re.sub(r"<[^>]+>", " ", t)
    t = html.unescape(t)
    t = re.sub(r"[ \t\r\f\v]+", " ", t)
    t = re.sub(r"\n\s*\n+", "\n\n", t).strip()
    return t[:max_chars]


# ── safe calculator ──────────────────────────────────────────────
import operator as _opmod
_AI_BINOPS = {_ast.Add: _opmod.add, _ast.Sub: _opmod.sub, _ast.Mult: _opmod.mul, _ast.Div: _opmod.truediv,
              _ast.FloorDiv: _opmod.floordiv, _ast.Mod: _opmod.mod, _ast.Pow: _opmod.pow}
_AI_FUNCS = {"sqrt": math.sqrt, "sin": math.sin, "cos": math.cos, "tan": math.tan, "log": math.log, "log10": math.log10,
             "log2": math.log2, "exp": math.exp, "abs": abs, "round": round, "floor": math.floor, "ceil": math.ceil,
             "factorial": math.factorial, "min": min, "max": max}
_AI_CONSTS = {"pi": math.pi, "e": math.e}

def ai_safe_calc(expr):
    expr = (expr or "").strip().replace("^", "**").replace("×", "*").replace("÷", "/").replace(",", "")
    if len(expr) > 200:
        raise ValueError("expression too long")
    def ev(n):
        if isinstance(n, _ast.Expression): return ev(n.body)
        if isinstance(n, _ast.Constant) and isinstance(n.value, (int, float)): return n.value
        if isinstance(n, _ast.BinOp) and type(n.op) in _AI_BINOPS:
            a, b = ev(n.left), ev(n.right)
            if isinstance(n.op, _ast.Pow) and (abs(b) > 1000 or abs(a) > 1e9):
                raise ValueError("number too large")
            return _AI_BINOPS[type(n.op)](a, b)
        if isinstance(n, _ast.UnaryOp) and isinstance(n.op, (_ast.USub, _ast.UAdd)):
            return -ev(n.operand) if isinstance(n.op, _ast.USub) else ev(n.operand)
        if isinstance(n, _ast.Name) and n.id in _AI_CONSTS: return _AI_CONSTS[n.id]
        if isinstance(n, _ast.Call) and isinstance(n.func, _ast.Name) and n.func.id in _AI_FUNCS and not n.keywords:
            args = [ev(a) for a in n.args]
            if n.func.id == "factorial" and args and args[0] > 500: raise ValueError("number too large")
            return _AI_FUNCS[n.func.id](*args)
        raise ValueError("not a plain maths expression")
    v = ev(_ast.parse(expr, mode="eval"))
    if isinstance(v, float):
        v = round(v, 10)
        if v == int(v) and abs(v) < 1e15: v = int(v)
    return v


# ── model output helpers: reasoning blocks and tool calls ────────
def ai_split_think(raw, assume=False):
    """-> (thinking_text, answer_text, still_thinking). Understands <think>…</think> (DeepSeek-R1, Qwen3 …).
    assume=True: the model is a reasoning model whose chat template already opened <think>, so text before </think> is thinking."""
    raw = raw or ""
    m = re.search(r"<think(?:ing)?>", raw, re.I)
    if not m:
        if assume:
            e = re.search(r"</think(?:ing)?>", raw, re.I)
            if e:
                return raw[:e.start()].strip(), raw[e.end():].strip(), False
            return raw.strip(), "", True
        return "", raw, False
    pre, rest = raw[:m.start()], raw[m.end():]
    e = re.search(r"</think(?:ing)?>", rest, re.I)
    if e:
        return rest[:e.start()].strip(), (pre + rest[e.end():]).strip(), False
    return rest.strip(), pre.strip(), True

def _ai_trim_partial_tag(text):
    for tag in ("<think>", "<thinking>", "<tool_call>"):
        for k in range(len(tag) - 1, 0, -1):
            if text.endswith(tag[:k]):
                return text[:-k]
    return text

_AI_TOOL_ALIASES = {
    "search": "web_search", "google": "web_search", "websearch": "web_search", "internet_search": "web_search",
    "read": "read_file", "open_file": "read_file", "cat": "read_file", "readfile": "read_file",
    "write": "write_file", "create_file": "write_file", "save_file": "write_file", "writefile": "write_file", "artifact": "write_file",
    "ls": "list_dir", "list_files": "list_dir", "listdir": "list_dir", "list_directory": "list_dir", "dir": "list_dir",
    "fetch": "fetch_url", "browse": "fetch_url", "open_page": "fetch_url", "get_url": "fetch_url",
    "calculator": "calc", "calculate": "calc", "math": "calc", "date": "now", "time": "now", "datetime": "now",
    "get_page": "read_page", "page": "read_page", "current_page": "read_page", "read_current_page": "read_page",
    "find": "find_files", "search_files": "find_files", "delete": "delete_file", "remove_file": "delete_file",
    "mkdir": "make_dir", "create_folder": "make_dir", "create_directory": "make_dir", "copy": "copy_file", "move": "move_file",
    "rename_file": "move_file", "open": "open_url", "goto": "open_url", "navigate": "open_url",
    "image": "image_gen", "generate_image": "image_gen", "get_clipboard": "clipboard_get", "set_clipboard": "clipboard_set",
    "memory": "remember", "save_memory": "remember", "tabs": "list_tabs", "bookmarks": "list_bookmarks", "history": "search_history",
}
_AI_PRIMARY_ARG = {
    "web_search": "query", "fetch_url": "url", "run_python": "code", "image_gen": "prompt", "read_file": "path", "list_dir": "path",
    "run_command": "command", "open_url": "url", "calc": "expr", "delete_file": "path", "make_dir": "path", "open_path": "path",
    "search_history": "query", "remember": "fact", "get_setting": "name", "open_browser_page": "name", "clipboard_set": "text",
}

def _ai_escape_in_strings(s):
    out = []; in_s = False; esc = False
    for ch in s:
        if in_s:
            if esc: out.append(ch); esc = False
            elif ch == "\\": out.append(ch); esc = True
            elif ch == '"': out.append(ch); in_s = False
            elif ch == "\n": out.append("\\n")
            elif ch == "\r": out.append("\\r")
            elif ch == "\t": out.append("\\t")
            else: out.append(ch)
        else:
            out.append(ch)
            if ch == '"': in_s = True
    if in_s:
        out.append('"')
    return "".join(out)

def _ai_json_loose(s):
    s = (s or "").strip()
    s = re.sub(r"^```(?:json)?\s*|\s*```$", "", s).strip()
    cands = [s]
    t = _ai_escape_in_strings(s); cands.append(t)
    t = re.sub(r",\s*([}\]])", r"\1", t)
    t = t + "}" * max(0, t.count("{") - t.count("}")) + "]" * max(0, t.count("[") - t.count("]"))
    cands.append(t)
    for c in cands:
        try:
            return json.loads(c)
        except Exception:
            pass
    try:
        return _ast.literal_eval(s)
    except Exception:
        return None

def _ai_norm_tool_name(name, known):
    n = re.sub(r"[^a-z0-9_]", "_", str(name or "").strip().lower()).strip("_")
    n = _AI_TOOL_ALIASES.get(n, n)
    return n if n in known else None

def _ai_call_from_obj(obj, known):
    if isinstance(obj, list) and obj:
        obj = obj[0]
    if not isinstance(obj, dict):
        return None
    if "function" in obj and isinstance(obj["function"], dict):
        obj = obj["function"]
    name = obj.get("name") or obj.get("tool") or obj.get("tool_name") or obj.get("function_name") or obj.get("action")
    args = None
    for k in ("arguments", "args", "parameters", "input", "params", "action_input"):
        if k in obj:
            args = obj[k]; break
    if isinstance(args, str):
        j = _ai_json_loose(args)
        args = j if isinstance(j, dict) else None if not args.strip() else {"_": args}
    n = _ai_norm_tool_name(name, known)
    if not n:
        return None
    if args is None:
        args = {k: v for k, v in obj.items() if k not in ("name", "tool", "tool_name", "function_name", "action")}
    if not isinstance(args, dict):
        args = {}
    if "_" in args and n in _AI_PRIMARY_ARG:
        args = {_AI_PRIMARY_ARG[n]: args["_"]}
    return {"name": n, "args": args}

def _ai_legacy_call(name, arg, known):
    n = _ai_norm_tool_name(name, known)
    if not n:
        return None
    arg = (arg or "").strip()
    if n == "write_file":
        m = re.match(r"^([A-Za-z]:[\\/][^:\n]*?|[^:\n]+?):(.*)$", arg, re.S)
        if m:
            return {"name": n, "args": {"path": m.group(1).strip(), "content": m.group(2).lstrip("\n")}}
        return {"name": n, "args": {"path": "output.txt", "content": arg}}
    if n in _AI_PRIMARY_ARG:
        return {"name": n, "args": {_AI_PRIMARY_ARG[n]: arg}}
    return {"name": n, "args": {}}

def _ai_sig_params(name):
    m = re.search(r"\(([^)]*)\)", AI_TOOLS.get(name, {}).get("sig", ""))
    return [p.strip().rstrip("?") for p in (m.group(1).split(",") if m else []) if p.strip()]

def _ai_xml_calls(text, known):
    """Qwen-style  <function=write_file><parameter=path>x</parameter>...</function>"""
    out = []
    for m in re.finditer(r"<function\s*=\s*([\w.\-]+)\s*>(.*?)(?:</function>|\Z)", text or "", re.S | re.I):
        n = _ai_norm_tool_name(m.group(1), known)
        if not n:
            continue
        args = {}
        for pm in re.finditer(r"<parameter\s*=\s*([\w.\-]+)\s*>\n?(.*?)\n?(?:</parameter>|(?=<parameter\s*=)|\Z)", m.group(2), re.S | re.I):
            args[pm.group(1)] = pm.group(2)
        out.append(({"name": n, "args": args}, m.start()))
    return out

def _ai_pycalls(text, known):
    """The model wrote the tool call like Python:  web_search(query="x")  /  write_file("a.html", "...")
    Only accepted when the WHOLE block is nothing but calls to known tools with literal arguments (real programs never match)."""
    import ast as _ast_
    cands = [(m.group(1), m.start()) for m in re.finditer(r"```[ \t]*(?:python|py|tool_code|tool|text)?[ \t]*\n(.*?)(?:```|\Z)", text or "", re.S)]
    if not cands:
        for m in re.finditer(r"(?m)^[ \t]*([A-Za-z_]\w*\(.*\))[ \t]*$", text or ""):
            cands.append((m.group(1), m.start()))
    out = []
    for blk, pos in cands:
        try:
            tree = _ast_.parse(blk.strip("\n"))
        except Exception:
            continue
        calls = []; ok = bool(tree.body)
        for st in tree.body:
            node = st.value if isinstance(st, _ast_.Expr) else None
            if (isinstance(node, _ast_.Call) and isinstance(node.func, _ast_.Name) and node.func.id == "print"
                    and len(node.args) == 1 and isinstance(node.args[0], _ast_.Call)):
                node = node.args[0]
            if not (isinstance(node, _ast_.Call) and isinstance(node.func, _ast_.Name)):
                ok = False; break
            n = _ai_norm_tool_name(node.func.id, known)
            if not n:
                ok = False; break
            try:
                kw = {k.arg: _ast_.literal_eval(k.value) for k in node.keywords if k.arg}
                vals = [_ast_.literal_eval(a) for a in node.args]
            except Exception:
                ok = False; break
            params = _ai_sig_params(n)
            for i, v in enumerate(vals):
                if i < len(params):
                    kw.setdefault(params[i], v)
            calls.append({"name": n, "args": kw})
        if ok and calls:
            out.append((calls, pos))
    return out

def ai_parse_tool_calls(text, known):
    """-> (visible_text, [ {name, args} ]).  Accepts <tool_call>{json}</tool_call>, ```json {…}``` and legacy TOOL:name:arg."""
    text = text or ""
    calls = []; cut = None
    for m in re.finditer(r"<tool_call>(.*?)(?:</tool_call>|\Z)", text, re.S | re.I):
        if cut is None: cut = m.start()
        c = _ai_call_from_obj(_ai_json_loose(m.group(1)), known)
        if c:
            calls.append(c)
        else:
            for xc, _p in _ai_xml_calls(m.group(1), known):
                calls.append(xc)
    if not calls:
        for m in re.finditer(r"```(?:json|tool_call|tool)?\s*(\{.*?\})\s*(?:```|\Z)", text, re.S):
            c = _ai_call_from_obj(_ai_json_loose(m.group(1)), known)
            if c:
                calls.append(c); cut = m.start() if cut is None else cut
    if not calls:
        for m in re.finditer(r"(?m)^\s*(\{\s*\"(?:name|tool)\".*\})\s*$", text):
            c = _ai_call_from_obj(_ai_json_loose(m.group(1)), known)
            if c:
                calls.append(c); cut = m.start() if cut is None else cut
    if not calls:
        for m in re.finditer(r"TOOL:\s*(\w+)\s*:\s*(.+?)(?=\n\s*TOOL:|\Z)", text, re.S):
            c = _ai_legacy_call(m.group(1), m.group(2), known)
            if c:
                calls.append(c); cut = m.start() if cut is None else cut
    if not calls:
        xs = _ai_xml_calls(text, known)
        if xs:
            calls = [c for c, _p in xs]; cut = xs[0][1]
    if not calls:
        for blk_calls, pos in _ai_pycalls(text, known)[:1]:
            calls = blk_calls; cut = pos
    visible = text[:cut] if cut is not None else text
    return visible.strip(), calls

def ai_visible_stream_text(raw):
    """What to show while streaming: no tool-call markup, no half-written tags."""
    t = raw
    for mk in ("<tool_call", "TOOL:", "<function="):
        i = t.find(mk)
        if i >= 0:
            t = t[:i]
    return _ai_trim_partial_tag(t)


# ── instant answers (no model needed → fast, exact, never garbled) ──
_AI_RX_NAME   = re.compile(r"^(?:hi+|hello+|hey+)?[\s,!.]*(?:(?:so|ok|okay|tell me|can you tell me)[\s,]+)?(?:what(?:'s|s| is| are)?|whats)\s+(?:is\s+)?(?:your|ur)\s+name\b", re.I)
_AI_RX_WHO    = re.compile(r"^(?:hi+|hello+|hey+)?[\s,!.]*(?:who\s+are\s+you|who\s+r\s+u|what\s+are\s+you|introduce\s+yourself|tell me about yourself|your\s+name\s*\??$|name\s+please)", re.I)
_AI_RX_MAKER  = re.compile(r"\bwho\s+(?:made|created|built|developed|trained|owns|programmed)\s+(?:you|u)\b|\bwho(?:'s|s| is)\s+your\s+(?:creator|developer|maker|owner)\b", re.I)
_AI_RX_ISAI   = re.compile(r"\bare\s+you\s+(?:chat\s?gpt|gpt|openai|claude|gemini|bard|siri|alexa|copilot|llama|deepseek|a\s+(?:bot|robot|human|real person))\b", re.I)
_AI_RX_MODEL  = re.compile(r"\b(?:which|what)\s+(?:ai\s+)?(?:model|llm|engine|brain)\s+(?:are\s+you|do\s+you\s+(?:use|run)|is\s+this|powers?\s+you)\b|\bwhat\s+are\s+you\s+(?:running|powered)\s+(?:on|by)\b", re.I)
_AI_RX_CAN    = re.compile(r"^(?:hi+|hello+|hey+)?[\s,!.]*(?:what\s+(?:can|do)\s+you\s+(?:do|help\s+(?:me\s+)?with)|what\s+are\s+your\s+(?:features|abilities|skills|powers|capabilities)|how\s+can\s+you\s+help(?:\s+me)?|help\s+me\s+with\s+what|your\s+features)\b", re.I)
_AI_RX_HELLO  = re.compile(r"^(?:hi+|hello+|hey+|hola|namaste|namaskar|yo|sup|good\s+(?:morning|afternoon|evening|night)|hii+|heyy+)[\s!.,😊👋]*$", re.I)
_AI_RX_THANKS = re.compile(r"^(?:thanks?|thank\s+you|thx|ty|thanks\s+a\s+lot|many\s+thanks|great|awesome|nice|cool|perfect|ok\s*thanks?)[\s!.😊👍]*$", re.I)
_AI_RX_TIME   = re.compile(r"\b(?:what(?:'s|s| is)?|tell me|show me|current)\s+(?:the\s+)?(?:current\s+)?(time|date|day)(?:\s+(?:today|now|is it|right now))?\b|\bwhat\s+day\s+is\s+(?:it|today)\b|\bwhat\s+time\s+is\s+it\b|\btoday'?s\s+date\b|\bdate\s+today\b|\bcurrent\s+(?:time|date)\b", re.I)
_AI_RX_MATH   = re.compile(r"^(?:what(?:'s|s| is)\s+|calculate\s+|calc\s+|compute\s+|solve\s+|evaluate\s+)?([-+*/().%^\d\s,×÷x]*[\d)][-+*/%^×÷x][-+*/().%^\d\s,×÷x]*|[a-z0-9_]+\([-+*/().%^\d\s,]*\)|[-+*/().%^\d\s×÷x]*\d\s*(?:\*\*|\^)\s*\d[-+*/().%^\d\s]*)\s*[=?]*\s*$", re.I)

def ai_quick_answer(text, name="", model_label=""):
    """Returns a ready markdown reply, or None when the question needs the real model."""
    t = " ".join((text or "").split())
    if not t or len(t) > 160:
        return None
    low = t.lower().rstrip("?!. ")
    nm = f", {name}" if name else ""
    if _AI_RX_NAME.search(t) or low in ("your name", "name", "ur name", "what's ur name", "whats ur name"):
        return "My name is **SPS AI**."
    if _AI_RX_WHO.search(t):
        return "I'm **SPS AI**, a helpful AI assistant."
    if _AI_RX_MAKER.search(t):
        return "I'm **SPS AI**, a helpful AI assistant. I run on your computer using a local AI model, so your chats stay with you."
    if _AI_RX_ISAI.search(t):
        return "No — I'm **SPS AI**, a helpful AI assistant that runs on your own computer."
    if _AI_RX_MODEL.search(t):
        return (f"I'm **SPS AI**. Right now I'm running on **{model_label}**, a model that lives on your computer."
                if model_label else "I'm **SPS AI**. I run on an AI model that lives on your computer — you can pick the model in the box next to the send button.")
    if _AI_RX_HELLO.match(t):
        return f"Hello{nm}! 👋 How can I help you today?"
    if _AI_RX_THANKS.match(t):
        return "You're welcome! 😊 Anything else I can help with?"
    if _AI_RX_CAN.search(t):
        return (
            "Here's everything I can help you with:\n\n"
            "**💬 Conversation & Knowledge**\n"
            "- Answer any question — science, history, math, coding, general knowledge\n"
            "- Explain complex topics step by step\n"
            "- Translate text between languages\n"
            "- Summarise articles, documents, or pasted text\n"
            "- Write essays, emails, cover letters, stories, poems\n"
            "- Check grammar, spelling, and style\n"
            "- Brainstorm ideas, names, slogans\n\n"
            "**🌐 Web & Research** *(Chat / Agent mode)*\n"
            "- Search the web for current information automatically\n"
            "- Read and summarise any public web page\n"
            "- Find news, prices, scores, people, places\n"
            "- Research a topic and cite sources\n"
            "- Open URLs in new browser tabs\n\n"
            "**🖥️ Your Computer** *(Agent / Special mode)*\n"
            "- Create files: HTML pages, Python scripts, text files, code\n"
            "- Read and edit existing files\n"
            "- List, search, copy, move, delete files\n"
            "- Run Python code and show the output\n"
            "- Run safe system commands\n"
            "- Copy text to your clipboard\n\n"
            "**🌐 Your Browser**\n"
            "- Read the page you have open\n"
            "- List your open tabs\n"
            "- Search your browsing history\n"
            "- Show your bookmarks\n"
            "- Change browser settings by voice/text command\n"
            "- Open Settings, Downloads, Bookmarks, History, Notes\n\n"
            "**🧮 Instant Built-in Tools** *(no model needed)*\n"
            "- Maths: `12 * (8 + 3)`, percentages, unit conversions\n"
            "- Current date and time\n"
            "- Remember facts about you across chats\n\n"
            "**🤖 AI Modes**\n"
            "- **Chat** — fast answers + automatic web search\n"
            "- **Agent** — does real work: writes files, runs code, researches the web\n"
            "- **Think** — shows full step-by-step reasoning before answering\n"
            "- **Special** — thinks first (DeepSeek-R1), then the agent executes the plan\n\n"
            "Just ask — I'll figure out the best approach automatically. 🚀"
        )
    m = _AI_RX_MATH.match(t)
    if m and re.search(r"\d", m.group(1)) and re.search(r"[-+*/%^×÷x]|\(", m.group(1)):
        try:
            expr = re.sub(r"(?<=\d)\s*x\s*(?=\d)", "*", m.group(1))
            v = ai_safe_calc(expr)
            return f"**{m.group(1).strip()} = {v:,}**" if isinstance(v, int) and abs(v) >= 10000 else f"**{m.group(1).strip()} = {v}**"
        except Exception:
            return None
    return None


# ── is this a job on the user's computer (→ agent), or a question about the browser (→ built-in help)? ──
_AI_RX_TASK_VERB = re.compile(r"\b(list|read|open|show|find|search|look|create|make|write|save|delete|remove|move|copy|rename|run|execute|organi[sz]e|sort|clean|summari[sz]e|check|count|tell|analy[sz]e|edit|fix|what(?:'s| is)\s+(?:in|inside)|what\s+files)\b", re.I)
_AI_RX_TASK_OBJ = re.compile(
    r"(\bmy\s+(?:\w+\s+){0,2}(?:files?|folders?|directory|directories|pc|computer|laptop|drive)\b|"
    r"\b(?:downloads|desktop|documents|pictures|music|videos?)\s+(?:folder|directory)\b|"
    r"\b(?:the|this|that|a)\s+(?:\w+\s+){0,2}(?:folder|directory)\b|[A-Za-z]:[\\/]|(?:^|\s)~[\\/]|"
    r"\b[\w\-]+\.(?:txt|md|py|csv|json|docx?|xlsx?|pdf|html?|js|log|bat|sh)\b|\b(?:folder|directory)\b)", re.I)
_AI_RX_BROWSERY = re.compile(r"\b(sps|browser|settings?|bookmarks?|extensions?|password manager|cookies|tabs?|incognito|toolbar|sidebar)\b", re.I)

_AI_RX_FILEREF = re.compile(r"[A-Za-z]:[\\/]|(?:^|\s)~[\\/]|\b[\w\-]+\.(?:txt|md|py|csv|json|docx?|xlsx?|pdf|html?|js|log|bat|sh|ini|cfg|xml|yaml|yml)\b", re.I)

def ai_is_computer_task(text):
    t = text or ""
    if _AI_RX_BROWSERY.search(t):
        return False
    return bool(_AI_RX_FILEREF.search(t) or (_AI_RX_TASK_VERB.search(t) and _AI_RX_TASK_OBJ.search(t)))

_AI_RX_QWORD = re.compile(r"^(?:please\s+|hey\s+|hi\s+)?(?:who|whom|whose|how|where|what|why|which|when|can|could|does|do|is|are|should|tell me how|show me how|i want to|i need to|help me)\b", re.I)

def ai_is_browser_question(text):
    """Should the built-in browser help answer this? Only for questions that are plausibly about the browser —
    otherwise loose word overlap would answer a coding request with the 'Guided tour' page."""
    t = " ".join((text or "").split())
    n = len(t.split())
    if _AI_RX_BROWSERY.search(t):
        return True
    if n <= 4:
        return True
    return n <= 12 and bool(_AI_RX_QWORD.match(t))


# ── modes & models ────────────────────────────────────────────────
AI_MODES = ("chat", "agent", "think", "special")
AI_MODE_INFO = {
    "chat":    ("💬", "Chat",    "Everyday questions. Can search the web and give links. No computer actions."),
    "agent":   ("🤖", "Agent",   "Does real work in a private sandbox: writes & runs code, makes files, researches. Asks before touching your real files."),
    "think":   ("🧠", "Think",   "Deep reasoning. Shows its full thinking, then the answer."),
    "special": ("⚡", "Special", "Thinks first (DeepSeek-R1), then hands the work to the Agent (Qwen-Coder). Tries again until it works."),
}

def ai_model_roles(filename):
    """Which modes a model file is meant for. chat / agent / think."""
    f = (filename or "").lower()
    if "deepseek" in f or "r1-distill" in f:
        return {"think"}
    if "coder" in f:
        return {"agent"}
    if "phi-3" in f or "phi3" in f or "phi-4" in f:
        return {"chat", "agent"}
    if any(k in f for k in ("qwen", "tinyllama", "gemma", "llama", "mistral", "smol")):
        return {"chat"}
    return {"chat", "agent"}                      # unknown models you add yourself: allowed in chat and agent

def ai_model_short(label):
    return re.sub(r"\s*[^\w\s.\-+()]+\s*$", "", label or "").strip() or (label or "")


# ── what does the user's message need? ────────────────────────────
_AI_RX_WEB_STRONG = re.compile(
    r"\b(latest|newest|news|headlines?|price\s+of|how\s+much\s+(?:is|does|are)|cost\s+of|weather|forecast|temperature\s+in|scores?\b|who\s+won|results?\s+of|"
    r"release\s+date|stock\s+price|share\s+price|exchange\s+rate|trending|search\s+(?:for|the\s+web|online|the\s+internet)|look\s+up|google\s+it|"
    r"on\s+the\s+(?:web|internet)|according\s+to\s+the\s+internet|20(?:2[4-9]|3\d)|who\s+is\s+the\s+(?:current|new)|is\s+\w+\s+still\s+(?:open|available|working|alive))\b", re.I)
_AI_RX_WEB_WEAK = re.compile(r"\b(today|tonight|yesterday|tomorrow|right\s+now|now|nowadays|at\s+present|at\s+the\s+moment|at\s+this\s+time|currently|current|this\s+(?:week|month|year)|recent(?:ly)?|online)\b", re.I)
_AI_RX_WEB_OFFICE = re.compile(r"\b(?:prime\s+minister|president|chief\s+minister|home\s+minister|finance\s+minister|ceo|chairman|governor|chancellor|speaker|captain|coach)\s+of\b", re.I)
_AI_RX_WEB_NOT_OFFICE = re.compile(r"\b(?:first|second|third|was|were|former|late|history|born|died|era|term\s+of)\b", re.I)
_AI_RX_LINK_ASK = re.compile(
    r"\b(?:give|send|share|show|provide|need|want|find|get|tell)\b.{0,30}\b(?:links?|urls?|websites?|web\s+sites?|sites?|pages?|sources?)\b|"
    r"\b(?:links?|urls?)\s+(?:to|for|of)\b|\bofficial\s+(?:site|website|page|link)\b|\bwhere\s+(?:can|do|could)\s+i\s+(?:download|buy|watch|read|find|get|stream)\b|"
    r"\bdownload\s+link\b|\bwebsite\s+(?:for|of|to)\b", re.I)
_AI_RX_WORK = re.compile(
    r"\b(?:create|make|build|generate|write|code|develop|design|produce|export|convert|analy[sz]e|calculate|plot|chart|graph|parse|scrape|"
    r"organi[sz]e|rename|sort|clean|merge|split|compress|zip|unzip|automate|script|program|csv|json|excel|spreadsheet|pdf|docx?|html|website|app|"
    r"game|calculator|bot|tool|simulation|dataset|report|presentation|file|folder|run|execute|test|debug|fix|refactor|install)\b", re.I)
_AI_RX_SIMPLE = re.compile(r"^(?:what(?:'s| is| are)|who(?:'s| is| was)|why|define|meaning of|explain|tell me about|how (?:does|do|did))\b", re.I)

_AI_RX_PURE_TIME = re.compile(r"^(?:hey\s+|please\s+)?(?:what(?:'s|s| is)?\s+(?:the\s+)?)?(?:current\s+)?(?:time|date|day)(?:\s+(?:is\s+it(?:\s+now)?|today|now|right\s+now))?$|^what\s+(?:time|day)\s+is\s+it(?:\s+(?:now|today|right\s+now))?$|^(?:today'?s\s+date|date\s+today)$", re.I)

def ai_wants_web(text):
    t = text or ""
    # also trigger on explicit "search for X" even if short
    low = t.lower()
    if re.search(r"\\b(search for|look up|find out|google|what is the latest|current|right now|today['\\s]|breaking|news about|price of|score of|who is the (current|new)|recently|just released|just announced)\\b", low):
        return True
    if ai_is_computer_task(t) or len(t) > 400:
        return False
    if _AI_RX_PURE_TIME.match(" ".join(t.split()).strip(" ?!.")):
        return False                        # the clock is already in the prompt — no web search for "what time is it" 
    if _AI_RX_WEB_OFFICE.search(t) and not _AI_RX_WEB_NOT_OFFICE.search(t):
        return True                         # "who is the prime minister of X" changes over time → look it up
    return bool(_AI_RX_WEB_STRONG.search(t)) or bool(_AI_RX_WEB_WEAK.search(t) and _AI_RX_QWORD.match(t.strip()))

_AI_RX_WEB_AGENT = re.compile(r"\b(research|search|google|look\s*up|browse|surf|web|internet|online|news|latest|trending|price|prices|reviews?)\b", re.I)

def ai_wants_web_agent(text):
    """Agent / Special mode: the user mentions research / searching -> the browser itself does the web search first."""
    t = text or ""
    return ai_wants_web(t) or bool(_AI_RX_WEB_AGENT.search(t))

def ai_wants_links(text):
    return bool(_AI_RX_LINK_ASK.search(text or ""))

def ai_needs_work(text):
    """Heuristic: does this request need tools (code, files, research) rather than just a spoken answer?"""
    t = text or ""
    if ai_is_computer_task(t):
        return True
    if _AI_RX_WORK.search(t) and not _AI_RX_SIMPLE.match(t.strip()):
        return True
    return ai_wants_web(t)

_AI_RX_QFILLER = re.compile(r"^(?:please\s+|can\s+you\s+|could\s+you\s+|would\s+you\s+|hey\s+|hi\s+|ok\s+|okay\s+)*(?:give|send|share|show|provide|find|get|tell|search(?:\s+for)?|look\s+up|google)\s+(?:me\s+)?(?:the\s+|a\s+|some\s+)?", re.I)

def ai_search_query(text):
    q = " ".join((text or "").split())
    q = _AI_RX_QFILLER.sub("", q)
    q = re.sub(r"\b(?:links?|urls?)\s+(?:to|for|of)\s+", "", q, flags=re.I)
    q = re.sub(r"\b(?:please|thanks|thank you)\b[.!?\s]*$", "", q, flags=re.I)
    return q.strip(" ?.!,")[:140] or (text or "")[:140]


# ── "Is this question about SPS Browser itself?"  Only then is the guide file (SPS_BROWSER_GUIDE.md) used. ──
_AI_RX_SPS_NAME = re.compile(r"\bsps\b(?!\s*ai\b)|\bspsbrowser\b|\b(?:this|our|my|your)\s+(?:web\s+)?browser\b", re.I)
_AI_RX_OTHER_BROWSER = re.compile(r"\b(?:chrome|chromium|firefox|mozilla|edge|safari|opera|brave|vivaldi|tor\s+browser|internet\s+explorer)\b", re.I)

def ai_mentions_other_browser(text):
    t = text or ""
    return bool(_AI_RX_OTHER_BROWSER.search(t)) and not re.search(r"\bsps\b", t, re.I)

def ai_is_sps_question(text):
    t = text or ""
    if ai_mentions_other_browser(t):
        return False
    return bool(_AI_RX_SPS_NAME.search(t))

_SPS_GUIDE_CACHE = {"path": "", "mtime": 0, "secs": []}

def sps_guide_path():
    for d in (APP_DIR, os.path.dirname(os.path.abspath(__file__))):
        p = os.path.join(d, "SPS_BROWSER_GUIDE.md")
        if os.path.isfile(p):
            return p
    return ""

def _sps_guide_sections():
    """Reads SPS_BROWSER_GUIDE.md (re-read automatically when you edit it). -> [{title, text, tt, bt, kt}]"""
    p = sps_guide_path()
    if not p:
        return []
    try:
        mt = os.path.getmtime(p)
    except Exception:
        return []
    c = _SPS_GUIDE_CACHE
    if c["path"] == p and c["mtime"] == mt:
        return c["secs"]
    try:
        with open(p, encoding="utf-8", errors="replace") as f:
            raw = f.read()
    except Exception:
        return []
    raw = re.sub(r"<!--.*?-->", "", raw, flags=re.S)
    raw = raw.replace("{DATA}", BASE_DATA_DIR).replace("{MODELS}", SHARED_MODELS_DIR)
    secs = []; head = "SPS Browser overview"; body = []

    def flush():
        txt = "\n".join(body).strip()
        if txt:
            kw = ""
            km = re.search(r"(?mi)^keywords:\s*(.+)$", txt)
            if km:
                kw = km.group(1)
                txt = re.sub(r"(?mi)^keywords:.*\n?", "", txt).strip()
            secs.append({"title": head, "text": txt, "tt": set(_kb_tokens(head)), "kt": set(_kb_tokens(kw)),
                         "bt": {}})
            for t in _kb_tokens(txt):
                secs[-1]["bt"][t] = secs[-1]["bt"].get(t, 0) + 1

    for ln in raw.splitlines():
        m = re.match(r"^(#{1,3})\s+(.*)$", ln)
        if m and len(m.group(1)) >= 2:
            flush(); head = m.group(2).strip(); body = []
        elif m:
            continue
        else:
            body.append(ln)
    flush()
    c["path"], c["mtime"], c["secs"] = p, mt, secs
    return secs

def sps_guide_context(query, settings=None, limit=2600):
    """The parts of SPS_BROWSER_GUIDE.md that answer this question (+ the live ON/OFF state of a matching setting)."""
    secs = _sps_guide_sections()
    if not secs:
        return ""
    q = _kb_prepare_query(query)
    qt = [t for t in _kb_tokens(q)]
    if not qt:
        return ""
    n = float(len(secs)); df = {}
    for s in secs:
        for t in set(s["tt"]) | set(s["kt"]) | set(s["bt"]):
            df[t] = df.get(t, 0) + 1
    ql = " " + q.lower() + " "
    scored = []
    for s in secs:
        sc = 0.0
        for t in set(qt):
            idf = math.log(1 + n / max(1, df.get(t, 1)))
            if t in s["tt"]: sc += 3.0 * idf
            if t in s["kt"]: sc += 2.0 * idf
            if t in s["bt"]: sc += min(s["bt"][t], 3) * 0.5 * idf
        if (" " + s["title"].lower() + " ") in ql:
            sc += 6
        if sc > 0:
            scored.append((sc, s))
    if not scored:
        return ""
    scored.sort(key=lambda x: -x[0])
    top = scored[0][0]
    keep = [s for sc, s in scored[:4] if sc >= 0.55 * top][:3]
    parts = []
    for s in keep:
        t = s["text"]
        parts.append(f"### {s['title']}\n{t[:1100] + ('…' if len(t) > 1100 else '')}")
    ctx = "\n\n".join(parts)
    try:
        for sc, e in kb_search(query, 3):
            if e["kind"] == "setting" and sc >= 8 and settings is not None:
                st = _fmt_state(settings, e["key"])
                if st:
                    ctx += f"\n\nLive state: **{e['title']}** is {st} right now."
                break
    except Exception:
        pass
    return ctx[:limit]

# ── does the request ask for a file / program / page that must be CREATED? ──
_AI_RX_MAKE_VERB = re.compile(r"\b(?:make|create|build|write|generate|code|develop|design|produce|program|prepare|give\s+me|i\s+(?:want|need))\b", re.I)
_AI_RX_MAKE_THING = re.compile(
    r"\b(?:calculator|calc|app|application|game|website|web\s?site|web\s?page|webpage|page|landing\s+page|portfolio|script|program|tool|html|css|javascript|python|"
    r"file|todo|to-do|clock|timer|stopwatch|quiz|form|dashboard|chat\s?bot|snake|tic[- ]?tac[- ]?toe|converter|generator|tracker|planner|login|widget|animation|simulator|simulation)\b", re.I)

def ai_wants_file(text):
    t = (text or "").strip()
    if not t or _AI_RX_SIMPLE.match(t):
        return False
    return bool(_AI_RX_MAKE_VERB.search(t) and _AI_RX_MAKE_THING.search(t))

def ai_extract_code_blocks(text):
    """-> [(language, code)] for every ``` fenced block (an unfinished last block counts too)."""
    out = []
    for m in re.finditer(r"```[ \t]*([\w+#.\-]*)[^\n]*\n(.*?)(?:```|\Z)", text or "", re.S):
        code = m.group(2).rstrip()
        if len(code.strip()) >= 20:
            out.append((m.group(1).lower(), code))
    return out

_AI_LANG_EXT = {"python": "py", "py": "py", "python3": "py", "javascript": "js", "js": "js", "node": "js", "json": "json", "bash": "sh", "sh": "sh",
                "shell": "sh", "sql": "sql", "java": "java", "c": "c", "cpp": "cpp", "c++": "cpp", "csharp": "cs", "cs": "cs", "css": "css",
                "markdown": "md", "md": "md", "csv": "csv", "xml": "xml", "yaml": "yml", "yml": "yml", "bat": "bat", "text": "txt", "txt": "txt",
                "php": "php", "go": "go", "rust": "rs", "ts": "ts", "typescript": "ts"}

def ai_pick_code_file(blocks):
    """-> (extension, code). Separate html + css + js blocks are joined into ONE working page."""
    if not blocks:
        return None
    pages = [c for l, c in blocks if l in ("html", "htm") or re.search(r"<!doctype html|<html\b", c, re.I)]
    if pages:
        page = max(pages, key=len)
        css = [c for l, c in blocks if l == "css"]
        js = [c for l, c in blocks if l in ("js", "javascript")]
        if css and not re.search(r"<style", page, re.I):
            tag = "<style>\n" + "\n".join(css) + "\n</style>"
            page = re.sub(r"</head>", lambda m: tag + "\n</head>", page, count=1, flags=re.I) if re.search(r"</head>", page, re.I) else tag + "\n" + page
        if js and not re.search(r"<script(?![^>]*\bsrc=)", page, re.I):
            tag = "<script>\n" + "\n".join(js) + "\n</script>"
            page = re.sub(r"</body>", lambda m: tag + "\n</body>", page, count=1, flags=re.I) if re.search(r"</body>", page, re.I) else page + "\n" + tag
        return "html", page
    lang, code = max(blocks, key=lambda b: len(b[1]))
    ext = _AI_LANG_EXT.get(lang)
    if not ext:
        ext = "py" if re.search(r"(?m)^\s*(?:import \w+|from \w+ import|def \w+\(|print\()", code) else "txt"
    return ext, code

_AI_FILE_NAMES = [(r"calculator|\bcalc\b", "calculator"), (r"to-?do|task\s+list", "todo_list"), (r"tic[- ]?tac[- ]?toe", "tic_tac_toe"),
                  (r"snake", "snake_game"), (r"game", "game"), (r"stopwatch", "stopwatch"), (r"clock", "clock"), (r"timer", "timer"),
                  (r"quiz", "quiz"), (r"portfolio", "portfolio"), (r"landing", "landing_page"), (r"dashboard", "dashboard"),
                  (r"converter", "converter"), (r"login", "login_page"), (r"website|web\s?site|web\s?page|webpage|page", "website"),
                  (r"chat\s?bot", "chatbot"), (r"tracker", "tracker"), (r"planner", "planner"), (r"generator", "generator")]

def ai_guess_filename(user_text, ext):
    m = re.search(r"\b([\w\-]+\.(?:html?|py|js|css|json|txt|md|csv|java|c|cpp|sh|bat|sql|php|go|ts))\b", user_text or "", re.I)
    if m:
        return m.group(1)
    low = (user_text or "").lower()
    for rx, name in _AI_FILE_NAMES:
        if re.search(rx, low):
            return f"{name}.{ext}"
    return f"program.{ext}" if ext in ("py", "js", "java", "c", "cpp", "sh", "bat") else f"output.{ext}"



