#  SPS AI V33 — Part B: chats · settings · memory · activity log · dialogs
# ═══════════════════════════════════════════════════════════════
AI_DEFAULT_SETTINGS = {
    "mode": "chat",           # chat · agent · think · special
    "sandbox_auto": True,     # Agent/Special may work inside their private sandbox without asking each time
    "auto_web": True,         # search the web by itself when a question needs fresh information (asks once per session)
    "models": {},             # your model choice per mode slot
    "agent": True,            # (kept for older settings files)
    "os_level": 2,            # 0 = chat only · 1 = read-only computer access · 2 = full, with permission for each change
    "max_steps": 15,          # most tool steps for ONE request
    "max_retries": 5,         # how many failed attempts in a row before it stops and asks you
    "temperature": 0.3,
    "max_tokens": 1024,
    "think": False,           # step-by-step reasoning (shown in a collapsible box)
    "save_history": True,
    "custom": "",             # your own instructions for the AI
    "extra_cmds": "",         # extra harmless programs you allow (never overrides the hard blocks)
    "ctx": 0,                 # 0 = automatic
    "wide": False,
}

def ai_load_settings(base):
    s = {k: (dict(v) if isinstance(v, dict) else v) for k, v in AI_DEFAULT_SETTINGS.items()}
    try:
        with open(os.path.join(base, "ai_settings.json"), encoding="utf-8") as f:
            d = json.load(f)
        for k, v in d.items():
            if k in s and type(v) == type(s[k]):
                s[k] = v
            elif k in s and isinstance(s[k], float) and isinstance(v, int):
                s[k] = float(v)
    except Exception:
        pass
    return s

def ai_save_settings(base, s):
    try:
        with open(os.path.join(base, "ai_settings.json"), "w", encoding="utf-8") as f:
            json.dump(s, f, indent=2)
    except Exception:
        pass

# ── memory (facts the user asked the AI to remember) ──
def ai_memory_load(base):
    try:
        with open(os.path.join(base, "ai_memory.json"), encoding="utf-8") as f:
            d = json.load(f)
        return [str(x)[:240] for x in d if isinstance(x, str)][:60]
    except Exception:
        return []

def ai_memory_save(base, items):
    try:
        with open(os.path.join(base, "ai_memory.json"), "w", encoding="utf-8") as f:
            json.dump(items[:60], f, indent=1, ensure_ascii=False)
    except Exception:
        pass

# ── activity log: every action the AI asked for, and what you decided ──
def ai_audit(base, tool, summary, decision, status=""):
    try:
        p = os.path.join(base, "ai_activity.log")
        if os.path.exists(p) and os.path.getsize(p) > 1_000_000:
            with open(p, "rb") as f:
                f.seek(-300_000, 2); keep = f.read()
            with open(p, "wb") as f:
                f.write(keep)
        line = f"{datetime.datetime.now().strftime('%Y-%m-%d %H:%M:%S')} | {tool:<16} | {decision:<10} | {status:<8} | {str(summary).replace(chr(10), ' ')[:220]}\n"
        with open(p, "a", encoding="utf-8") as f:
            f.write(line)
    except Exception:
        pass

# ── chat history on disk (one small JSON file per chat, inside your profile) ──
class AIStore:
    def __init__(self, base):
        self.dir = os.path.join(base, "ai_chats")
        try:
            os.makedirs(self.dir, exist_ok=True)
        except Exception:
            pass

    def _p(self, cid):
        return os.path.join(self.dir, re.sub(r"[^A-Za-z0-9_-]", "", str(cid)) + ".json")

    def save(self, chat):
        try:
            p = self._p(chat["id"]); tmp = p + ".tmp"
            with open(tmp, "w", encoding="utf-8") as f:
                json.dump(chat, f, ensure_ascii=False)
            os.replace(tmp, p)
            return True
        except Exception:
            return False

    def load(self, cid):
        try:
            with open(self._p(cid), encoding="utf-8") as f:
                d = json.load(f)
            if isinstance(d, dict) and isinstance(d.get("items"), list) and isinstance(d.get("history"), list):
                return d
        except Exception:
            pass
        return None

    def delete(self, cid):
        try:
            os.remove(self._p(cid)); return True
        except Exception:
            return False

    def delete_all(self):
        n = 0
        try:
            for fn in os.listdir(self.dir):
                if fn.endswith(".json"):
                    try: os.remove(os.path.join(self.dir, fn)); n += 1
                    except Exception: pass
        except Exception:
            pass
        return n

    def list(self, query=""):
        q = (query or "").strip().lower()
        res = []
        try:
            names = [fn for fn in os.listdir(self.dir) if fn.endswith(".json")]
        except Exception:
            names = []
        for fn in names:
            d = self.load(fn[:-5])
            if not d:
                continue
            first = next((i.get("text", "") for i in d["items"] if i.get("type") == "user"), "")
            if q:
                blob = (d.get("title", "") + " " + " ".join(str(i.get("text", "")) for i in d["items"] if i.get("type") in ("user", "ai"))).lower()
                if q not in blob:
                    continue
            res.append({"id": d.get("id", fn[:-5]), "title": d.get("title") or "New chat", "updated": d.get("updated", 0),
                        "pinned": bool(d.get("pinned")), "count": sum(1 for i in d["items"] if i.get("type") in ("user", "ai")),
                        "snippet": first[:90]})
        res.sort(key=lambda m: (not m["pinned"], -float(m["updated"] or 0)))
        return res


# ── dialogs ───────────────────────────────────────────────────────
def _ai_qss(t):
    return (f"QDialog{{background:{t['bg_primary']};}}QLabel{{color:{t['text_primary']};background:transparent;}}"
            f"QCheckBox{{color:{t['text_primary']};}}QGroupBox{{color:{t['text_primary']};}}"
            f"QPlainTextEdit,QTextEdit,QLineEdit,QSpinBox,QDoubleSpinBox,QComboBox{{background:{t['bg_secondary']};color:{t['text_primary']};"
            f"border:1px solid {t['border']};border-radius:8px;padding:5px 8px;}}"
            f"QComboBox QAbstractItemView{{background:{t['bg_primary']};color:{t['text_primary']};selection-background-color:{t['accent']};}}")

def _ai_btn(text, bg, fg="#fff", border=None):
    b = QPushButton(text); b.setCursor(Qt.CursorShape.PointingHandCursor)
    b.setStyleSheet(f"QPushButton{{background:{bg};color:{fg};border:{('1px solid ' + border) if border else 'none'};border-radius:9px;"
                    f"padding:8px 18px;font-weight:600;font-size:13px;}}QPushButton:hover{{opacity:.9;}}")
    return b

class AIPermissionDialog(QDialog):
    """Asks before the AI does anything on this computer. Returns 'once', 'chat' or 'deny' (Esc / closing = deny)."""
    def __init__(self, parent, t, title, summary, details="", risk="medium", icon="🔐", warnings=(),
                 remember_label="", allow_text="Allow once"):
        super().__init__(parent)
        self.choice = "deny"
        self.setWindowTitle("SPS AI asks permission")
        self.setModal(True)
        self.setMinimumWidth(580)
        self.setStyleSheet(_ai_qss(t))
        col = {"low": t["success"], "medium": t["warning"], "high": t["danger"]}.get(risk, t["warning"])
        lay = QVBoxLayout(self); lay.setContentsMargins(20, 18, 20, 16); lay.setSpacing(10)
        top = QHBoxLayout()
        ic = QLabel(icon); ic.setStyleSheet("font-size:26px;")
        _tt_clean = re.sub(r'^[^\w<]+', '', title)
        tt = QLabel(f"<b style='font-size:15px'>{html.escape(_tt_clean)}</b>")
        badge = QLabel({"low": "LOW RISK", "medium": "ASKS FIRST", "high": "HIGH RISK"}.get(risk, "ASKS FIRST"))
        badge.setStyleSheet(f"background:{col};color:#fff;border-radius:8px;padding:3px 9px;font-size:10px;font-weight:800;")
        top.addWidget(ic); top.addWidget(tt, 1); top.addWidget(badge)
        lay.addLayout(top)
        s = QLabel(summary); s.setWordWrap(True); s.setTextFormat(Qt.TextFormat.RichText)
        lay.addWidget(s)
        for w in warnings:
            wl = QLabel("⚠️ " + w); wl.setWordWrap(True)
            wl.setStyleSheet(f"background:{t['bg_secondary']};color:{t['text_primary']};border-left:4px solid {t['warning']};padding:7px 9px;border-radius:6px;")
            lay.addWidget(wl)
        if details:
            box = QPlainTextEdit(); box.setReadOnly(True); box.setPlainText(details)
            box.setFont(QFont("Consolas" if platform.system() == "Windows" else "monospace", 10))
            box.setMaximumHeight(190); box.setMinimumHeight(70)
            lay.addWidget(box)
        row = QHBoxLayout(); row.setSpacing(8)
        deny = _ai_btn("Deny", t["bg_tertiary"], t["text_primary"], t["border"]); deny.setDefault(True); deny.setAutoDefault(True)
        deny.clicked.connect(lambda: self._done("deny"))
        row.addWidget(deny); row.addStretch(1)
        if remember_label:
            rb = _ai_btn(remember_label, t["bg_secondary"], t["text_primary"], t["border"])
            rb.clicked.connect(lambda: self._done("chat")); rb.setMinimumWidth(rb.sizeHint().width() + 6); row.addWidget(rb)
        ok = _ai_btn(allow_text, t["danger"] if risk == "high" else t["accent"])
        ok.clicked.connect(lambda: self._done("once")); ok.setAutoDefault(False); ok.setMinimumWidth(ok.sizeHint().width() + 6)
        row.addWidget(ok)
        lay.addLayout(row)
        deny.setFocus()

    def _done(self, c):
        self.choice = c; self.accept()

    @staticmethod
    def ask(parent, t, title, summary, details="", risk="medium", icon="🔐", warnings=(), remember_label="", allow_text="Allow once"):
        d = AIPermissionDialog(parent, t, title, summary, details, risk, icon, warnings, remember_label, allow_text)
        d.exec()
        return d.choice

class AITextDialog(QDialog):
    def __init__(self, parent, t, title, text, extra_buttons=()):
        super().__init__(parent)
        self.setWindowTitle(title); self.resize(660, 460); self.setStyleSheet(_ai_qss(t))
        lay = QVBoxLayout(self)
        box = QPlainTextEdit(); box.setReadOnly(True); box.setPlainText(text)
        box.setFont(QFont("Consolas" if platform.system() == "Windows" else "monospace", 10))
        lay.addWidget(box, 1)
        row = QHBoxLayout()
        for label, cb in extra_buttons:
            b = _ai_btn(label, t["bg_tertiary"], t["text_primary"], t["border"]); b.clicked.connect(cb); row.addWidget(b)
        row.addStretch(1)
        c = _ai_btn("Close", t["accent"]); c.clicked.connect(self.accept); row.addWidget(c)
        lay.addLayout(row)

class AISettingsDialog(QDialog):
    def __init__(self, panel):
        super().__init__(panel.mw)
        from PyQt6.QtWidgets import QDoubleSpinBox
        self.p = panel; t = panel.t; s = panel.cfg
        self.setWindowTitle("SPS AI — Settings"); self.setMinimumWidth(520); self.setStyleSheet(_ai_qss(t))
        # V33: resizable + maximizable window; settings scroll, Save/Cancel stay pinned at the bottom
        self.setWindowFlags(self.windowFlags() | Qt.WindowType.WindowMaximizeButtonHint | Qt.WindowType.WindowMinimizeButtonHint)
        self.setSizeGripEnabled(True)
        from PyQt6.QtWidgets import QScrollArea
        _outer = QVBoxLayout(self); _outer.setContentsMargins(8, 8, 8, 8); _outer.setSpacing(8)
        _scroll = QScrollArea(); _scroll.setWidgetResizable(True); _scroll.setFrameShape(QFrame.Shape.NoFrame)
        _inner = QWidget(); _scroll.setWidget(_inner); _outer.addWidget(_scroll, 1)
        lay = QVBoxLayout(_inner); lay.setSpacing(10)
        try:
            _scr = (panel.mw.screen() or QApplication.primaryScreen()).availableGeometry()
            self.resize(min(640, _scr.width() - 40), min(720, _scr.height() - 80))
        except Exception:
            self.resize(600, 600)
        form = QFormLayout(); form.setLabelAlignment(Qt.AlignmentFlag.AlignLeft)
        self.sbx = QCheckBox("Agent / Special: work inside the private sandbox without asking each time (your real files still ask)"); self.sbx.setChecked(s["sandbox_auto"])
        form.addRow(self.sbx)
        self.autoweb = QCheckBox("Search the web automatically when a question needs fresh information"); self.autoweb.setChecked(s["auto_web"])
        form.addRow(self.autoweb)
        self.level = QComboBox()
        self.level.addItems(["0 · Chat only — no files, no commands", "1 · Read-only — may look at files you allow",
                             "2 · Full — may also create / edit / run (asks every time)"])
        self.level.setCurrentIndex(int(s["os_level"]))
        form.addRow("Computer access:", self.level)
        self.steps = QSpinBox(); self.steps.setRange(1, 60); self.steps.setValue(s["max_steps"])
        form.addRow("Most steps per request:", self.steps)
        self.retries = QSpinBox(); self.retries.setRange(1, 30); self.retries.setValue(s["max_retries"])
        form.addRow("Retries after a failure:", self.retries)
        self.temp = QDoubleSpinBox(); self.temp.setRange(0.0, 1.5); self.temp.setSingleStep(0.05); self.temp.setValue(float(s["temperature"]))
        form.addRow("Creativity (0 = exact):", self.temp)
        self.maxtok = QSpinBox(); self.maxtok.setRange(128, 4096); self.maxtok.setSingleStep(128); self.maxtok.setValue(int(s["max_tokens"]))
        form.addRow("Longest answer (tokens):", self.maxtok)
        self.ctx = QSpinBox(); self.ctx.setRange(0, 16384); self.ctx.setSingleStep(512); self.ctx.setValue(int(s["ctx"]))
        self.ctx.setSpecialValueText("automatic"); form.addRow("Memory window (tokens):", self.ctx)
        ram = QLabel()
        try:
            import psutil
            ram.setText(f"{psutil.virtual_memory().available // 1048576} MB free / {psutil.virtual_memory().total // 1048576} MB total")
        except Exception:
            ram.setText("unknown")
        form.addRow("Available RAM:", ram)
        self.think = QCheckBox("Think step by step before answering (slower, better for maths and logic)"); self.think.setChecked(s["think"])
        form.addRow(self.think)
        self.hist = QCheckBox("Save my chats on this PC (so I can open old chats)"); self.hist.setChecked(s["save_history"])
        form.addRow(self.hist)
        self.net = QCheckBox("Allow internet tools for this session"); self.net.setChecked(panel._net_ok)
        form.addRow(self.net)
        lay.addLayout(form)
        lay.addWidget(QLabel("Your own instructions for the AI (optional):"))
        self.custom = QPlainTextEdit(); self.custom.setPlainText(s["custom"]); self.custom.setMaximumHeight(70)
        self.custom.setPlaceholderText("e.g. “Answer in Bengali.”  “Keep answers short.”  “I'm a student.”")
        lay.addWidget(self.custom)
        lay.addWidget(QLabel("Extra harmless programs the AI may run (comma separated, optional):"))
        self.extra = QLineEdit(s["extra_cmds"]); self.extra.setPlaceholderText("e.g. choco list, python --version  (dangerous ones stay blocked)")
        lay.addWidget(self.extra)
        info = QLabel(f"📁 AI folder: {html.escape(LOCAL_AI_SANDBOX_DIR)}<br>🗂️ Chats: {html.escape(panel.store.dir)}")
        info.setWordWrap(True); info.setStyleSheet(f"color:{t['text_secondary']};font-size:11px;")
        lay.addWidget(info)
        r1 = QHBoxLayout()
        for label, cb in (("📜 Activity log", panel._show_activity_log), ("🧠 Memory", panel._show_memory),
                          ("🔐 Revoke permissions", panel._revoke_grants), ("📂 AI folder", lambda: QDesktopServices.openUrl(QUrl.fromLocalFile(LOCAL_AI_SANDBOX_DIR)))):
            b = _ai_btn(label, t["bg_tertiary"], t["text_primary"], t["border"]); b.clicked.connect(cb); r1.addWidget(b)
        lay.addLayout(r1)
        r2 = QHBoxLayout(); r2.addStretch(1)
        c = _ai_btn("Cancel", t["bg_tertiary"], t["text_primary"], t["border"]); c.clicked.connect(self.reject)
        o = _ai_btn("Save", t["accent"]); o.clicked.connect(self.accept)
        r2.addWidget(c); r2.addWidget(o)
        mx = _ai_btn("⛶ Maximize", t["bg_tertiary"], t["text_primary"], t["border"])
        mx.clicked.connect(lambda: (self.showNormal(), mx.setText("⛶ Maximize")) if self.isMaximized() else (self.showMaximized(), mx.setText("🗗 Restore")))
        r2.insertWidget(0, mx)
        _outer.addLayout(r2)

    def apply(self):
        s = self.p.cfg
        s.update(sandbox_auto=self.sbx.isChecked(), auto_web=self.autoweb.isChecked(), os_level=self.level.currentIndex(), max_steps=self.steps.value(),
                 max_retries=self.retries.value(), temperature=float(self.temp.value()), max_tokens=self.maxtok.value(),
                 ctx=self.ctx.value(), think=self.think.isChecked(), save_history=self.hist.isChecked(),
                 custom=self.custom.toPlainText().strip()[:1500], extra_cmds=self.extra.text().strip()[:300])
        self.p._net_ok = self.net.isChecked()


