#  SPS AI V33 — Part D: tools  (each one is gated by: settings level → hard safety rules → your permission)
# ═══════════════════════════════════════════════════════════════
# kind: safe (no OS access) · browser (your browser data: asks once per chat) · net (internet: asks once per session)
#       os_read (reads files: asks, can remember per folder) · os_write / exec (changes things: asks EVERY time)
AI_TOOLS = {
    "calc":              dict(kind="safe",     icon="🧮", title="Calculate",          sig="calc(expr)", desc="exact maths, e.g. (12+8)*3"),
    "now":               dict(kind="safe",     icon="🕒", title="Date & time",        sig="now()", desc="the current date and time"),
    "get_setting":       dict(kind="safe",     icon="⚙️", title="Check setting",      sig="get_setting(name)", desc="whether a browser setting is on or off"),
    "recall":            dict(kind="safe",     icon="🧠", title="Memory",             sig="recall()", desc="facts the user asked you to remember"),
    "read_page":         dict(kind="browser",  icon="📄", title="Read page",          sig="read_page()", desc="the text of the page open in the browser"),
    "list_tabs":         dict(kind="browser",  icon="🗂️", title="List tabs",          sig="list_tabs()", desc="the open browser tabs"),
    "open_url":          dict(kind="browser",  icon="🔗", title="Open page",          sig="open_url(url)", desc="open a web page in a new tab"),
    "open_browser_page": dict(kind="browser",  icon="🪟", title="Open browser window", sig="open_browser_page(name)", desc="open settings, history, bookmarks, downloads, passwords, extensions, notes, flags …"),
    "set_setting":       dict(kind="browser",  icon="🎛️", title="Change setting",     sig='set_setting(name, value)', desc='turn a browser setting "on" or "off"', always_ask=True),
    "search_history":    dict(kind="browser",  icon="🕘", title="Search history",     sig="search_history(query)", desc="search the user's browsing history"),
    "list_bookmarks":    dict(kind="browser",  icon="⭐", title="Bookmarks",          sig="list_bookmarks()", desc="the user's bookmarks"),
    "remember":          dict(kind="browser",  icon="📝", title="Remember",           sig="remember(fact)", desc="remember a fact about the user for next time", always_ask=True),
    "web_search":        dict(kind="net",      icon="🔍", title="Web search",         sig="web_search(query)", desc="search the internet"),
    "fetch_url":         dict(kind="net",      icon="🌐", title="Read web page",      sig="fetch_url(url)", desc="read a public web page"),
    "image_gen":         dict(kind="net",      icon="🎨", title="Make image",         sig="image_gen(prompt)", desc="create an image"),
    "list_dir":          dict(kind="os_read",  icon="📁", title="List folder",        sig="list_dir(path)", desc="list the files in a folder"),
    "read_file":         dict(kind="os_read",  icon="📖", title="Read file",          sig="read_file(path, offset?)", desc="read a text file"),
    "find_files":        dict(kind="os_read",  icon="🔎", title="Find files",         sig="find_files(root, pattern)", desc='find files by name, e.g. "*.pdf"'),
    "open_path":         dict(kind="os_read",  icon="📂", title="Open file/folder",   sig="open_path(path)", desc="open a document, picture or folder in its normal app"),
    "clipboard_get":     dict(kind="os_read",  icon="📋", title="Read clipboard",     sig="clipboard_get()", desc="the text on the clipboard"),
    "write_file":        dict(kind="os_write", icon="✍️", title="Write file",         sig="write_file(path, content, append?)", desc="create or overwrite a text file (a relative path lives in your sandbox; the user gets it as a download card)"),
    "make_dir":          dict(kind="os_write", icon="🗂️", title="Create folder",      sig="make_dir(path)", desc="create a folder"),
    "copy_file":         dict(kind="os_write", icon="📑", title="Copy file",          sig="copy_file(src, dst)", desc="copy one file"),
    "move_file":         dict(kind="os_write", icon="🚚", title="Move file",          sig="move_file(src, dst)", desc="move or rename one file"),
    "delete_file":       dict(kind="os_write", icon="🗑️", title="Delete file",        sig="delete_file(path)", desc="move one file to the recoverable AI trash"),
    "clipboard_set":     dict(kind="os_write", icon="📋", title="Write clipboard",    sig="clipboard_set(text)", desc="put text on the clipboard"),
}
_AI_LEVEL_NEEDED = {"safe": 0, "browser": 0, "net": 0, "os_read": 1, "os_write": 2, "exec": 2}
_AI_SMALL_TOOLS = ("calc", "read_page", "web_search", "fetch_url", "open_url", "list_dir", "read_file", "write_file", "set_setting")
_AI_OPEN_OK_EXT = {".txt", ".md", ".pdf", ".doc", ".docx", ".xls", ".xlsx", ".ppt", ".pptx", ".csv", ".json", ".rtf", ".odt", ".ods",
                   ".png", ".jpg", ".jpeg", ".gif", ".webp", ".bmp", ".svg", ".mp3", ".wav", ".ogg", ".flac", ".mp4", ".mkv", ".webm", ".avi", ".mov", ".zip", ""}

_AI_MODE_KINDS = {"chat": {"safe", "browser", "net"}, "agent": {"safe", "browser", "net", "os_read", "os_write", "exec"},
                  "special": {"safe", "browser", "net", "os_read", "os_write", "exec"}, "think": set()}

def ai_tools_for(level, small=False, mode="agent"):
    kinds = _AI_MODE_KINDS.get(mode, set())
    names = [n for n, s in AI_TOOLS.items() if _AI_LEVEL_NEEDED[s["kind"]] <= level and s["kind"] in kinds]
    return [n for n in names if (not small or n in _AI_SMALL_TOOLS)]

def ai_tool_prompt(level, small=False, mode="agent"):
    names = ai_tools_for(level, small, mode)
    lines = [f"- {AI_TOOLS[n]['sig']} — {AI_TOOLS[n]['desc']}" for n in names]
    return "\n".join(lines)


class AIResult:
    def __init__(self, ok, text, status="ok", label="", decision="auto", image=None):
        self.ok = ok; self.text = text; self.status = status      # status: ok | error | denied | blocked
        self.label = label; self.decision = decision; self.image = image

