_KB = []
_KB_BY_KEY = {}

def _stem(w):
    for suf in ("ing", "ed", "es", "s"):
        if w.endswith(suf) and len(w) - len(suf) >= 3:
            return w[:-len(suf)]
    return w

_KB_STOP = set("a an the is are was were be to of in on for and or my me i you it this that can could would should do does did how what where when why which "
               "please help with from at as by your our any some turn off set use show make get want need like about into just "
               "sps spsbrowser sps-browser".split())

def _kb_tokens(s):
    return [_stem(w) for w in re.findall(r"[a-z0-9]+", (s or "").lower()) if w not in _KB_STOP and len(w) > 1]

def _kb_build():
    del _KB[:]; _KB_BY_KEY.clear()
    for key, label, desc, section in _KB_SETTINGS_RAW:
        e = {"id": "set:" + key, "kind": "setting", "title": label, "key": key, "section": section,
             "kw": [label.lower(), key.replace("_", " ")], "desc": desc,
             "w": {}, "tt": set(_kb_tokens(label))}
        _KB.append(e); _KB_BY_KEY[key] = e
    for fid, title, kw, body in _KB_FEATURES:
        _KB.append({"id": "feat:" + fid, "kind": "feature", "title": title, "kw": [k.lower() for k in kw],
                    "body": body, "w": {}, "tt": set(_kb_tokens(title))})
    # inverse-document-frequency weights
    df = {}
    for e in _KB:
        toks = set(_kb_tokens(e["title"])) | set(_kb_tokens(e.get("desc", ""))) | set(_kb_tokens(e.get("key", "").replace("_", " "))) \
               | {t for k in e["kw"] for t in _kb_tokens(k)}
        e["_all"] = toks
        for t in toks:
            df[t] = df.get(t, 0) + 1
    n = float(len(_KB))
    for e in _KB:
        w = {}
        for t in _kb_tokens(e.get("desc", "")): w[t] = max(w.get(t, 0), 0.6 * math.log(1 + n / df[t]))
        for t in _kb_tokens(e.get("key", "").replace("_", " ")): w[t] = max(w.get(t, 0), 1.2 * math.log(1 + n / df[t]))
        for k in e["kw"]:
            for t in _kb_tokens(k): w[t] = max(w.get(t, 0), 1.6 * math.log(1 + n / df[t]))
        for t in _kb_tokens(e["title"]): w[t] = max(w.get(t, 0), 2.2 * math.log(1 + n / df[t]))
        e["w"] = w
_kb_build()

_KB_WORDS = set()
def _kb_collect_words():
    _KB_WORDS.clear()
    for e in _KB:
        blob = " ".join([e.get("title", ""), e.get("desc", ""), e.get("key", "").replace("_", " "), " ".join(e.get("kw", []))])
        for w in re.findall(r"[a-z]{4,}", blob.lower()):
            _KB_WORDS.add(w)
_kb_collect_words()

# words people say -> the words the knowledge base uses
_KB_SYNONYMS = [
    (r"\b(gpu|graphics? card|video card|hw accel\w*)\b", "hardware acceleration"),
    (r"\bpop[- ]?ups?\b", "block popups"),
    (r"\b(vpn|socks|proxies)\b", "proxy"),
    (r"\b(ram|memory saver|sleeping tabs?|save memory)\b", "tab sleep"),
    (r"\b(auto ?play|autoplay)\b", "auto-play media"),
    (r"\bpicture[- ]in[- ]picture\b", "pip mode"),
    (r"\b(ad ?block(?:er|ing)?|block ads?)\b", "ad blocker"),
    (r"\b(cookies?)\b", "cookies"),
    (r"\b(incognito|private browsing|private window)\b", "private incognito"),
    (r"\b(dark theme|night mode)\b", "dark mode"),
    (r"\b(clear|delete) (?:my )?(?:browsing )?data\b", "clear data on exit"),
]

_KB_PRODUCT_NAME = re.compile(r"\b(?:sps\s+)?(?:web\s+)?browser(?:\s+pro)?\b|\bsps\s+pro\b|\bspsbrowser\b", re.I)

def _kb_fix_typos(query):
    """'accelaretion' -> 'acceleration' (only for words the knowledge base does not know)."""
    import difflib
    out = []
    for w in re.findall(r"[A-Za-z0-9']+|[^A-Za-z0-9']+", query or ""):
        lw = w.lower()
        if lw.isalpha() and len(lw) >= 6 and lw not in _KB_WORDS and lw not in _KB_STOP and _stem(lw) not in _KB_WORDS:
            m = difflib.get_close_matches(lw, _KB_WORDS, n=1, cutoff=0.8)
            if m:
                w = m[0]
        out.append(w)
    return "".join(out)

def _kb_prepare_query(query):
    q = _kb_fix_typos(query or "")
    extra = []
    for rx, phrase in _KB_SYNONYMS:
        if re.search(rx, q, re.I):
            extra.append(phrase)
    stripped = _KB_PRODUCT_NAME.sub(" ", q)   # "in sps browser" is not a question about the About page
    if _kb_tokens(stripped) or extra:         # something real is left -> use it
        q = stripped
    return (q + " " + " ".join(extra)).strip()   # else ("what is sps browser") keep the wording: it IS about the product

def kb_search(query, topn=4):
    query = _kb_prepare_query(query)
    q = " " + (query or "").lower() + " "
    qt = set(_kb_tokens(query))
    res = []
    for e in _KB:
        s = 0.0
        for ph in e["kw"]:
            if (" " + ph + " ") in q or (len(ph) > 3 and ph in q):
                s += 6 if " " in ph else 3.5
        for t in qt:
            s += e["w"].get(t, 0)
        if e["tt"] and e["tt"] <= qt:
            s += 5
        if s > 0:
            res.append((s, e))
    res.sort(key=lambda x: -x[0])
    return res[:topn]

_HELP_WORDS = re.compile(r"\b(how|where|what|which|setting|settings|option|options|enable|disable|turn|change|find|open|browser|sps|tab|tabs|menu|button|feature|shortcut|toggle|can i|is there|help)\b", re.I)

def _fmt_state(settings, key):
    if key in settings and isinstance(settings.get(key), bool):
        return "ON ✅" if settings[key] else "OFF ⛔"
    return None

def kb_render(entry, settings):
    if entry["kind"] == "setting":
        key = entry["key"]
        lines = [f"**{entry['title']}** — {entry['desc']}.",
                 f"📍 Where: ⚙️ **Settings → {entry['section']} → {entry['title']}**",
                 f"👉 To turn it **on** or **off**: open ⋮ → **Settings** → **{entry['section']}**, find **{entry['title']}** and switch it."]
        st = _fmt_state(settings, key)
        if st:
            lines.append(f"🔘 Right now it is **{st}**.")
        if sps_needs_restart(key):
            lines.append("🔄 This one needs a restart — SPS will offer to close and restart for you.")
        if key in _RISKY_SETTINGS:
            lines.append("🛡️ It protects you, so I'd keep it on unless a site truly doesn't work.")
        lines.append(f"\nWant me to change it? Say **“turn on {entry['title']}”** or **“turn off {entry['title']}”** — I'll ask you first.")
        return "\n".join(lines)
    body = entry["body"].replace("{DATA}", BASE_DATA_DIR).replace("{MODELS}", SHARED_MODELS_DIR)
    return f"**{entry['title']}**\n\n{body}"

def kb_answer(query, settings):
    """Returns (direct_markdown_or_None, context_text_for_model)."""
    res = kb_search(query, 4)
    if not res:
        return None, ""
    top, second = res[0][0], (res[1][0] if len(res) > 1 else 0)
    helpish = bool(_HELP_WORDS.search(query))
    direct = None
    if (top >= 11 and top >= 1.1 * second) or (helpish and top >= 8 and top >= 1.35 * second) or (top >= 12 and res[0][1]["kind"] == "feature"):
        direct = kb_render(res[0][1], settings)
        if len(res) > 1 and second >= 0.55 * top and res[1][1]["kind"] != res[0][1]["kind"]:
            direct += "\n\n---\n**Related:**\n\n" + kb_render(res[1][1], settings)
    ctx = []
    for s, e in res[:3]:
        if s >= 4:
            ctx.append(kb_render(e, settings))
    return direct, "\n\n".join(ctx)[:1800]

_ACTION_ON = re.compile(r"\b(?:turn|switch|set)\s+on\s+(.+)|\b(?:enable|activate)\s+(.+)", re.I)
_ACTION_OFF = re.compile(r"\b(?:turn|switch|set)\s+off\s+(.+)|\b(?:disable|deactivate)\s+(.+)", re.I)
_ACTION_ONOFF_TAIL = re.compile(r"\b(?:turn|switch)\s+(.+?)\s+(on|off)\b", re.I)

def kb_parse_toggle(text):
    """'turn off ad blocker' -> ('ad blocker', False). None if not a toggle request."""
    t = (text or "").strip().rstrip(".!?")
    m = _ACTION_ONOFF_TAIL.search(t)
    if m:
        return m.group(1), m.group(2).lower() == "on"
    m = _ACTION_ON.search(t)
    if m:
        return (m.group(1) or m.group(2)), True
    m = _ACTION_OFF.search(t)
    if m:
        return (m.group(1) or m.group(2)), False
    return None

def kb_find_setting(name):
    """Best matching boolean setting for a spoken name. Returns (entry, alternatives)."""
    name = re.sub(r"\b(the|my|please|setting|settings|option|feature|mode)\b", " ", name or "", flags=re.I)
    res = [(s, e) for s, e in kb_search(name, 6) if e["kind"] == "setting"]
    if not res or res[0][0] < 5.5:
        return None, [e for _s, e in res[:3]]
    if len(res) > 1 and res[1][0] >= 0.88 * res[0][0] and res[0][0] < 16:
        return None, [e for _s, e in res[:3]]
    return res[0][1], []

