# ═══════════════════════════════════════════════════════════════
#  RESTART ENGINE  (manual restart · settings restart · auto-restart on hang/lag)
# ═══════════════════════════════════════════════════════════════
_SPS_RESTARTING = False
_SPS_RESTART_LOCK = threading.Lock()
_PW_TOKEN = secrets.token_hex(12)          # secret shared only with the isolated password script

def _sps_gui_python():
    exe = sys.executable
    if platform.system() == "Windows" and exe.lower().endswith("python.exe"):
        w = exe[:-10] + "pythonw.exe"
        if os.path.exists(w):
            return w
    return exe

def _sps_sandbox_active():
    """True when this browser was started BY the SPS Sandbox (it sets these two variables)."""
    return os.environ.get("SPS_SANDBOX") == "1" and bool(os.environ.get("SPS_SANDBOX_RESTART_FILE"))

def _sps_find_sandbox_exe():
    """SPS_Browser.exe (the sandbox) that sits next to this browser's exe."""
    if getattr(sys, "frozen", False):
        d = os.path.dirname(os.path.abspath(sys.executable))
        for n in ("SPS_Browser.exe", "SPS_Browser"):
            p = os.path.join(d, n)
            if os.path.isfile(p) and os.path.abspath(p) != os.path.abspath(sys.executable):
                return p
    return ""

def _sps_request_sandbox_restart(cmd):
    """Ask the sandbox (our parent) to start the browser again - the browser never starts itself."""
    i = next((k for k, a in enumerate(cmd) if str(a).startswith("--")), len(cmd))
    path = os.environ["SPS_SANDBOX_RESTART_FILE"]
    os.makedirs(os.path.dirname(path), exist_ok=True)
    tmp = path + ".tmp"
    with open(tmp, "w", encoding="utf-8") as f:
        json.dump({"args": list(cmd[i:]), "time": time.time(), "pid": os.getpid()}, f)
    os.replace(tmp, path)

def _sps_build_restart_cmd(profile, reason):
    args, skip = [], False
    for a in sys.argv[1:]:
        if skip:
            skip = False; continue
        if a in ("--restarted", "--profile"):
            skip = True; continue
        if a == "--picker":
            continue
        if a.startswith("--"):
            args.append(a)
    args += ["--profile", profile, "--restarted", reason]
    if getattr(sys, "frozen", False):
        # Frozen: ALWAYS restart through the sandbox exe (never the bare browser exe).
        sb = _sps_find_sandbox_exe()
        return ([sb] if sb else [sys.executable]) + args
    return [_sps_gui_python(), os.path.abspath(sys.argv[0])] + args

def _sps_spawn_delayed(cmd, wait_pid, delay=2.0):
    """Start `cmd` AFTER process `wait_pid` has fully exited (so profile folders are unlocked)."""
    if _sps_sandbox_active():
        # Running under the sandbox: leave a restart request and exit; the sandbox relaunches us.
        _sps_request_sandbox_restart(cmd)
        return
    flags = 0
    if platform.system() == "Windows":
        flags = 0x00000008 | 0x00000200 | 0x08000000      # DETACHED | NEW_PROCESS_GROUP | NO_WINDOW
    kw = {"close_fds": True}
    if flags:
        kw["creationflags"] = flags
    if not getattr(sys, "frozen", False):
        code = ("import sys,time,json,subprocess\n"
                "pid=int(sys.argv[1]);cmd=json.loads(sys.argv[2]);d=float(sys.argv[3])\n"
                "try:\n"
                "    import psutil\n"
                "    t0=time.time()\n"
                "    def alive():\n"
                "        try: return psutil.Process(pid).status()!=psutil.STATUS_ZOMBIE\n"
                "        except Exception: return False\n"
                "    while alive() and time.time()-t0<30: time.sleep(0.3)\n"
                "except Exception:\n"
                "    time.sleep(4)\n"
                "time.sleep(d)\n"
                "subprocess.Popen(cmd,close_fds=True)\n")
        subprocess.Popen([_sps_gui_python(), "-c", code, str(wait_pid), json.dumps(cmd), str(delay)],
                         stdin=subprocess.DEVNULL, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL, **kw)
    elif platform.system() == "Windows":
        subprocess.Popen("cmd /c ping -n 4 127.0.0.1 >nul & " + subprocess.list2cmdline(cmd), shell=True,
                         stdin=subprocess.DEVNULL, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL, **kw)
    else:
        subprocess.Popen(["sh", "-c", 'sleep 3; exec "$@"', "sh"] + cmd,
                         stdin=subprocess.DEVNULL, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL, **kw)

def _sps_restart_log_path():
    return os.path.join(BASE_DATA_DIR, "restart_log.json")

def _sps_restart_allowed(max_in_window=3, window_sec=300):
    """Loop guard: never auto-restart more than 3 times in 5 minutes."""
    try:
        with open(_sps_restart_log_path(), encoding="utf-8") as f:
            stamps = [t for t in json.load(f) if time.time() - t < window_sec]
    except Exception:
        stamps = []
    return len(stamps) < max_in_window

def _sps_note_restart():
    try:
        try:
            with open(_sps_restart_log_path(), encoding="utf-8") as f:
                stamps = [t for t in json.load(f) if time.time() - t < 3600]
        except Exception:
            stamps = []
        stamps.append(time.time())
        with open(_sps_restart_log_path(), "w", encoding="utf-8") as f:
            json.dump(stamps, f)
    except Exception:
        pass

def _sps_chromium_flags_from_settings(s):
    """Turn saved settings into Chromium switches (they only take effect at start-up, hence 'restart required')."""
    flags, feats = [], []
    if not s.get("hardware_accel", True):
        flags += ["--disable-gpu", "--disable-gpu-compositing"]
    if s.get("flags_gpu_rasterization", False) and s.get("hardware_accel", True):
        flags.append("--enable-gpu-rasterization")
    if s.get("flags_zero_copy", False) and s.get("hardware_accel", True):
        flags.append("--enable-zero-copy")
    if s.get("flags_oop_rasterization", False) and s.get("hardware_accel", True):
        flags.append("--enable-oop-rasterization")
    if not s.get("flags_quic_protocol", True):
        flags.append("--disable-quic")
    if s.get("flags_force_dark_mode", False):
        feats.append("WebContentsForceDark")
    if s.get("proxy_enabled") and (s.get("proxy_host") or "").strip():
        flags.append(f"--proxy-server=http://{s['proxy_host'].strip()}:{int(s.get('proxy_port', 8080))}")
    if feats:
        flags.append("--enable-features=" + ",".join(feats))
    return " ".join(flags)

