    def _toggle_night_shift(self):
        sd = self.settings_data
        sd["night_shift_enabled"] = not sd.get("night_shift_enabled", False)
        self._apply_night_shift()
        self.status.showMessage("Night shift " + ("ON 🌙" if sd["night_shift_enabled"] else "OFF"), 2000)

    def _apply_night_shift(self):
        s2 = self.settings_data
        if not s2.get("night_shift_enabled", False):
            js = "(function(){var e=document.getElementById('_sps_ns');if(e)e.remove();})();"
        else:
            alpha = max(0, min(100, int(s2.get("night_shift_intensity", 50)))) / 200.0
            js = (f"(function(){{var e=document.getElementById('_sps_ns');"
                  f"if(!e){{e=document.createElement('div');e.id='_sps_ns';"
                  f"e.style.cssText='position:fixed;top:0;left:0;width:100vw;height:100vh;"
                  f"background:rgba(255,140,0,{alpha:.3f});pointer-events:none;z-index:2147483647;"
                  f"mix-blend-mode:multiply;';document.body.appendChild(e);}}"
                  f"e.style.background='rgba(255,140,0,{alpha:.3f})';}})()")
        for i in range(self.tabs.count()):
            w = self.tabs.widget(i)
            if w and hasattr(w, 'page'):
                try: w.page().runJavaScript(js)
                except Exception: pass

