    def _show_clipboard_history(self):
        t = self._theme
        if not hasattr(self, '_clipboard_ring'): self._clipboard_ring = []
        dlg = QDialog(self); dlg.setWindowTitle("📋 Clipboard History"); dlg.resize(480, 380)
        dlg.setStyleSheet(f"QDialog{{background:{t['bg_primary']};}}QLabel{{color:{t['text_primary']};}}")
        lay = QVBoxLayout(dlg)
        hdr = QLabel("📋 Clipboard History (last 20)")
        hdr.setStyleSheet(f"font-size:15px;font-weight:700;color:{t['accent']};padding:6px 0;")
        lay.addWidget(hdr)
        lst = QListWidget()
        lst.setStyleSheet(f"QListWidget{{background:{t['bg_secondary']};border:1px solid {t['border']};"
                          f"border-radius:10px;color:{t['text_primary']};font-size:13px;padding:4px;}}")
        for item in self._clipboard_ring:
            lst.addItem(item[:120] + ("…" if len(item) > 120 else ""))
        if not self._clipboard_ring:
            lst.addItem("(nothing copied yet)")
        lay.addWidget(lst, 1)
        def use_it():
            row = lst.currentRow()
            if 0 <= row < len(self._clipboard_ring):
                QApplication.clipboard().setText(self._clipboard_ring[row])
                self.status.showMessage("📋 Copied to clipboard", 1500); dlg.accept()
        row_btns = QHBoxLayout()
        ub = QPushButton("Use selected"); ub.clicked.connect(use_it)
        ub.setStyleSheet(f"background:{t['accent']};color:white;border-radius:8px;padding:7px 18px;font-weight:700;")
        cb = QPushButton("Close"); cb.clicked.connect(dlg.accept)
        cb.setStyleSheet(f"background:{t['bg_secondary']};color:{t['text_primary']};border:1px solid {t['border']};border-radius:8px;padding:7px 18px;")
        row_btns.addWidget(ub); row_btns.addWidget(cb)
        lay.addLayout(row_btns)
        dlg.exec()

    def _on_clipboard_change(self):
        text = QApplication.clipboard().text()
        if not text or not text.strip(): return
        if not hasattr(self, '_clipboard_ring'): self._clipboard_ring = []
        if self._clipboard_ring and self._clipboard_ring[0] == text: return
        self._clipboard_ring.insert(0, text)
        self._clipboard_ring = self._clipboard_ring[:int(self.settings_data.get("clipboard_history_max", 20))]


