        body_lbl = QLabel(steps[0][1])
        body_lbl.setWordWrap(True)
        body_lbl.setStyleSheet(f"font-size:13px;line-height:1.6;color:{t['text_primary']};")
        body_lbl.setAlignment(Qt.AlignmentFlag.AlignTop)
