        skip_btn = QPushButton("Skip Tour")
        skip_btn.setStyleSheet(f"QPushButton{{background:{t['bg_secondary']};color:{t['text_secondary']};border:1px solid {t['border']};border-radius:10px;padding:10px 20px;font-size:13px;}}"
                               f"QPushButton:hover{{background:{t['hover']};}}")
        skip_btn.clicked.connect(dlg.reject)

        prev_btn = QPushButton("← Back")
        prev_btn.setStyleSheet(f"QPushButton{{background:{t['bg_secondary']};color:{t['text_primary']};border:1px solid {t['border']};border-radius:10px;padding:10px 20px;font-size:13px;font-weight:600;}}"
                               f"QPushButton:hover{{background:{t['hover']};}}")
        prev_btn.setEnabled(False)

        next_btn = QPushButton("Next →")
        next_btn.setStyleSheet(f"QPushButton{{background:{t['accent']};color:white;border:none;border-radius:10px;padding:10px 24px;font-size:13px;font-weight:700;}}"
                               f"QPushButton:hover{{background:{t['accent']}dd;}}")
        next_btn.setDefault(True)

        btn_row.addWidget(skip_btn); btn_row.addStretch()
        btn_row.addWidget(prev_btn); btn_row.addWidget(next_btn)
        lay.addLayout(btn_row)

        def update_step():
            i = self._tour_step
            prog.setValue(i); step_lbl.setText(f"Step {i+1} of {total}")
            title_lbl.setText(steps[i][0]); body_lbl.setText(steps[i][1])
            prev_btn.setEnabled(i > 0)
            next_btn.setText("Finish! 🎉" if i == total-1 else "Next →")

        def go_next():
            if self._tour_step == total - 1:
                dlg.accept(); return
            self._tour_step += 1; update_step()

        def go_prev():
            if self._tour_step > 0:
                self._tour_step -= 1; update_step()

        next_btn.clicked.connect(go_next)
        prev_btn.clicked.connect(go_prev)
        dlg.exec()

