    def _show_add_extension(self):
        """Open the Extensions Manager directly on the Add Custom Script tab."""
        dlg = ExtensionsDialog(self.profile_name, self._theme, self.extension_manager, self)
        dlg.extensions_changed.connect(self._rebuild_extension_toolbar_buttons)
        # Switch to Add tab (index 1)
        try:
            for child in dlg.findChildren(QTabWidget):
                child.setCurrentIndex(1); break
        except Exception: pass
        dlg.exec()
        self._rebuild_extension_toolbar_buttons()

    def _run_extension(self, ext):
        """Execute a single extension's code in the current tab."""
        browser = self.tabs.currentWidget()
        if not browser: return
        code = ext.get("code", "")
        ext_type = ext.get("type", "JavaScript")
        if ext_type == "CSS":
            js = f"""(function(){{var s=document.createElement('style');s.textContent={json.dumps(code)};document.head.appendChild(s);}})();"""
            browser.page().runJavaScript(js)
        else:
            browser.page().runJavaScript(code)

    def _rebuild_extension_toolbar_buttons(self):
        """
        V28: Chrome-style extension toolbar.
        - 0 extensions: nothing shown.
        - 1 extension: show its icon directly in toolbar.
        - 2+ extensions: show single 🧩 puzzle button; click → overflow menu listing all.
        """
        # Remove old extension buttons/actions
        for btn in getattr(self, "_ext_toolbar_btns", []):
            try: self.toolbar.removeAction(btn)
            except: pass
        for btn in getattr(self, "_ext_toolbar_widgets", []):
            try: self.toolbar.removeWidget(btn); btn.deleteLater()
            except: pass
        self._ext_toolbar_btns = []
        self._ext_toolbar_widgets = []

        if not self.settings_data.get("extensions_toolbar_visible", True):
            return

        exts = self.extension_manager.get_toolbar_extensions()
        use_overflow = self.settings_data.get("ext_toolbar_overflow", True) and len(exts) >= 2

        def _make_ext_btn(icon_text, tooltip, slot, w=36, h=34):
            btn = QPushButton(icon_text)
            btn.setFixedSize(w, h)
            btn.setToolTip(tooltip)
            t = self._theme
            btn.setStyleSheet(
                f"QPushButton{{font-size:16px;background:{t['accent_light']};color:{t['accent']};"
                f"border:1px solid {t['accent']};border-radius:8px;padding:0;}}"
                f"QPushButton:hover{{background:{t['accent']};color:white;}}"
            )
            btn.clicked.connect(slot)
            return btn

        if use_overflow:
            # Single puzzle button
            def _show_overflow():
                menu = ExtensionOverflowMenu(exts, self._run_extension, self._theme, self)
                btn_widget = self._ext_toolbar_widgets[0] if self._ext_toolbar_widgets else None
                if btn_widget:
                    pos = btn_widget.mapToGlobal(btn_widget.rect().bottomLeft())
                    menu.exec(pos)
            puzzle_btn = _make_ext_btn("🧩", f"{len(exts)} Extensions — click to expand", _show_overflow, 38, 34)
            self.toolbar.insertWidget(self.menu_btn_action if hasattr(self,'menu_btn_action') else None, puzzle_btn)
            self._ext_toolbar_widgets.append(puzzle_btn)
        else:
            # Individual button per extension (0 or 1)
            for ext in exts:
                icon = ext.get("icon", "🧩")
                name = ext.get("name", "Ext")
                ext_ref = ext
                btn = _make_ext_btn(icon, f"{name}: {ext.get('description','')}", lambda checked=False, e=ext_ref: self._run_extension(e))
                self.toolbar.insertWidget(self.menu_btn_action if hasattr(self,'menu_btn_action') else None, btn)
                self._ext_toolbar_widgets.append(btn)

