    def _open_local_ai_panel(self, prompt=None):
        """Show (never toggle-hide) the SPS AI sidebar; optionally send a first question."""
        if not hasattr(self, "_ai_panel"):
            return
        if not self._ai_panel.isVisible():
            self._ai_panel.setVisible(True)
            sizes = self.splitter.sizes()
            total = sum(sizes) or self.width()
            self.splitter.setSizes([sizes[0], max(total - sizes[0] - 380, 400), 380])
        try:
            self._ai_panel.input_box.setFocus()
        except Exception:
            pass
        if prompt:
            QTimer.singleShot(250, lambda p=prompt: self._ai_panel._quick(p))

    def _toggle_local_ai_panel(self):
        if not hasattr(self, "_ai_panel"):
            return
        visible = self._ai_panel.isVisible()
        if not visible:
            self._open_local_ai_panel()
            return
        self._ai_panel.setVisible(False)
        sizes = self.splitter.sizes()
        self.splitter.setSizes([sizes[0], sizes[1] + sizes[2], 0])

    def _show_ai_hub(self):
        self._show_ai_menu()

    # ── First-run guided tour ─────────────────
    def _tour_steps(self):
        g = lambda *names: (lambda: [getattr(self, n, None) for n in names])
        def sidebar_t():
            sb = getattr(self, "sidebar", None)
            return [sb] if sb is not None and sb.isVisible() else [getattr(self, "sidebar_btn", None)]
        def page_t():
            try: return [self.tabs.currentWidget()]
            except Exception: return None
        def tabbar_t():
            try: return [self.tabs.tabBar()]
            except Exception: return None
        return [
            ("👋 Welcome to SPS Browser!",
             "Let's take a <b>quick 1-minute tour</b> so you know where everything is. "
             "You can use <b>Next</b> / <b>Back</b> (or the ← → keys) and skip any time with <b>Esc</b>.<br><br>"
             "Replay it later from <b>⋮ Menu → 🧭 Take the Tour</b>.", None),
            ("🏠 Your New Tab page",
             "Search the web, jump to your favourite sites, see recent pages and bookmarks, and open the "
             "<b>🤖 AI Chat</b> card to talk to your private on-device assistant.", page_t),
            ("🗂️ Tabs",
             "Every page opens in a tab. <b>Ctrl+T</b> new tab · <b>Ctrl+W</b> close · <b>Ctrl+Shift+T</b> reopen a closed tab · "
             "<b>Ctrl+Tab</b> switch tabs.", tabbar_t),
            ("📚 Sidebar",
             "One-click access to <b>Bookmarks, History, Downloads, Passwords, Notes, Extensions, Privacy Shield</b> and more. "
             "Show or hide it with <b>☰</b> or <b>Ctrl+B</b>.", sidebar_t),
            ("⬅ ➡ ↻ Navigation",
             "Go back, forward and reload (<b>Alt+←</b>, <b>Alt+→</b>, <b>Ctrl+R</b>). The 🏠 button returns to your home page.",
             g("back_btn", "fwd_btn", "reload_btn")),
            ("🔍 Address &amp; search bar",
             "Type a web address or a search. Click the search-engine button on the left to switch between "
             "<b>SPS Search, Google and DuckDuckGo</b>. Press <b>Ctrl+L</b> to jump here. "
             "Tip: type <b>@history</b>, <b>@downloads</b> or <b>@settings</b> for shortcuts.",
             g("engine_btn", "url_bar")),
            ("🔒 Site security",
             "The lock shows whether a site is secure. Click it for site info, connection details and permissions.",
             g("lock_btn")),
            ("🤖 SPS AI",
             "Ask questions, summarize the page you're reading, write code or emails. It runs <b>privately on your computer</b> "
             "and always asks before using the internet. Add a <i>.gguf</i> model to <b>local_ai/models</b> to activate it.",
             g("ai_btn")),
            ("📥 Download Manager",
             "Downloads open in a full manager with <b>live speed, time left, pause / resume / retry</b>, search and history. "
             "Open it any time with <b>Ctrl+J</b>.", None),
            ("⋮ The main menu",
             "Everything else lives here: <b>Settings, Passwords, Extensions, Privacy Dashboard, Reader Mode, Screenshot, "
             "Developer Tools, Workspaces, Security controls</b> and more.",
             g("menu_btn")),
            ("🎉 You're all set!",
             "Handy keys: <b>Ctrl+D</b> bookmark · <b>Ctrl+F</b> find · <b>Ctrl+H</b> history · <b>F12</b> dev tools · "
             "<b>F1</b> all shortcuts.<br><br>Enjoy browsing — safe, private and fast!", None),
        ]

    def start_tour(self, manual=True):
        old = getattr(self, "_tour", None)
        if old is not None:
            try: old.finish()
            except Exception: pass
        ov = TourOverlay(self, self._tour_steps(), self._theme, self._tour_done)
        self._tour = ov
        ov.setGeometry(self.rect()); ov.show(); ov.raise_(); ov.setFocus()

    def _tour_done(self):
        self._tour = None
        if not self.settings_data.get("tour_completed"):
            self.settings_data["tour_completed"] = True
            try: save_settings_to_disk(self.profile_name, self.settings_data)
            except Exception: pass
        try: self.status.showMessage("🧭 Tour finished — replay it any time from ⋮ Menu → Take the Tour", 6000)
        except Exception: pass

    def _start_tour_if_needed(self, tries=0):
        """Auto-start once on first open — waits for the welcome/name dialog and the window to be ready."""
        if self.settings_data.get("tour_completed") or getattr(self, "_tour", None) is not None:
            return
        busy = (QApplication.activeModalWidget() is not None) or (not self.isVisible()) or self.isMinimized()
        if busy and tries < 60:
            QTimer.singleShot(1000, lambda: self._start_tour_if_needed(tries + 1)); return
        self._safe_call(self.start_tour, False)

    def _safe_call(self, fn, *a):
        """Run a UI action; log + show a status message instead of letting an error kill the browser."""
        try:
            return fn(*a)
        except Exception as exc:
            _sps_log_exception(type(exc), exc, exc.__traceback__)
            try: self.status.showMessage(f"⚠️ Action failed: {exc}", 5000)
            except Exception: pass

