    def _auto_local_sync(self):
        """Auto-push bookmarks + history to shared sync store."""
        what = self.settings_data.get("local_sync_what", "bookmarks,history")
        if "bookmarks" in what:
            bm_path = os.path.join(self.profile_path, "bookmarks.json")
            if os.path.exists(bm_path):
                with open(bm_path, encoding="utf-8") as f: bm = json.load(f)
                self.local_sync.push_bookmarks(bm)
        if "history" in what:
            h_path = os.path.join(self.profile_path, "history.json")
            if os.path.exists(h_path):
                with open(h_path, encoding="utf-8") as f: hist = json.load(f)
                self.local_sync.push("history", hist)
        self.status.showMessage("🔄 Profile sync updated.", 2000)

