    # ── V28: Screenshot (enhanced) ────────────
    def take_full_page_screenshot(self):
        """Take a full-page (scrolled) screenshot via JS."""
        browser = self.tabs.currentWidget()
        if not browser: return
        t = self._theme
        path, _ = QFileDialog.getSaveFileName(self, "Save Full Page Screenshot",
            os.path.join(os.path.expanduser("~/Desktop"), "fullpage.png"),
            "PNG Images (*.png);;JPEG (*.jpg)")
        if not path: return
        browser.page().runJavaScript(
            """(function(){
                var canvas=document.createElement('canvas');
                canvas.width=document.body.scrollWidth;
                canvas.height=document.body.scrollHeight;
                var ctx=canvas.getContext('2d');
                ctx.drawWindow(window,0,0,document.body.scrollWidth,document.body.scrollHeight,'white');
                return canvas.toDataURL('image/png');
            })()""",
            lambda result: self._save_screenshot_data(result, path)
        )

    def _save_screenshot_data(self, data_url, path):
        if data_url and "base64," in data_url:
            b64 = data_url.split("base64,")[1]
            img_bytes = base64.b64decode(b64)
            with open(path, "wb") as f: f.write(img_bytes)
            self.status.showMessage(f"📸 Full-page screenshot saved: {path}", 3000)

