    # ── V29: Local File Editor ────────────────
    def open_local_file_editor(self, path=None):
        """Open any local file for viewing/editing — like VS Code lite."""
        if not path:
            path, _ = QFileDialog.getOpenFileName(
                self, "Open File", os.path.expanduser("~"),
                "All Files (*);;HTML (*.html *.htm);;Text (*.txt *.md *.py *.js *.css *.json *.xml *.csv)"
            )
        if not path or not os.path.isfile(path):
            return

        ext = os.path.splitext(path)[1].lower()

        # Media files — open in browser tab
        media_exts = {
            ".png",".jpg",".jpeg",".gif",".bmp",".webp",".svg",".ico",
            ".mp4",".webm",".avi",".mkv",".mov",".mp3",".wav",".ogg",".flac",
            ".pdf"
        }
        if ext in media_exts:
            self.add_new_tab(QUrl.fromLocalFile(path), os.path.basename(path))
            return

        # Text/code files — open in editor dialog
        t = self._theme
        dlg = QDialog(self)
        dlg.setWindowTitle(f"📝 {os.path.basename(path)}")
        dlg.resize(900, 640)
        dlg.setStyleSheet(f"background:{t['bg_primary']};color:{t['text_primary']};")
        lay = QVBoxLayout(dlg)

        # Header bar
        hbar = QHBoxLayout()
        path_lbl = QLabel(f"📄 {path}")
        path_lbl.setStyleSheet(f"font-size:11px;color:{t['text_secondary']};")
        hbar.addWidget(path_lbl, 1)
        size_lbl = QLabel(f"{os.path.getsize(path):,} bytes")
        size_lbl.setStyleSheet(f"font-size:11px;color:{t['text_secondary']};")
        hbar.addWidget(size_lbl)
        lay.addLayout(hbar)

        # Editor
        editor = QPlainTextEdit()
        editor.setStyleSheet(
            f"background:#0d1117;color:#c9d1d9;border:1px solid {t['border']};"
            "border-radius:8px;font-family:'Cascadia Code','Consolas','Courier New',monospace;"
            "font-size:13px;padding:8px;line-height:1.5;"
        )
        try:
            with open(path, "r", encoding="utf-8", errors="replace") as f:
                content = f.read()
            editor.setPlainText(content)
        except Exception as e:
            editor.setPlainText(f"Error reading file: {e}")
        lay.addWidget(editor, 1)

        # Status bar
        def _update_cursor():
            cur = editor.textCursor()
            status_lbl.setText(
                f"Line {cur.blockNumber()+1}, Col {cur.columnNumber()+1}  |  "
                f"{len(editor.toPlainText())} chars"
            )
        editor.cursorPositionChanged.connect(_update_cursor)
        status_lbl = QLabel(""); status_lbl.setStyleSheet(f"font-size:11px;color:{t['text_secondary']};")
        lay.addWidget(status_lbl)
        _update_cursor()

        # Buttons
        btn_row = QHBoxLayout()
        def _save():
            try:
                with open(path, "w", encoding="utf-8") as f:
                    f.write(editor.toPlainText())
                self.status.showMessage(f"💾 Saved: {path}", 3000)
                dlg.setWindowTitle(f"📝 {os.path.basename(path)}")
            except Exception as e:
                QMessageBox.critical(dlg, "Save Error", str(e))
        def _save_as():
            new_path, _ = QFileDialog.getSaveFileName(dlg, "Save As", path)
            if new_path:
                try:
                    with open(new_path, "w", encoding="utf-8") as f:
                        f.write(editor.toPlainText())
                    self.status.showMessage(f"💾 Saved as: {new_path}", 3000)
                except Exception as e:
                    QMessageBox.critical(dlg, "Save Error", str(e))
        def _open_in_browser():
            self.add_new_tab(QUrl.fromLocalFile(path), os.path.basename(path))
        def _word_wrap():
            if editor.lineWrapMode() == QPlainTextEdit.LineWrapMode.NoWrap:
                editor.setLineWrapMode(QPlainTextEdit.LineWrapMode.WidgetWidth)
            else:
                editor.setLineWrapMode(QPlainTextEdit.LineWrapMode.NoWrap)

        for label, fn, color in [
            ("💾 Save",       _save,           t["accent"]),
            ("💾 Save As…",   _save_as,        t["bg_secondary"]),
            ("🌐 Open in Tab",_open_in_browser, t["bg_secondary"]),
            ("↕ Wrap",        _word_wrap,       t["bg_secondary"]),
            ("✕ Close",       dlg.reject,       t["bg_secondary"]),
        ]:
            b = QPushButton(label)
            b.setStyleSheet(
                f"background:{color};color:{'white' if color==t['accent'] else t['text_primary']};"
                f"border-radius:8px;padding:8px 14px;font-size:13px;"
                f"border:1px solid {t['border']};"
            )
            b.clicked.connect(fn)
            btn_row.addWidget(b)
        lay.addLayout(btn_row)

        # Mark modified
        editor.textChanged.connect(lambda: dlg.setWindowTitle(f"📝 {os.path.basename(path)} •"))
        dlg.exec()

    # ── V29: Register as default browser + file handler ──────
    def _register_file_associations(self):
        """Register SPS Browser for 'Open With' context menu on Windows."""
        if platform.system() != "Windows":
            self.status.showMessage("File association registration is Windows-only.", 3000)
            return
        try:
            import winreg
            exe = (_sps_find_sandbox_exe() or sys.executable) if getattr(sys, "frozen", False) else os.path.abspath(sys.argv[0])   # frozen: always the SANDBOX exe
            exe_quoted = f'"{exe}"'

            # Extensions to register
            exts = [
                ".html", ".htm", ".xhtml",
                ".png", ".jpg", ".jpeg", ".gif", ".webp", ".bmp", ".svg",
                ".mp4", ".webm", ".mp3", ".wav", ".ogg",
                ".pdf", ".txt", ".md", ".json", ".xml", ".csv",
                ".py", ".js", ".css",
            ]
            prog_id = "SPSBrowser.Document"

            # Register ProgID
            with winreg.CreateKey(winreg.HKEY_CURRENT_USER,
                                  rf"Software\Classes\{prog_id}") as k:
                winreg.SetValueEx(k, "", 0, winreg.REG_SZ, "SPS Browser Document")
            with winreg.CreateKey(winreg.HKEY_CURRENT_USER,
                                  rf"Software\Classes\{prog_id}\shell\open\command") as k:
                winreg.SetValueEx(k, "", 0, winreg.REG_SZ, f'{exe_quoted} "%1"')

            # Register each extension
            for ext in exts:
                try:
                    with winreg.CreateKey(winreg.HKEY_CURRENT_USER,
                                          rf"Software\Classes\{ext}\OpenWithProgids") as k:
                        winreg.SetValueEx(k, prog_id, 0, winreg.REG_NONE, b"")
                except Exception:
                    pass

            # Notify Windows to refresh associations
            try:
                import ctypes
                SHCNE_ASSOCCHANGED = 0x08000000
                SHCNF_IDLIST       = 0x0000
                ctypes.windll.shell32.SHChangeNotify(SHCNE_ASSOCCHANGED, SHCNF_IDLIST, None, None)
            except Exception:
                pass

            QMessageBox.information(
                self, "✅ File Associations Registered",
                "SPS Browser is now available in the 'Open With' menu for:\n"
                ".html .htm .png .jpg .gif .pdf .mp4 .mp3 .txt .json .md .py .js .css\n\n"
                "Right-click any file → Open With → SPS Browser"
            )
        except Exception as e:
            QMessageBox.critical(self, "Registration Error", str(e))

